  -- Add image_fingerprint
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'image_fingerprint') then
    alter table products add column image_fingerprint jsonb;
  end if;

  -- Add image_urls array
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'image_urls') then
    alter table products add column image_urls text[] not null default array[]::text[];
  end if;

  -- Add description
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'description') then
    alter table products add column description text;
  end if;

  -- Add category (enum/text)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'category') then
    alter table products add column category text not null default 'other';
  end if;

  -- Add category_id (FK to categories table)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'category_id') then
    alter table products add column category_id uuid;
  end if;

  -- Add category_name (resolved name)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'category_name') then
    alter table products add column category_name text;
  end if;

  -- Add brand reference
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'brand_id') then
    alter table products add column brand_id uuid references public.product_brands(id) on delete set null;
  end if;

  if not exists (
    select 1
      from pg_constraint
     where conrelid = 'public.products'::regclass
       and conname = 'products_brand_id_fkey'
  ) then
    alter table products
      add constraint products_brand_id_fkey
        foreign key (brand_id) references public.product_brands(id) on delete set null;
  end if;

  -- Add brand
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'brand') then
    alter table products add column brand text;
  end if;

  -- Add model
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'model') then
    alter table products add column model text;
  end if;

  -- Add specifications (jsonb)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'specifications') then
    alter table products add column specifications jsonb not null default '{}'::jsonb;
  end if;

	  -- Add supplier relationship
	  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'supplier_id') then
	    -- FK added later after suppliers table exists (bootstrap-safe).
	    alter table products add column supplier_id uuid;
	  end if;

	  -- Add supplier_name (resolved name, kept in sync by triggers)
	  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'supplier_name') then
	    alter table products add column supplier_name text;
	  end if;

	  -- Add supplier reference codes
	  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'supplier_reference') then
	    alter table products add column supplier_reference text;
	  end if;

  -- Add supplier code (Código Proveedor for this specific supplier)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'supplier_code') then
    alter table products add column supplier_code text;
  end if;

  -- Add manufacturer metadata
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'manufacturer') then
    alter table products add column manufacturer text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'manufacturer_sku') then
    alter table products add column manufacturer_sku text;
  end if;

  -- Add international product identifiers
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'gtin') then
    alter table products add column gtin text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'hs_code') then
    alter table products add column hs_code text;
  end if;

  -- Add origin and variant attributes
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'country_of_origin') then
    alter table products add column country_of_origin text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'color') then
    alter table products add column color text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'size') then
    alter table products add column size text;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'material') then
    alter table products add column material text;
  end if;

  -- Add dimensional data
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'dimensions') then
    alter table products add column dimensions jsonb not null default '{}'::jsonb;
  end if;

  -- Add warranty and lifecycle controls
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'warranty_months') then
    alter table products add column warranty_months integer not null default 0;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'lifecycle_status') then
    alter table products add column lifecycle_status text not null default 'active';
  end if;

  -- Add tracking flags
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'serialized') then
    alter table products add column serialized boolean not null default false;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'lot_tracking') then
    alter table products add column lot_tracking boolean not null default false;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'expiration_tracking') then
    alter table products add column expiration_tracking boolean not null default false;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'expiry_days') then
    alter table products add column expiry_days integer;
  end if;

  -- Add planning attributes
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'lead_time_days') then
    alter table products add column lead_time_days integer not null default 0;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'reorder_quantity') then
    alter table products add column reorder_quantity integer not null default 0;
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'warehouse_location') then
    alter table products add column warehouse_location text;
  end if;

  -- Add pricing metadata
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'price_currency') then
    alter table products add column price_currency text not null default 'CLP';
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'cost_currency') then
    alter table products add column cost_currency text not null default 'CLP';
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'tax_rate') then
    alter table products add column tax_rate numeric(5,2);
  end if;

  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'is_published') then
    alter table products add column is_published boolean not null default true;
  end if;

  -- Add is_google_merchant (requires is_published to be true)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'is_google_merchant') then
    alter table products add column is_google_merchant boolean not null default false;
  end if;

  -- Add tags array
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'tags') then
    alter table products add column tags text[] not null default array[]::text[];
  end if;

  -- Add unit
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'unit') then
    alter table products add column unit text not null default 'unit';
  end if;

  -- Add weight
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'weight') then
    alter table products add column weight numeric(10,2) not null default 0;
  end if;

  -- Add track_stock
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'track_stock') then
    alter table products add column track_stock boolean not null default true;
  end if;

  -- Add purchase_treatment (inventory vs workshop consumable)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'purchase_treatment') then
    alter table products add column purchase_treatment text not null default 'inventory';
  end if;

  -- Add is_active
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'is_active') then
    alter table products add column is_active boolean not null default true;
  end if;

  -- Add product_type (product or service)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'product_type') then
    alter table products add column product_type text not null default 'product';
  end if;

  -- Add is_service (computed from product_type, for inventory triggers)
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'is_service') then
    alter table products add column is_service boolean not null default false;
  end if;

  -- Sync is_service with product_type for existing records
  update products set is_service = (product_type = 'service') where is_service != (product_type = 'service');

  -- Add updated_at
  if not exists (select 1 from information_schema.columns where table_name = 'products' and column_name = 'updated_at') then
    alter table products add column updated_at timestamp with time zone not null default now();
  end if;

  -- Normalize existing brands into product_brands table and backfill brand_id
  with normalized_brands as (
    select lower(btrim(brand)) as normalized_name,
           min(btrim(brand)) as canonical_name
      from products
     where brand is not null
       and btrim(brand) <> ''
     group by lower(btrim(brand))
  )
  insert into product_brands (name, created_at, updated_at)
  select canonical_name, now(), now()
    from normalized_brands nb
   where not exists (
     select 1
       from product_brands pb
      where lower(pb.name) = nb.normalized_name
   );

  update products p
     set brand_id = pb.id
    from product_brands pb
   where p.brand_id is null
     and p.brand is not null
     and btrim(p.brand) <> ''
     and lower(pb.name) = lower(btrim(p.brand));

  update products p
     set brand = pb.name
    from product_brands pb
   where p.brand_id = pb.id
     and (p.brand is distinct from pb.name);

  -- Sync inventory_qty to stock_quantity for existing records
  update products set stock_quantity = inventory_qty where stock_quantity = 0 and inventory_qty > 0;

  -- Services must never track stock (backfill existing rows)
  update products
     set is_service = true,
       purchase_treatment = 'inventory',
         track_stock = false,
         inventory_qty = 0,
         stock_quantity = 0,
         min_stock_level = 0,
         max_stock_level = 0
   where product_type = 'service'
     and (
       is_service is distinct from true
       or track_stock is distinct from false
       or coalesce(inventory_qty, 0) <> 0
       or coalesce(stock_quantity, 0) <> 0
       or coalesce(min_stock_level, 0) <> 0
       or coalesce(max_stock_level, 0) <> 0
     );

  -- Legacy compatibility: non-service products that don't track stock
  -- are treated as workshop consumables by default.
  update products
     set purchase_treatment = 'workshop_consumable'
   where product_type = 'product'
     and coalesce(track_stock, true) = false
     and greatest(coalesce(inventory_qty, 0), coalesce(stock_quantity, 0)) = 0
     and coalesce(purchase_treatment, 'inventory') = 'inventory';
end $$;

-- Keep service flags consistent even if callers forget.
create or replace function public.sync_product_service_flags()
returns trigger
language plpgsql
as $$
declare
  v_old_tracks_inventory boolean := false;
  v_new_tracks_inventory boolean := false;
  v_existing_stock integer := 0;
begin
  if NEW.product_type is null then
    NEW.product_type := 'product';
  end if;

  if NEW.purchase_treatment is null or
     NEW.purchase_treatment not in ('inventory', 'workshop_consumable') then
    NEW.purchase_treatment := 'inventory';
  end if;

  NEW.is_service := (NEW.product_type = 'service');

  if TG_OP = 'UPDATE' then
    v_old_tracks_inventory :=
      coalesce(OLD.product_type, 'product') <> 'service'
      and coalesce(OLD.purchase_treatment, 'inventory') = 'inventory'
      and coalesce(OLD.track_stock, true) = true;

    v_new_tracks_inventory :=
      NEW.product_type <> 'service'
      and NEW.purchase_treatment = 'inventory'
      and coalesce(NEW.track_stock, true) = true;

    v_existing_stock := greatest(
      coalesce(OLD.inventory_qty, 0),
      coalesce(OLD.stock_quantity, 0)
    );

    if v_old_tracks_inventory
       and not v_new_tracks_inventory
       and v_existing_stock > 0 then
      raise exception
        'No se puede desactivar el control de inventario para el producto % mientras tenga stock (% unidades).',
        coalesce(NEW.name, OLD.name, 'sin nombre'),
        v_existing_stock
        using errcode = 'check_violation',
              hint = 'Primero deja el stock en 0 y reclasifica el valor contable antes de cambiarlo a consumible de taller o servicio.';
    end if;
  end if;

  if NEW.is_service then
    NEW.purchase_treatment := 'inventory';
    NEW.track_stock := false;
    NEW.inventory_qty := 0;
    NEW.stock_quantity := 0;
    NEW.min_stock_level := 0;
    NEW.max_stock_level := 0;
  elsif NEW.purchase_treatment = 'workshop_consumable' then
    NEW.track_stock := false;
    NEW.inventory_qty := 0;
    NEW.stock_quantity := 0;
    NEW.min_stock_level := 0;
    NEW.max_stock_level := 0;
  end if;

  return NEW;
end;
$$;

drop trigger if exists trg_sync_product_service_flags on products;
create trigger trg_sync_product_service_flags
  before insert or update of product_type, purchase_treatment, is_service, track_stock, inventory_qty, stock_quantity, min_stock_level, max_stock_level
  on products
  for each row
  execute function public.sync_product_service_flags();

create or replace function public.convert_product_inventory_to_non_stock(
  p_product_id uuid,
  p_target_purchase_treatment text default 'workshop_consumable',
  p_target_product_type text default 'product',
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products;
  v_target_purchase_treatment text := coalesce(nullif(p_target_purchase_treatment, ''), 'inventory');
  v_target_product_type text := coalesce(nullif(p_target_product_type, ''), 'product');
  v_existing_stock integer := 0;
  v_inventory_value numeric(14,2) := 0;
  v_effective_reason text;
  v_description text;
  v_reference text;
  v_inventory_account_id uuid;
  v_workshop_consumables_account_id uuid;
  v_entry_id uuid;
  v_original_state jsonb;
  v_original_product_snapshot jsonb;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  if v_target_purchase_treatment not in ('inventory', 'workshop_consumable') then
    raise exception 'Invalid target purchase_treatment: %', v_target_purchase_treatment;
  end if;

  if v_target_product_type not in ('product', 'service') then
    raise exception 'Invalid target product_type: %', v_target_product_type;
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   for update;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  if coalesce(v_product.product_type, 'product') = 'service'
     or coalesce(v_product.purchase_treatment, 'inventory') <> 'inventory'
     or coalesce(v_product.track_stock, true) = false then
    raise exception 'Product % is not currently a stock-tracked inventory item', v_product.name;
  end if;

  if v_target_product_type = 'product'
     and v_target_purchase_treatment = 'inventory' then
    raise exception 'Target state still tracks inventory; conversion is not required';
  end if;

  v_existing_stock := greatest(
    coalesce(v_product.inventory_qty, 0),
    coalesce(v_product.stock_quantity, 0)
  );

  if v_existing_stock <= 0 then
    raise exception 'Product % has no stock to convert', v_product.name;
  end if;

  v_inventory_value := round(v_existing_stock * greatest(coalesce(v_product.cost, 0), 0), 2);
  v_effective_reason := coalesce(
    nullif(trim(p_reason), ''),
    case
      when v_target_product_type = 'service' then 'Conversión de inventario a servicio'
      else 'Conversión de inventario a consumible de taller'
    end
  );
  v_description := format('%s - %s', v_effective_reason, v_product.name);
  v_reference := format('product_conversion:%s:%s', v_product.id, extract(epoch from clock_timestamp())::bigint);
  v_original_state := jsonb_build_object(
    'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
    'product_type', coalesce(v_product.product_type, 'product'),
    'track_stock', coalesce(v_product.track_stock, true),
    'inventory_qty', coalesce(v_product.inventory_qty, 0),
    'stock_quantity', coalesce(v_product.stock_quantity, 0),
    'min_stock_level', coalesce(v_product.min_stock_level, 0),
    'max_stock_level', coalesce(v_product.max_stock_level, 0)
  );
  v_original_product_snapshot := to_jsonb(v_product);

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  update public.products
     set inventory_qty = 0,
         stock_quantity = 0,
         updated_at = now()
   where id = v_product.id;

  insert into public.stock_adjustments (
    tenant_id,
    product_id,
    adjustment_type,
    quantity,
    stock_before,
    stock_after,
    reason,
    reference,
    created_by,
    created_at
  ) values (
    v_product.tenant_id,
    v_product.id,
    'correction',
    -v_existing_stock,
    v_existing_stock,
    0,
    v_effective_reason,
    v_reference,
    auth.uid(),
    now()
  );

  if v_inventory_value > 0 then
    v_inventory_account_id := public.ensure_account(
      v_product.tenant_id,
      '1105',
      'Inventarios',
      'asset',
      'currentAsset',
      'Valor del inventario de productos',
      null
    );

    v_workshop_consumables_account_id := public.ensure_account(
      v_product.tenant_id,
      '5101',
      'Consumibles de Taller',
      'expense',
      'costOfGoodsSold',
      'Materiales y consumibles de uso rápido aplicados directamente en el taller',
      null
    );

    v_entry_id := gen_random_uuid();

    insert into public.journal_entries (
      id,
      tenant_id,
      entry_number,
      entry_date,
      description,
      type,
      source_module,
      source_reference,
      status,
      total_debit,
      total_credit,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_product.tenant_id,
      public.get_next_document_number(v_product.tenant_id, 'journal_entry'),
      now(),
      v_description,
      'adjustment',
      'product_conversion',
      v_product.id::text,
      'posted',
      v_inventory_value,
      v_inventory_value,
      now(),
      now()
    );

    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_workshop_consumables_account_id,
      v_product.tenant_id,
      '5101',
      'Consumibles de Taller',
      v_description,
      v_inventory_value,
      0,
      now(),
      now()
    );

    insert into public.journal_lines (
      id,
      entry_id,
      account_id,
      tenant_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_entry_id,
      v_inventory_account_id,
      v_product.tenant_id,
      '1105',
      'Inventarios',
      v_description,
      0,
      v_inventory_value,
      now(),
      now()
    );
  end if;

  update public.products
     set purchase_treatment = v_target_purchase_treatment,
         product_type = v_target_product_type,
         updated_at = now()
   where id = v_product.id
   returning * into v_product;

  insert into public.user_activity_log (
    tenant_id,
    user_id,
    action,
    details,
    performed_by,
    created_at
  ) values (
    v_product.tenant_id,
    auth.uid(),
    'product_conversion',
    jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'conversion_reference', v_reference,
      'conversion_reason', v_effective_reason,
      'target_purchase_treatment', v_target_purchase_treatment,
      'target_product_type', v_target_product_type,
      'converted_quantity', v_existing_stock,
      'inventory_value', v_inventory_value,
      'journal_entry_id', v_entry_id,
      'original_state', v_original_state,
      'original_product_snapshot', v_original_product_snapshot,
      'converted_state', jsonb_build_object(
        'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
        'product_type', coalesce(v_product.product_type, 'product'),
        'track_stock', coalesce(v_product.track_stock, true),
        'inventory_qty', coalesce(v_product.inventory_qty, 0),
        'stock_quantity', coalesce(v_product.stock_quantity, 0),
        'min_stock_level', coalesce(v_product.min_stock_level, 0),
        'max_stock_level', coalesce(v_product.max_stock_level, 0)
      ),
      'restored', false
    ),
    auth.uid(),
    now()
  );

  perform set_config('app.skip_stock_adjustment_trigger', '', true);

  return jsonb_build_object(
    'product', to_jsonb(v_product),
    'converted_quantity', v_existing_stock,
    'inventory_value', v_inventory_value,
    'reference', v_reference,
    'journal_entry_id', v_entry_id
  );
exception
  when others then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    raise;
end;
$$;

grant execute on function public.convert_product_inventory_to_non_stock(uuid, text, text, text) to authenticated;

create or replace function public.restore_product_conversion_state(
  p_product_id uuid,
  p_reason text default null,
  p_restore_inventory boolean default false,
  p_conversion_reference text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products;
  v_log public.user_activity_log;
  v_original_state jsonb;
  v_restore_reason text;
  v_restore_reference text;
  v_original_purchase_treatment text;
  v_original_product_type text;
  v_original_track_stock boolean;
  v_original_inventory_qty integer := 0;
  v_original_stock_qty integer := 0;
  v_original_min_stock integer := 0;
  v_original_max_stock integer := 0;
  v_inventory_value numeric(14,2) := 0;
  v_blocking_activity_count integer := 0;
  v_inventory_account_id uuid;
  v_workshop_consumables_account_id uuid;
  v_entry_id uuid;
  v_restored_inventory_qty integer := 0;
  v_restored_stock_qty integer := 0;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   for update;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  select *
    into v_log
    from public.user_activity_log
   where tenant_id = v_product.tenant_id
     and action = 'product_conversion'
     and details->>'product_id' = v_product.id::text
     and coalesce((details->>'restored')::boolean, false) = false
     and (
       p_conversion_reference is null
       or details->>'conversion_reference' = p_conversion_reference
     )
   order by created_at desc
   limit 1
   for update;

  if not found then
    raise exception 'No unreversed product conversion snapshot found for product %', v_product.name;
  end if;

  v_original_state := v_log.details->'original_state';

  if v_original_state is null then
    raise exception 'The selected conversion does not contain a reversible snapshot';
  end if;

  v_original_purchase_treatment := coalesce(v_original_state->>'purchase_treatment', 'inventory');
  v_original_product_type := coalesce(v_original_state->>'product_type', 'product');
  v_original_track_stock := coalesce((v_original_state->>'track_stock')::boolean, true);
  v_original_inventory_qty := coalesce((v_original_state->>'inventory_qty')::integer, 0);
  v_original_stock_qty := coalesce((v_original_state->>'stock_quantity')::integer, 0);
  v_original_min_stock := coalesce((v_original_state->>'min_stock_level')::integer, 0);
  v_original_max_stock := coalesce((v_original_state->>'max_stock_level')::integer, 0);
  v_inventory_value := coalesce((v_log.details->>'inventory_value')::numeric, 0);
  v_restore_reason := coalesce(
    nullif(trim(p_reason), ''),
    'Restauración de estado original del producto'
  );
  v_restore_reference := format(
    'product_restore:%s:%s',
    v_product.id,
    extract(epoch from clock_timestamp())::bigint
  );

  if p_restore_inventory then
    select case
             when exists (
               select 1
                 from public.stock_adjustments sa
                where sa.tenant_id = v_product.tenant_id
                  and sa.product_id = v_product.id
                  and sa.created_at > v_log.created_at
                  and coalesce(sa.reference, '') <> coalesce(v_log.details->>'conversion_reference', '')
             ) then 1
             when exists (
               select 1
                 from public.stock_movements sm
                where sm.tenant_id = v_product.tenant_id
                  and sm.product_id = v_product.id
                  and sm.created_at > v_log.created_at
             ) then 1
             when exists (
               select 1
                 from public.sales_invoices si
                 cross join lateral jsonb_array_elements(coalesce(si.items, '[]'::jsonb)) item
                where si.tenant_id = v_product.tenant_id
                  and si.created_at > v_log.created_at
                  and lower(coalesce(si.status, 'draft')) not in (
                    'draft','borrador',
                    'sent','enviado','enviada','issued','emitido','emitida',
                    'cancelled','cancelado','cancelada','anulado','anulada'
                  )
                  and nullif(item->>'product_id', '')::uuid = v_product.id
             ) then 1
             when exists (
               select 1
                 from public.purchase_invoices pi
                 cross join lateral jsonb_array_elements(coalesce(pi.items, '[]'::jsonb)) item
                where pi.tenant_id = v_product.tenant_id
                  and pi.created_at > v_log.created_at
                  and pi.status not in ('draft', 'cancelled')
                  and nullif(item->>'product_id', '')::uuid = v_product.id
             ) then 1
             else 0
           end
      into v_blocking_activity_count;

    if v_blocking_activity_count > 0 then
      raise exception
        'No es seguro restaurar stock/valor para el producto % porque hubo actividad después de la conversión.',
        v_product.name
        using errcode = 'check_violation',
              hint = 'Restaura solo la configuración con p_restore_inventory = false, o revisa manualmente compras/ventas posteriores.';
    end if;
  end if;

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  v_restored_inventory_qty := case when p_restore_inventory then v_original_inventory_qty else 0 end;
  v_restored_stock_qty := case when p_restore_inventory then v_original_stock_qty else 0 end;

  update public.products
     set purchase_treatment = v_original_purchase_treatment,
         product_type = v_original_product_type,
         track_stock = v_original_track_stock,
         inventory_qty = v_restored_inventory_qty,
         stock_quantity = v_restored_stock_qty,
         min_stock_level = v_original_min_stock,
         max_stock_level = v_original_max_stock,
         updated_at = now()
   where id = v_product.id
   returning * into v_product;

  if p_restore_inventory and v_original_inventory_qty > 0 then
    insert into public.stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by,
      created_at
    ) values (
      v_product.tenant_id,
      v_product.id,
      'correction',
      v_original_inventory_qty,
      0,
      v_original_inventory_qty,
      v_restore_reason,
      v_restore_reference,
      auth.uid(),
      now()
    );

    if v_inventory_value > 0 then
      v_inventory_account_id := public.ensure_account(
        v_product.tenant_id,
        '1105',
        'Inventarios',
        'asset',
        'currentAsset',
        'Valor del inventario de productos',
        null
      );

      v_workshop_consumables_account_id := public.ensure_account(
        v_product.tenant_id,
        '5101',
        'Consumibles de Taller',
        'expense',
        'costOfGoodsSold',
        'Materiales y consumibles de uso rápido aplicados directamente en el taller',
        null
      );

      v_entry_id := gen_random_uuid();

      insert into public.journal_entries (
        id,
        tenant_id,
        entry_number,
        entry_date,
        description,
        type,
        source_module,
        source_reference,
        status,
        total_debit,
        total_credit,
        created_at,
        updated_at
      ) values (
        v_entry_id,
        v_product.tenant_id,
        public.get_next_document_number(v_product.tenant_id, 'journal_entry'),
        now(),
        format('%s - %s', v_restore_reason, v_product.name),
        'adjustment',
        'product_restore',
        v_product.id::text,
        'posted',
        v_inventory_value,
        v_inventory_value,
        now(),
        now()
      );

      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_inventory_account_id,
        v_product.tenant_id,
        '1105',
        'Inventarios',
        format('%s - %s', v_restore_reason, v_product.name),
        v_inventory_value,
        0,
        now(),
        now()
      ), (
        gen_random_uuid(),
        v_entry_id,
        v_workshop_consumables_account_id,
        v_product.tenant_id,
        '5101',
        'Consumibles de Taller',
        format('%s - %s', v_restore_reason, v_product.name),
        0,
        v_inventory_value,
        now(),
        now()
      );
    end if;
  end if;

  update public.user_activity_log
     set details = coalesce(details, '{}'::jsonb) || jsonb_build_object(
       'restored', true,
       'restored_at', now(),
       'restored_by', auth.uid(),
       'restore_reference', v_restore_reference,
       'restored_inventory', p_restore_inventory,
       'restore_journal_entry_id', v_entry_id,
       'restore_reason', v_restore_reason
     )
   where id = v_log.id;

  insert into public.user_activity_log (
    tenant_id,
    user_id,
    action,
    details,
    performed_by,
    created_at
  ) values (
    v_product.tenant_id,
    auth.uid(),
    'product_conversion_restore',
    jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'source_conversion_reference', v_log.details->>'conversion_reference',
      'restore_reference', v_restore_reference,
      'restore_reason', v_restore_reason,
      'restored_inventory', p_restore_inventory,
      'restored_inventory_qty', v_restored_inventory_qty,
      'restored_stock_qty', v_restored_stock_qty,
      'journal_entry_id', v_entry_id,
      'product_state_after_restore', jsonb_build_object(
        'purchase_treatment', coalesce(v_product.purchase_treatment, 'inventory'),
        'product_type', coalesce(v_product.product_type, 'product'),
        'track_stock', coalesce(v_product.track_stock, true),
        'inventory_qty', coalesce(v_product.inventory_qty, 0),
        'stock_quantity', coalesce(v_product.stock_quantity, 0),
        'min_stock_level', coalesce(v_product.min_stock_level, 0),
        'max_stock_level', coalesce(v_product.max_stock_level, 0)
      )
    ),
    auth.uid(),
    now()
  );

  perform set_config('app.skip_stock_adjustment_trigger', '', true);

  return jsonb_build_object(
    'product', to_jsonb(v_product),
    'source_conversion_reference', v_log.details->>'conversion_reference',
    'restore_reference', v_restore_reference,
    'restored_inventory', p_restore_inventory,
    'blocking_activity_count', v_blocking_activity_count,
    'journal_entry_id', v_entry_id
  );
exception
  when others then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    raise;
end;
$$;

grant execute on function public.restore_product_conversion_state(uuid, text, boolean, text) to authenticated;

create or replace function public.get_product_conversion_status(
  p_product_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products;
  v_conversion public.user_activity_log;
  v_restore public.user_activity_log;
  v_conversion_reference text;
  v_restored boolean := false;
  v_restored_inventory boolean := false;
begin
  if p_product_id is null then
    raise exception 'Product ID is required';
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   limit 1;

  if not found then
    raise exception 'Product not found or not accessible';
  end if;

  select *
    into v_conversion
    from public.user_activity_log
   where tenant_id = v_product.tenant_id
     and action = 'product_conversion'
     and details->>'product_id' = v_product.id::text
   order by created_at desc
   limit 1;

  if not found then
    return jsonb_build_object(
      'product_id', v_product.id,
      'product_name', v_product.name,
      'has_conversion_history', false,
      'can_restore', false,
      'restored', false
    );
  end if;

  v_conversion_reference := v_conversion.details->>'conversion_reference';
  v_restored := coalesce((v_conversion.details->>'restored')::boolean, false);
  v_restored_inventory := coalesce((v_conversion.details->>'restored_inventory')::boolean, false);

  if v_conversion_reference is not null then
    select *
      into v_restore
      from public.user_activity_log
     where tenant_id = v_product.tenant_id
       and action = 'product_conversion_restore'
       and details->>'product_id' = v_product.id::text
       and details->>'source_conversion_reference' = v_conversion_reference
     order by created_at desc
     limit 1;
  end if;

  return jsonb_build_object(
    'product_id', v_product.id,
    'product_name', v_product.name,
    'has_conversion_history', true,
    'can_restore', not v_restored,
    'conversion_reference', v_conversion_reference,
    'conversion_reason', v_conversion.details->>'conversion_reason',
    'conversion_created_at', v_conversion.created_at,
    'converted_quantity', coalesce((v_conversion.details->>'converted_quantity')::integer, 0),
    'inventory_value', coalesce((v_conversion.details->>'inventory_value')::numeric, 0),
    'target_purchase_treatment', v_conversion.details->>'target_purchase_treatment',
    'target_product_type', v_conversion.details->>'target_product_type',
    'journal_entry_id', v_conversion.details->>'journal_entry_id',
    'original_state', coalesce(v_conversion.details->'original_state', '{}'::jsonb),
    'converted_state', coalesce(v_conversion.details->'converted_state', '{}'::jsonb),
    'restored', v_restored,
    'restored_at', coalesce(v_conversion.details->>'restored_at', to_char(v_restore.created_at, 'YYYY-MM-DD"T"HH24:MI:SSOF')),
    'restored_inventory', coalesce(
      nullif(v_conversion.details->>'restored_inventory', '')::boolean,
      nullif(v_restore.details->>'restored_inventory', '')::boolean,
      v_restored_inventory,
      false
    ),
    'restore_reference', coalesce(v_conversion.details->>'restore_reference', v_restore.details->>'restore_reference'),
    'restore_reason', coalesce(v_conversion.details->>'restore_reason', v_restore.details->>'restore_reason'),
    'restore_journal_entry_id', coalesce(v_conversion.details->>'restore_journal_entry_id', v_restore.details->>'journal_entry_id')
  );
end;
$$;

grant execute on function public.get_product_conversion_status(uuid) to authenticated;

create index if not exists idx_products_supplier_id on products(supplier_id);
create index if not exists idx_products_brand_id on products(brand_id);
create index if not exists idx_products_gtin on products(gtin);
create index if not exists idx_products_hs_code on products(hs_code);

-- ============================================================================
-- PUBLIC STORE SEARCH (RPC)
-- ============================================================================
-- Tokenized AND search + accent-insensitive normalization.
-- Example: "camara 26" matches "Cámara ... 26x1,95...".

create extension if not exists pg_trgm;
create extension if not exists unaccent;

-- Optional scheduler/network extensions for server-side public business data refreshes.
-- Production uses pg_cron + pg_net to call the google-public-data-refresh Edge Function.
do $$
begin
  create schema if not exists extensions;
  execute 'create extension if not exists pg_net with schema extensions';
exception
  when others then
    raise notice '⚠ pg_net extension is not available in this environment: %', sqlerrm;
end $$;

do $$
begin
  create schema if not exists extensions;
  execute 'create extension if not exists pg_cron with schema extensions';
exception
  when others then
    raise notice '⚠ pg_cron extension is not available in this environment: %', sqlerrm;
end $$;

create or replace function public.search_products(
  p_search_term text,
  p_tenant_id uuid,
  p_limit int default 10
)
returns setof public.products
language sql
security invoker
set search_path = public
as $$
  with q as (
    select
      unaccent(lower(coalesce(p_search_term, ''))) as term,
      array_remove(
        regexp_split_to_array(
          regexp_replace(unaccent(lower(coalesce(p_search_term, ''))), '[^a-z0-9]+', ' ', 'g'),
          '\\s+'
        ),
        ''
      ) as tokens
  )
  select p.*
  from public.products p
  cross join q
  where
    q.term <> ''
    and p.tenant_id = p_tenant_id
    and p.is_active = true
    and (
      p.product_type = 'service'
      or coalesce(p.track_stock, true) = false
      or coalesce(p.inventory_qty, 0) > 0
      or coalesce(p.stock_quantity, 0) > 0
    )

    -- AND semantics across tokens, OR semantics across fields
    and (
      select bool_and(
        case
          -- Numeric-only tokens (e.g. "26") often represent sizes.
          -- Avoid matching them inside long identifier fields like SKU/barcodes,
          -- which can create false positives.
          when t ~ '^[0-9]+$' then
            (
              unaccent(lower(coalesce(p.name, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.description, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.brand, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.model, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.manufacturer, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.category_name, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.sku, ''))) ~ ('(^|[^0-9])' || t || '([^0-9]|$)')
              or unaccent(lower(coalesce(p.manufacturer_sku, ''))) ~ ('(^|[^0-9])' || t || '([^0-9]|$)')
            )
          else
            (
              unaccent(lower(coalesce(p.name, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.sku, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.description, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.brand, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.model, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.manufacturer, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.manufacturer_sku, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.barcode, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.gtin, ''))) like '%' || t || '%'
              or unaccent(lower(coalesce(p.category_name, ''))) like '%' || t || '%'
            )
        end
      )
      from unnest(q.tokens) as t
    )

  order by
    -- Prefer direct substring hits in the most relevant fields
    case when unaccent(lower(coalesce(p.sku, ''))) = q.term then 5 else 0 end desc,
    case when unaccent(lower(coalesce(p.name, ''))) like '%' || q.term || '%' then 4 else 0 end desc,
    case when unaccent(lower(coalesce(p.sku, ''))) like '%' || q.term || '%' then 3 else 0 end desc,
    case when unaccent(lower(coalesce(p.brand, ''))) like '%' || q.term || '%' then 2 else 0 end desc,

    -- Then trigram similarity
    greatest(
      similarity(unaccent(lower(coalesce(p.name, ''))), q.term),
      similarity(unaccent(lower(coalesce(p.sku, ''))), q.term),
      similarity(unaccent(lower(coalesce(p.description, ''))), q.term)
    ) desc,

    -- Stable ordering
    p.name asc

  limit greatest(p_limit, 0);
$$;

grant execute on function public.search_products(text, uuid, int) to anon;
grant execute on function public.search_products(text, uuid, int) to authenticated;

-- ============================================================================
-- PRODUCT SETS SYSTEM - Juegos/Sets de Productos
-- ============================================================================
-- Allows products to be defined as "sets" containing multiple components.
-- Example: "Juego Mazas Shimano Deore" = Front Hub + Rear Hub
-- Stock is tracked at component level, not at set level.
-- ============================================================================

-- Add set-related columns to products table
do $$
begin
  -- is_set: True if this product is a parent set product
  if not exists (select 1 from information_schema.columns
    where table_name = 'products' and column_name = 'is_set') then
    alter table products add column is_set boolean not null default false;
  end if;

  -- set_type: Type of set for UI hints ('pair', 'front_rear', 'left_right', 'custom')
  if not exists (select 1 from information_schema.columns
    where table_name = 'products' and column_name = 'set_type') then
    alter table products add column set_type text;
  end if;

  -- parent_set_id: If this is a component, references the parent set
  if not exists (select 1 from information_schema.columns
    where table_name = 'products' and column_name = 'parent_set_id') then
    alter table products add column parent_set_id uuid references products(id) on delete set null;
  end if;

  -- component_label: For components, stores the label like "Delantero", "Trasero"
  if not exists (select 1 from information_schema.columns
    where table_name = 'products' and column_name = 'component_label') then
    alter table products add column component_label text;
  end if;

  -- component_position: For ordering components in the set (1, 2, 3...)
  if not exists (select 1 from information_schema.columns
    where table_name = 'products' and column_name = 'component_position') then
    alter table products add column component_position integer;
  end if;
end $$;

-- Indexes for fast lookups
create index if not exists idx_products_parent_set
  on products(parent_set_id) where parent_set_id is not null;
create index if not exists idx_products_is_set
  on products(is_set) where is_set = true;

-- Product Set Components Table: Links parent sets to their child products
create table if not exists product_set_components (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,

  -- Parent set product
  set_product_id uuid references products(id) on delete cascade not null,

  -- Child component product
  component_product_id uuid references products(id) on delete cascade not null,

  -- Component metadata
  component_label text not null,        -- "Delantero", "Trasero", "Izquierdo", "Derecho"
  component_position integer not null,  -- Order: 1, 2, 3...
  quantity_in_set integer not null default 1,  -- Usually 1, could be 2 for "par de pedales"

  -- Pricing ratios (for calculating component prices from set price)
  cost_ratio numeric(5,4),   -- 0.4 = 40% of set cost goes to this component
  price_ratio numeric(5,4),  -- 0.6 = 60% of set price goes to this component

  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),

  -- Constraints
  unique(set_product_id, component_product_id),
  unique(set_product_id, component_position)
);

-- Indexes for product_set_components
create index if not exists idx_product_set_components_tenant
  on product_set_components(tenant_id);
create index if not exists idx_product_set_components_set
  on product_set_components(set_product_id);
create index if not exists idx_product_set_components_component
  on product_set_components(component_product_id);

-- Enable RLS on product_set_components
alter table product_set_components enable row level security;

-- RLS Policies for product_set_components
drop policy if exists "product_set_components_select" on product_set_components;
drop policy if exists "product_set_components_insert" on product_set_components;
drop policy if exists "product_set_components_update" on product_set_components;
drop policy if exists "product_set_components_delete" on product_set_components;

create policy "product_set_components_select" on product_set_components
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "product_set_components_insert" on product_set_components
  for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "product_set_components_update" on product_set_components
  for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "product_set_components_delete" on product_set_components
  for delete to authenticated
  using (tenant_id = public.user_tenant_id());

-- Trigger for updated_at on product_set_components
do $$
begin
  if not exists (select 1 from pg_trigger where tgname = 'trg_product_set_components_updated_at') then
    create trigger trg_product_set_components_updated_at
      before update on product_set_components
      for each row execute function public.set_updated_at();
  end if;
end $$;

-- Function: Get component availability for a set
-- Returns the minimum stock across all components (= max full sets available)
create or replace function public.get_set_availability(p_set_product_id uuid)
returns table (
  component_id uuid,
  component_name text,
  component_label text,
  component_position integer,
  stock_quantity integer,
  quantity_needed integer
)
language plpgsql
as $$
begin
  return query
  select
    psc.component_product_id as component_id,
    p.name as component_name,
    psc.component_label,
    psc.component_position,
    coalesce(p.stock_quantity, p.inventory_qty, 0)::integer as stock_quantity,
    psc.quantity_in_set as quantity_needed
  from product_set_components psc
  join products p on p.id = psc.component_product_id
  where psc.set_product_id = p_set_product_id
  order by psc.component_position;
end;
$$;

-- Function: Get full sets available (min stock across all components)
create or replace function public.get_full_sets_count(p_set_product_id uuid)
returns integer
language plpgsql
as $$
declare
  v_min_sets integer;
begin
  select min(
    floor(coalesce(p.stock_quantity, p.inventory_qty, 0)::numeric / psc.quantity_in_set)
  )::integer
  into v_min_sets
  from product_set_components psc
  join products p on p.id = psc.component_product_id
  where psc.set_product_id = p_set_product_id;

  return coalesce(v_min_sets, 0);
end;
$$;

-- Function: Check if set has partial availability
create or replace function public.is_set_partial(p_set_product_id uuid)
returns boolean
language plpgsql
as $$
declare
  v_has_stock boolean;
  v_missing_stock boolean;
begin
  -- Check if at least one component has stock
  select exists (
    select 1 from product_set_components psc
    join products p on p.id = psc.component_product_id
    where psc.set_product_id = p_set_product_id
      and coalesce(p.stock_quantity, p.inventory_qty, 0) >= psc.quantity_in_set
  ) into v_has_stock;

  -- Check if at least one component is missing stock
  select exists (
    select 1 from product_set_components psc
    join products p on p.id = psc.component_product_id
    where psc.set_product_id = p_set_product_id
      and coalesce(p.stock_quantity, p.inventory_qty, 0) < psc.quantity_in_set
  ) into v_missing_stock;

  -- Partial = some have stock AND some don't
  return v_has_stock and v_missing_stock;
end;
$$;

-- View: Products with set information (enriches products with component data)
drop view if exists public.products_with_sets cascade;

create or replace view public.products_with_sets as
select
  p.*,
  -- For sets: aggregate component info
  case when p.is_set then
    (select json_agg(
      json_build_object(
        'id', psc.id,
        'component_product_id', psc.component_product_id,
        'component_label', psc.component_label,
        'component_position', psc.component_position,
        'component_name', cp.name,
        'component_sku', cp.sku,
        'stock_quantity', coalesce(cp.stock_quantity, cp.inventory_qty, 0),
        'quantity_in_set', psc.quantity_in_set,
        'cost_ratio', psc.cost_ratio,
        'price_ratio', psc.price_ratio
      ) order by psc.component_position
    )
    from product_set_components psc
    join products cp on cp.id = psc.component_product_id
    where psc.set_product_id = p.id)
  end as set_components,
  -- For sets: calculate availability
  case when p.is_set then public.get_full_sets_count(p.id) end as full_sets_available,
  case when p.is_set then public.is_set_partial(p.id) end as is_partial,
  -- For components: get parent set info
  case when p.parent_set_id is not null then
    (select json_build_object(
      'id', ps.id,
      'name', ps.name,
      'sku', ps.sku
    ) from products ps where ps.id = p.parent_set_id)
  end as parent_set_info
from products p;

-- ============================================================================
-- STOCK ADJUSTMENTS TABLE - Track manual stock changes
-- ============================================================================
create table if not exists stock_adjustments (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  product_id uuid references products(id) on delete cascade not null,
  adjustment_type text not null check (adjustment_type in ('manual', 'correction', 'initial', 'damage', 'loss', 'found', 'import', 'purchase', 'count_gain', 'count_loss', 'theft', 'internal_use')),
