-- Trigger to track manual stock changes on products table
create or replace function track_product_stock_changes()
returns trigger as $$
declare
  v_adjustment_type text;
  v_reason text;
  v_reference text;
  v_context text;
  v_stock_before integer;
  v_stock_after integer;
  v_adjustment_qty integer;
begin
  -- Services and non-stock-tracked items should not generate stock adjustments.
  if coalesce(NEW.product_type, 'product') = 'service'
     or coalesce(NEW.track_stock, true) = false then
    return NEW;
  end if;

  -- CRITICAL: Only track MANUAL changes, not automatic ones from invoice triggers
  -- Skip if this update is triggered by invoice consumption functions
  if current_setting('app.skip_stock_adjustment_trigger', true) = 'true' then
    return NEW;
  end if;

  -- Only track if stock_quantity actually changed
  if (TG_OP = 'UPDATE' and OLD.stock_quantity <> NEW.stock_quantity) then

    -- If the legacy inventory_qty column had drifted and a form save rewrites
    -- both columns consistently, measure the real change from inventory_qty.
    if OLD.inventory_qty is distinct from OLD.stock_quantity
       and NEW.stock_quantity = NEW.inventory_qty then
      v_stock_before := OLD.inventory_qty;
      v_stock_after := NEW.inventory_qty;
    else
      v_stock_before := OLD.stock_quantity;
      v_stock_after := NEW.stock_quantity;
    end if;

    v_adjustment_qty := v_stock_after - v_stock_before;

    -- Pure column resync with no real stock change should not create a manual adjustment.
    if v_adjustment_qty = 0 then
      return NEW;
    end if;

    v_context := current_setting('app.stock_adjustment_context', true);

    -- Determine adjustment type based on context
    if v_context = 'import' then
      v_adjustment_type := 'import';
      v_reason := coalesce(current_setting('app.import_reason', true), 'Stock updated via import');
      v_reference := current_setting('app.import_reference', true);

    elsif v_context = 'purchase' then
      -- ✅ NEW: Handle purchase context
      v_adjustment_type := 'purchase';
      v_reason := 'Compra recibida (Invoice ' || coalesce(current_setting('app.stock_adjustment_reference', true), 'Unknown') || ')';
      v_reference := current_setting('app.stock_adjustment_reference', true);

    else
      v_adjustment_type := 'manual';
      v_reason := 'Ajuste Manual'; -- Changed label to match user expectation
      v_reference := null;
    end if;

    -- Insert into stock_adjustments (which now syncs to stock_movements via Migration 2)
    insert into stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by
    ) values (
      NEW.tenant_id,
      NEW.id,
      v_adjustment_type,
      v_adjustment_qty,
      v_stock_before,
      v_stock_after,
      v_reason,
      v_reference,
      auth.uid()
    );

  elsif (TG_OP = 'INSERT' and NEW.stock_quantity > 0) then
    -- Track initial stock logic
    v_context := current_setting('app.stock_adjustment_context', true);

    if v_context = 'import' then
      v_adjustment_type := 'import';
      v_reason := coalesce(current_setting('app.import_reason', true), 'Initial stock via import');
      v_reference := current_setting('app.import_reference', true);
    else
      v_adjustment_type := 'initial';
      v_reason := 'Initial stock on product creation';
      v_reference := null;
    end if;

    insert into stock_adjustments (
      tenant_id,
      product_id,
      adjustment_type,
      quantity,
      stock_before,
      stock_after,
      reason,
      reference,
      created_by
    ) values (
      NEW.tenant_id,
      NEW.id,
      v_adjustment_type,
      NEW.stock_quantity,
      0,
      NEW.stock_quantity,
      v_reason,
      v_reference,
      auth.uid()
    );
  end if;

  return NEW;
end;
$$ language plpgsql security definer;

drop trigger if exists trg_track_product_stock_changes on products;
create trigger trg_track_product_stock_changes
  after insert or update of stock_quantity
  on products
  for each row
  execute function track_product_stock_changes();

-- ============================================================================
-- PRODUCT TRIGGERS - Sync denormalized fields
-- ============================================================================

-- Function to sync category_name when category_id changes
create or replace function sync_product_category_name()
returns trigger as $$
begin
  -- Update category_name from product_categories table
  if NEW.category_id is not null then
    select name into NEW.category_name
    from product_categories
    where id = NEW.category_id;
  else
    NEW.category_name := null;
  end if;

  -- Update supplier_name from suppliers table
  if NEW.supplier_id is not null then
    select name into NEW.supplier_name
    from suppliers
    where id = NEW.supplier_id;
  else
    NEW.supplier_name := null;
  end if;

  return NEW;
end;
$$ language plpgsql;

-- Trigger to sync category_name and supplier_name on INSERT or UPDATE
drop trigger if exists trg_sync_product_denormalized_fields on products;
create trigger trg_sync_product_denormalized_fields
  before insert or update of category_id, supplier_id
  on products
  for each row
  execute function sync_product_category_name();

-- Function to update category_name when category name changes
create or replace function sync_products_on_category_change()
returns trigger as $$
begin
  -- When a category name changes, update all products using that category
  if TG_OP = 'UPDATE' and OLD.name is distinct from NEW.name then
    update products
    set category_name = NEW.name
    where category_id = NEW.id;
  end if;

  return NEW;
end;
$$ language plpgsql;

-- Trigger on product_categories to sync product names
do $$
begin
  if to_regclass('public.product_categories') is null then
    return;
  end if;

  execute 'drop trigger if exists trg_sync_products_on_category_change on product_categories';
  execute 'create trigger trg_sync_products_on_category_change after update of name on product_categories for each row execute function sync_products_on_category_change()';
exception
  when others then
    raise notice '⚠️ Could not create trg_sync_products_on_category_change (%).', sqlerrm;
end $$;

-- Function to update supplier_name when supplier name changes
create or replace function sync_products_on_supplier_change()
returns trigger as $$
begin
  -- When a supplier name changes, update all products using that supplier
  if TG_OP = 'UPDATE' and OLD.name is distinct from NEW.name then
    update products
    set supplier_name = NEW.name
    where supplier_id = NEW.id;
  end if;

  return NEW;
end;
$$ language plpgsql;

-- Trigger on suppliers to sync product supplier names
do $$
begin
  if to_regclass('public.suppliers') is null then
    return;
  end if;

  execute 'drop trigger if exists trg_sync_products_on_supplier_change on suppliers';
  execute 'create trigger trg_sync_products_on_supplier_change after update of name on suppliers for each row execute function sync_products_on_supplier_change()';
exception
  when others then
    raise notice '⚠️ Could not create trg_sync_products_on_supplier_change (%).', sqlerrm;
end $$;

