alter table public.suppliers
  add column if not exists legal_name text,
  add column if not exists trade_name text,
  add column if not exists owner_name text,
  add column if not exists aliases text[] not null default '{}'::text[],
  add column if not exists rut text,
  add column if not exists email text,
  add column if not exists phone text,
  add column if not exists address text,
  add column if not exists city text,
  add column if not exists region text,
  add column if not exists comuna text,
  add column if not exists contact_person text,
  add column if not exists website text,
  add column if not exists type text not null default 'local',
  add column if not exists bank_details jsonb not null default '{}'::jsonb,
  add column if not exists ocr_template jsonb not null default '{}'::jsonb,
  add column if not exists payment_terms text not null default 'net30',
  add column if not exists notes text,
  add column if not exists image_url text,
  add column if not exists portal_username text,
  add column if not exists portal_password text,
  add column if not exists sales_rep_name text,
  add column if not exists sales_rep_phone text,
  add column if not exists sales_rep_email text,
  add column if not exists purchase_instructions text,
  add column if not exists is_active boolean not null default true,
  add column if not exists created_at timestamp with time zone not null default now(),
  add column if not exists updated_at timestamp with time zone not null default now(),
  add column if not exists default_tax_treatment text not null default 'no_tax' check (default_tax_treatment in ('no_tax', 'tax_included'));

comment on column suppliers.default_tax_treatment is
  'Suggested tax treatment for purchases from this supplier. tax_included = invoice with IVA, no_tax = receipt or international purchase. User can override per transaction.';

comment on column suppliers.legal_name is
  'Legal issuer or razón social shown on supplier tax documents.';
comment on column suppliers.trade_name is
  'Commercial brand or public-facing supplier name.';
comment on column suppliers.owner_name is
  'Owner, parent, or controlling company when it differs from the shop-facing supplier.';
comment on column suppliers.aliases is
  'Additional OCR/search names that should resolve to this supplier.';

update public.suppliers
set aliases = '{}'::text[]
where aliases is null;

alter table public.suppliers
  alter column aliases set default '{}'::text[],
  alter column aliases set not null;

update public.suppliers s
set
  legal_name = coalesce(nullif(s.legal_name, ''), 'Kaudat SpA'),
  owner_name = coalesce(nullif(s.owner_name, ''), 'Kaudat SpA'),
  trade_name = coalesce(nullif(s.trade_name, ''), 'Starken'),
  rut = coalesce(nullif(s.rut, ''), '76.211.240-K'),
  default_tax_treatment = 'tax_included',
  aliases = (
    select array_agg(alias order by alias)
    from (
      select distinct trim(alias) as alias
      from unnest(
        coalesce(s.aliases, '{}'::text[]) ||
        array['Starken', 'Kaudat', 'Kaudat SpA', 'KAUDAT SPA']
      ) as alias
      where trim(alias) <> ''
    ) deduped_aliases
  ),
  updated_at = now()
where lower(s.name) like '%starken%'
   or lower(s.name) like '%kaudat%';

do $$
begin
  if not exists (
    select 1 from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'suppliers'
      and t.tgname = 'trg_suppliers_updated_at'
  ) then
    create trigger trg_suppliers_updated_at
      before update on suppliers
      for each row execute procedure public.set_updated_at();
  end if;
end $$;

