  v_count := v_count + (case when found then 1 else 0 end);

  -- EXPENSES - Other
  insert into accounts (tenant_id, code, name, type, category, description, is_active)
  select p_tenant_id, '6401', 'Gastos de Viaje', 'expense', 'operatingExpense',
