  to authenticated
  using (tenant_id = public.user_tenant_id());

create or replace function public.generate_expense_number()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next bigint;
begin
  select nextval('expense_number_seq') into v_next;
  return format('GTO-%s', lpad(v_next::text, 5, '0'));
exception
  when others then
    raise notice 'generate_expense_number fallback due to %', SQLERRM;
    return concat('GTO-', lpad((extract(epoch from now())::bigint % 100000)::text, 5, '0'));
end;
$$;

create or replace function public.prepare_expense_record()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_posting text := lower(coalesce(NEW.posting_status, 'draft'));
  v_payment text := lower(coalesce(NEW.payment_status, 'pending'));
begin
  if TG_OP = 'INSERT' then
    if coalesce(NEW.expense_number, '') = '' then
      NEW.expense_number := public.generate_expense_number();
    end if;
    NEW.created_at := coalesce(NEW.created_at, now());
    if v_posting = 'posted' then
      NEW.posted_at := coalesce(NEW.posted_at, NEW.issue_date, now());
    end if;
    if v_payment = 'paid' then
      NEW.paid_at := coalesce(NEW.paid_at, NEW.issue_date, now());
    end if;
  elsif TG_OP = 'UPDATE' then
    if v_posting = 'posted' and lower(coalesce(OLD.posting_status, 'draft')) <> 'posted' then
      NEW.posted_at := coalesce(NEW.posted_at, NEW.issue_date, now());
    elsif v_posting <> 'posted' then
      NEW.posted_at := null;
    end if;

    if v_payment = 'paid' and lower(coalesce(OLD.payment_status, 'pending')) <> 'paid' then
      NEW.paid_at := coalesce(NEW.paid_at, NEW.issue_date, now());
    elsif v_payment <> 'paid' then
      NEW.paid_at := null;
    end if;
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expenses_prepare'
       and tgrelid = 'public.expenses'::regclass
  ) then
    create trigger trg_expenses_prepare
      before insert or update on public.expenses
      for each row execute procedure public.prepare_expense_record();
  end if;
end $$;

create or replace function public.prepare_expense_line()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_account record;
begin
  NEW.quantity := coalesce(NEW.quantity, 1);
  NEW.unit_price := coalesce(NEW.unit_price, 0);
  NEW.subtotal := round(NEW.quantity * NEW.unit_price, 2);
  NEW.tax_rate := coalesce(NEW.tax_rate, 0);

  -- If the client doesn't provide these fields, they often come in as default 0
  -- (because the columns are NOT NULL DEFAULT 0). Treat 0 as "unset" when the
  -- computed subtotal is > 0.
  if NEW.tax_amount is null or (NEW.tax_amount = 0 and NEW.tax_rate <> 0 and NEW.subtotal <> 0) then
    NEW.tax_amount := round((NEW.subtotal * NEW.tax_rate) / 100, 2);
  end if;

  if NEW.total is null or (NEW.total = 0 and NEW.subtotal <> 0) then
    NEW.total := NEW.subtotal + coalesce(NEW.tax_amount, 0);
  end if;

  if (NEW.account_code is null or NEW.account_name is null) and NEW.account_id is not null then
    select code, name
      into v_account
      from public.accounts
     where id = NEW.account_id;
    if found then
      NEW.account_code := coalesce(NEW.account_code, v_account.code);
      NEW.account_name := coalesce(NEW.account_name, v_account.name);
    end if;
  end if;

  if TG_OP = 'INSERT' then
    NEW.created_at := coalesce(NEW.created_at, now());
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

-- NOTE: handle_expense_line_change() is defined later at line ~3851
-- (removed duplicate definition here to avoid overwriting the correct version)

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expense_lines_prepare'
       and tgrelid = 'public.expense_lines'::regclass
  ) then
    create trigger trg_expense_lines_prepare
      before insert or update on public.expense_lines
      for each row execute procedure public.prepare_expense_line();
  end if;
end $$;

create or replace function public.prepare_expense_payment()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if NEW.payment_date is null then
    NEW.payment_date := now();
  end if;

  if TG_OP = 'INSERT' then
    NEW.created_at := coalesce(NEW.created_at, now());
  end if;

  NEW.updated_at := now();
  return NEW;
end;
$$;

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expense_payments_prepare'
       and tgrelid = 'public.expense_payments'::regclass
  ) then
    create trigger trg_expense_payments_prepare
      before insert or update on public.expense_payments
      for each row execute procedure public.prepare_expense_payment();
  end if;
end $$;

create or replace function public.recalculate_expense_totals(p_expense_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_expense record;
  v_subtotal numeric(14,2) := 0;
  v_tax numeric(14,2) := 0;
  v_total numeric(14,2) := 0;
  v_paid numeric(14,2) := 0;
  v_latest_payment_date timestamp with time zone;
  v_payment_method_count integer := 0;
  v_payment_account_count integer := 0;
  v_single_payment_method_id uuid;
  v_single_payment_account_id uuid;
  v_category_id uuid;
  v_line_account_id uuid;
  v_line_account_code text;
  v_line_account_name text;
  v_category_name text;
  v_category_desc text;
  v_prev_payment text;
  v_new_payment text;
begin
  if p_expense_id is null then
    return;
  end if;

    select e.id,
      e.tenant_id,
      e.category_id,
        e.issue_date,
         lower(coalesce(e.payment_status, 'pending')) as payment_status,
         lower(coalesce(e.posting_status, 'draft')) as posting_status,
         e.paid_at,
         e.payment_method_id,
      e.payment_account_id,
         e.amount_paid as current_amount_paid,
         e.balance as current_balance
    into v_expense
    from public.expenses e
   where e.id = p_expense_id
   for update;

  if not found then
    return;
  end if;

  select
      coalesce(sum(subtotal), 0),
      coalesce(sum(tax_amount), 0),
      coalesce(sum(total), 0)
    into v_subtotal, v_tax, v_total
    from public.expense_lines
   where expense_id = p_expense_id;

  select coalesce(sum(amount), 0)
    into v_paid
    from public.expense_payments
   where expense_id = p_expense_id;

  select max(payment_date)
    into v_latest_payment_date
    from public.expense_payments
   where expense_id = p_expense_id
     and coalesce(amount, 0) > 0;

  -- If payments exist, reflect the payment method/account in the header when unambiguous.
  -- This keeps list views informative (and avoids "Sin medio de pago" for paid expenses).
  if v_paid > 0 then
    select
      count(distinct ep.payment_method_id),
      (array_agg(distinct ep.payment_method_id))[1]
      into v_payment_method_count, v_single_payment_method_id
      from public.expense_payments ep
     where ep.expense_id = p_expense_id
       and coalesce(ep.amount, 0) > 0
       and ep.payment_method_id is not null;

    select
      count(distinct ep.payment_account_id),
      (array_agg(distinct ep.payment_account_id))[1]
      into v_payment_account_count, v_single_payment_account_id
      from public.expense_payments ep
     where ep.expense_id = p_expense_id
       and coalesce(ep.amount, 0) > 0
       and ep.payment_account_id is not null;
  end if;

  v_prev_payment := v_expense.payment_status;

  -- Auto-assign category from expense line account (never override manual category)
  v_category_id := v_expense.category_id;
  if v_category_id is null then
    select el.account_id,
           el.account_code,
           el.account_name
      into v_line_account_id,
           v_line_account_code,
           v_line_account_name
      from public.expense_lines el
     where el.expense_id = p_expense_id
     order by el.line_index asc, el.created_at asc
     limit 1;

    if v_line_account_id is not null then
      v_category_name := public.get_expense_category_name_for_account(
        v_line_account_code,
        v_line_account_name
      );
      v_category_desc := coalesce(v_line_account_name, v_category_name);

      v_category_id := public.ensure_expense_category(
        v_expense.tenant_id,
        v_category_name,
        v_category_desc,
        v_line_account_id
      );
    end if;
  end if;

  -- If already marked as paid with payment_method_id set (immediate payment on creation)
  -- and no separate payment records exist, respect that status
  if v_prev_payment = 'paid'
     and v_expense.payment_method_id is not null
     and v_paid = 0
     and v_total > 0 then
    v_new_payment := 'paid';
    v_paid := v_total; -- Use total as paid amount
  elsif v_total = 0 then
    v_new_payment := v_prev_payment;
  elsif v_paid <= 0 then
    if v_prev_payment = 'scheduled' then
      v_new_payment := 'scheduled';
    else
      v_new_payment := 'pending';
    end if;
  elsif v_paid + 0.01 < v_total then
    v_new_payment := 'partial';
  else
    v_new_payment := 'paid';
  end if;

  update public.expenses
     set subtotal = v_subtotal,
         tax_amount = v_tax,
         total_amount = v_total,
         amount_paid = v_paid,
         balance = greatest(v_total - v_paid, 0),
         category_id = coalesce(category_id, v_category_id),
         payment_method_id = case
           when v_payment_method_count = 1 and v_expense.payment_method_id is null
             then v_single_payment_method_id
           else payment_method_id
         end,
         payment_account_id = case
           when v_payment_account_count = 1 and v_expense.payment_account_id is null
             then v_single_payment_account_id
           else payment_account_id
         end,
         payment_status = case
           when v_expense.posting_status = 'void' then payment_status
           when v_prev_payment = 'void' then 'void'
           else v_new_payment
         end,
         paid_at = case
           when v_expense.posting_status <> 'void'
             and v_total > 0
             and v_paid + 0.01 >= v_total then coalesce(v_latest_payment_date, paid_at, v_expense.issue_date, now())
           when v_new_payment <> 'paid' then null
           else paid_at
         end,
         updated_at = now()
   where id = p_expense_id;
end;
$$;

do $$
declare
  v_fixed_count integer := 0;
begin
  with payment_rollup as (
    select
      e.id,
      max(ep.payment_date) filter (where coalesce(ep.amount, 0) > 0) as latest_payment_date,
      count(ep.id) filter (where coalesce(ep.amount, 0) > 0) as payment_count
    from public.expenses e
    left join public.expense_payments ep
      on ep.expense_id = e.id
    where lower(coalesce(e.payment_status, 'pending')) = 'paid'
      and lower(coalesce(e.posting_status, 'draft')) <> 'void'
    group by e.id
  ), targets as (
    select
      e.id,
      case
        when pr.payment_count > 0 then pr.latest_payment_date
        when pr.payment_count = 0
          and e.issue_date is not null
          and (
            e.paid_at is null
            or (
              e.paid_at is not null
              and e.created_at is not null
              and e.created_at::date = e.paid_at::date
              and e.issue_date::date <> e.paid_at::date
            )
          ) then e.issue_date
        else null
      end as corrected_paid_at,
      case
        when pr.payment_count = 0
          and e.issue_date is not null
          and (
            e.posted_at is null
            or (
              e.posted_at is not null
              and e.created_at is not null
              and e.created_at::date = e.posted_at::date
              and e.issue_date::date <> e.posted_at::date
            )
          ) then e.issue_date
        else null
      end as corrected_posted_at
    from public.expenses e
    join payment_rollup pr on pr.id = e.id
  )
  update public.expenses e
     set paid_at = coalesce(t.corrected_paid_at, e.paid_at),
         posted_at = coalesce(t.corrected_posted_at, e.posted_at),
         updated_at = now()
    from targets t
   where e.id = t.id
     and (
       t.corrected_paid_at is distinct from e.paid_at
       or t.corrected_posted_at is distinct from e.posted_at
     );

  get diagnostics v_fixed_count = row_count;
  raise notice 'Backfilled % expense rows with corrected paid_at/posted_at', v_fixed_count;
end $$;

create or replace function public.create_expense_journal_entry(p_expense_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_expense record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_liability_account_id uuid;
  v_liability_account_code text;
  v_liability_account_name text;
  v_tax_account_id uuid;
  v_tax_account_code text := '2120';
  v_tax_account_name text := 'IVA Crédito Fiscal';
  v_cash_account record;
  v_total numeric(14,2);
  v_tax_total numeric(14,2);
  v_credit_account_id uuid;
  v_credit_account_code text;
  v_credit_account_name text;
  v_description text;
  v_supplier text;
  v_document text;
  v_line record;
  v_line_count integer := 0;
  v_default_account record;
  v_is_payroll boolean := false;
begin
  select e.*
    into v_expense
    from public.expenses e
   where e.id = p_expense_id;

  if not found then
    return;
  end if;

  if lower(coalesce(v_expense.posting_status, 'draft')) <> 'posted' then
    return;
  end if;

  v_total := coalesce(v_expense.total_amount, 0);

  if v_total = 0 then
    return;
  end if;

  v_is_payroll := (
    v_expense.notes like 'Pago de salario%'
    or v_expense.notes like 'Salario:%'
    or v_expense.reference like 'Semana %'
  );

  -- Delete existing journal entry if it exists (to recreate it fresh)
  select exists (
           select 1
             from public.journal_entries
            where source_module = 'expenses'
              and source_reference = v_expense.expense_number
         )
    into v_exists;

  if v_exists then
    perform public.delete_expense_journal_entry(p_expense_id);
  end if;

  if v_is_payroll then
    v_liability_account_code := '2106';
    v_liability_account_name := 'Sueldos por Pagar';
    v_liability_account_id := public.ensure_account(
      v_expense.tenant_id,
      v_liability_account_code,
      v_liability_account_name,
      'liability',
      'currentLiability',
      'Obligaciones pendientes de pago por remuneraciones al personal',
      null
    );
  else
    v_liability_account_code := '2105';
    v_liability_account_name := 'Cuentas por Pagar - Gastos';
    v_liability_account_id := coalesce(
      v_expense.liability_account_id,
      public.ensure_account(
        v_expense.tenant_id,
        v_liability_account_code,
        v_liability_account_name,
        'liability',
        'currentLiability',
        'Obligaciones por gastos pendientes de pago',
        null
      )
    );
  end if;

  -- Ensure record has a known tuple structure even when no payment account/method is set
  select null::uuid as id, null::text as code, null::text as name
    into v_cash_account;

  if v_expense.payment_account_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.id = v_expense.payment_account_id;
  elsif v_expense.payment_method_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.payment_methods pm
      join public.accounts a on a.id = pm.account_id
     where pm.id = v_expense.payment_method_id;
  end if;

  v_tax_account_id := public.ensure_account(
    v_expense.tenant_id,
    v_tax_account_code,
    v_tax_account_name,
    'asset',
    'currentAsset',
    'Crédito fiscal IVA soportado en compras',
    null
  );

  v_supplier := coalesce(nullif(v_expense.supplier_name, ''), 'Proveedor');
  v_document := coalesce(nullif(v_expense.document_number, ''), v_expense.expense_number);
  v_description := format('Gasto %s - %s', v_document, v_supplier);

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_expense.tenant_id,
    public.get_next_document_number(v_expense.tenant_id, 'journal_entry'),
    coalesce(v_expense.issue_date, now()),
    v_description,
    case when v_is_payroll then 'payroll' else 'purchase' end,
    'expenses',
    v_expense.expense_number,
    'posted',
    v_total,
    v_total,
    now(),
    now()
  );

  for v_line in
    select el.*
      from public.expense_lines el
     where el.expense_id = v_expense.id
     order by el.line_index, el.created_at
  loop
    v_line_count := v_line_count + 1;
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_line.account_id,
      v_line.account_code,
      v_line.account_name,
      coalesce(nullif(v_line.description, ''), v_description),
      coalesce(v_line.subtotal, 0),
      0,
      now(),
      now()
    );
  end loop;

  if v_line_count = 0 then
    if v_expense.category_id is not null then
      select a.id, a.code, a.name
        into v_default_account
        from public.expense_categories ec
        join public.accounts a on a.id = ec.default_account_id
       where ec.id = v_expense.category_id;
    end if;

    if not found or v_default_account.id is null then
      select public.ensure_account(
               v_expense.tenant_id,
               '5200',
               'Gastos Generales',
               'expense',
               'operatingExpense',
               'Gastos generales y administrativos',
               null
             ) as id,
             '5200' as code,
             'Gastos Generales' as name
        into v_default_account;
    end if;

    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_default_account.id,
      v_default_account.code,
      v_default_account.name,
      v_description,
      coalesce(v_expense.subtotal, v_total - coalesce(v_expense.tax_amount, 0)),
      0,
      now(),
      now()
    );
  end if;

  v_tax_total := coalesce(v_expense.tax_amount, 0);
  if v_tax_total <> 0 then
    insert into public.journal_lines (
      id,
      tenant_id,
      entry_id,
      account_id,
      account_code,
      account_name,
      description,
      debit_amount,
      credit_amount,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_expense.tenant_id,
      v_entry_id,
      v_tax_account_id,
      v_tax_account_code,
      v_tax_account_name,
      format('IVA crédito gasto %s', v_document),
      v_tax_total,
      0,
      now(),
      now()
    );
  end if;

  if v_is_payroll then
    v_credit_account_id := v_liability_account_id;
    v_credit_account_code := v_liability_account_code;
    v_credit_account_name := v_liability_account_name;
  elsif lower(coalesce(v_expense.payment_status, 'pending')) = 'paid'
     and coalesce(v_expense.balance, 0) <= 0.01
     and v_cash_account.id is not null then
    v_credit_account_id := v_cash_account.id;
    v_credit_account_code := v_cash_account.code;
    v_credit_account_name := v_cash_account.name;
  else
    v_credit_account_id := v_liability_account_id;
    select code, name
      into v_credit_account_code, v_credit_account_name
      from public.accounts
     where id = v_credit_account_id;
  end if;

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_credit_account_id,
    v_credit_account_code,
    v_credit_account_name,
    v_description,
    0,
    v_total,
    now(),
    now()
  );
end;
$$;

create or replace function public.delete_expense_journal_entry(p_expense_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_expense_id is null then
    return;
  end if;

  delete from public.journal_entries
   where source_module = 'expenses'
     and source_reference = (
       select e.expense_number
         from public.expenses e
        where e.id = p_expense_id
     );

  delete from public.journal_entries
   where source_module = 'expenses'
     and source_reference = p_expense_id::text;
end;
$$;

create or replace function public.create_expense_payment_journal_entry(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment record;
  v_expense record;
  v_entry_id uuid := gen_random_uuid();
  v_exists boolean;
  v_liability_account_id uuid;
  v_liability_code text;
  v_liability_name text;
  v_cash_account record;
  v_description text;
  v_is_payroll boolean := false;
begin
  select ep.*
    into v_payment
    from public.expense_payments ep
   where ep.id = p_payment_id;

  if not found then
    return;
  end if;

  select e.*
    into v_expense
    from public.expenses e
   where e.id = v_payment.expense_id;

  if not found then
    return;
  end if;

  if lower(coalesce(v_expense.posting_status, 'draft')) <> 'posted' then
    return;
  end if;

  if coalesce(v_payment.amount, 0) = 0 then
    return;
  end if;

  v_is_payroll := (
    v_expense.notes like 'Pago de salario%'
    or v_expense.notes like 'Salario:%'
    or v_expense.reference like 'Semana %'
  );

  select exists (
           select 1
             from public.journal_entries
            where source_module = 'expense_payments'
              and source_reference = v_payment.id::text
         )
    into v_exists;

  if v_exists then
    perform public.delete_expense_payment_journal_entry(v_payment.id);
  end if;

  if v_is_payroll then
    v_liability_code := '2106';
    v_liability_name := 'Sueldos por Pagar';
  else
    v_liability_code := '2105';
    v_liability_name := 'Cuentas por Pagar - Gastos';
  end if;

  v_liability_account_id := coalesce(
    v_expense.liability_account_id,
    public.ensure_account(
      v_expense.tenant_id,
      v_liability_code,
      v_liability_name,
      'liability',
      'currentLiability',
      'Obligaciones por gastos pendientes de pago',
      null
    )
  );

  if v_payment.payment_account_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.id = v_payment.payment_account_id;
  elsif v_payment.payment_method_id is not null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.payment_methods pm
      join public.accounts a on a.id = pm.account_id
     where pm.id = v_payment.payment_method_id;
  end if;

  if v_cash_account.id is null then
    select a.id, a.code, a.name
      into v_cash_account
      from public.accounts a
     where a.code = '1101'
     limit 1;
  end if;

  v_description := format('Pago gasto %s', coalesce(v_expense.expense_number, v_expense.id::text));

  insert into public.journal_entries (
    id,
    tenant_id,
    entry_number,
    entry_date,
    description,
    type,
    source_module,
    source_reference,
    status,
    total_debit,
    total_credit,
    created_at,
    updated_at
  ) values (
    v_entry_id,
    v_expense.tenant_id,
    public.get_next_document_number(v_expense.tenant_id, 'journal_entry'),
    coalesce(v_payment.payment_date, now()),
    v_description,
    'payment',
    'expense_payments',
    v_payment.id::text,
    'posted',
    v_payment.amount,
    v_payment.amount,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_liability_account_id,
    (select code from public.accounts where id = v_liability_account_id),
    (select name from public.accounts where id = v_liability_account_id),
    v_description,
    v_payment.amount,
    0,
    now(),
    now()
  );

  insert into public.journal_lines (
    id,
    tenant_id,
    entry_id,
    account_id,
    account_code,
    account_name,
    description,
    debit_amount,
    credit_amount,
    created_at,
    updated_at
  ) values (
    gen_random_uuid(),
    v_expense.tenant_id,
    v_entry_id,
    v_cash_account.id,
    v_cash_account.code,
    v_cash_account.name,
    v_description,
    0,
    v_payment.amount,
    now(),
    now()
  );
end;
$$;

create or replace function public.delete_expense_payment_journal_entry(p_payment_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_payment_id is null then
    return;
  end if;

  delete from public.journal_entries
   where source_module = 'expense_payments'
     and source_reference = p_payment_id::text;
end;
$$;

create or replace function public.process_expense_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old_posted boolean := lower(coalesce(OLD.posting_status, 'draft')) = 'posted';
  v_new_posted boolean := lower(coalesce(NEW.posting_status, 'draft')) = 'posted';
begin
  if pg_trigger_depth() > 1 then
    if TG_OP = 'DELETE' then
      return OLD;
    else
      return NEW;
    end if;
  end if;

  if TG_OP = 'INSERT' then
    perform public.recalculate_expense_totals(NEW.id);
    -- Journal entry will be created by expense_lines trigger after lines are inserted
    return NEW;

  elsif TG_OP = 'UPDATE' then
    perform public.recalculate_expense_totals(NEW.id);

    if v_old_posted and not v_new_posted then
      perform public.delete_expense_journal_entry(OLD.id);
    elsif not v_old_posted and v_new_posted then
      perform public.create_expense_journal_entry(NEW.id);
    elsif v_old_posted and v_new_posted then
      perform public.delete_expense_journal_entry(OLD.id);
      perform public.create_expense_journal_entry(NEW.id);
    end if;

    return NEW;

  elsif TG_OP = 'DELETE' then
    if v_old_posted then
      perform public.delete_expense_journal_entry(OLD.id);
    end if;
    return OLD;
  end if;

  return NULL;
end;
$$;

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expenses_change'
       and tgrelid = 'public.expenses'::regclass
  ) then
    create trigger trg_expenses_change
      after insert or update or delete on public.expenses
      for each row execute procedure public.process_expense_change();
  end if;
end $$;

create or replace function public.handle_expense_payment_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if TG_OP = 'INSERT' then
    perform public.recalculate_expense_totals(NEW.expense_id);
    perform public.create_expense_payment_journal_entry(NEW.id);
    return NEW;

  elsif TG_OP = 'UPDATE' then
    perform public.recalculate_expense_totals(NEW.expense_id);
    perform public.delete_expense_payment_journal_entry(OLD.id);
    perform public.create_expense_payment_journal_entry(NEW.id);
    return NEW;

  elsif TG_OP = 'DELETE' then
    perform public.recalculate_expense_totals(OLD.expense_id);
    perform public.delete_expense_payment_journal_entry(OLD.id);
    return OLD;
  end if;

  return NULL;
end;
$$;

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expense_payments_change'
       and tgrelid = 'public.expense_payments'::regclass
  ) then
    create trigger trg_expense_payments_change
      after insert or update or delete on public.expense_payments
      for each row execute procedure public.handle_expense_payment_change();
  end if;
end $$;

-- ================================================
-- Trigger for expense_lines changes
-- ================================================
create or replace function public.handle_expense_line_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_expense_id uuid;
  v_posting_status text;
begin
  -- Get the expense_id from the relevant row
  if TG_OP = 'DELETE' then
    v_expense_id := OLD.expense_id;
  else
    v_expense_id := NEW.expense_id;
  end if;

  -- Check if parent expense is posted
  select posting_status into v_posting_status
    from public.expenses
   where id = v_expense_id;

  -- If posted, regenerate journal entry
  if lower(coalesce(v_posting_status, 'draft')) = 'posted' then
    perform public.delete_expense_journal_entry(v_expense_id);
    perform public.create_expense_journal_entry(v_expense_id);
  end if;

  -- Recalculate expense totals
  perform public.recalculate_expense_totals(v_expense_id);

  if TG_OP = 'DELETE' then
    return OLD;
  else
    return NEW;
  end if;
end;
$$;

do $$
begin
  if not exists (
    select 1
      from pg_trigger
     where tgname = 'trg_expense_lines_change'
       and tgrelid = 'public.expense_lines'::regclass
  ) then
    create trigger trg_expense_lines_change
      after insert or update or delete on public.expense_lines
      for each row execute procedure public.handle_expense_line_change();
  end if;
end $$;

create table if not exists stock_movements (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  product_id uuid not null references products(id) on delete cascade,
  warehouse_id uuid,
  type text not null check (type in ('IN','OUT','INVENTORY_ADJUST','TRANSFER_OUT','TRANSFER_IN')),
  movement_type text,
  quantity numeric(12,2) not null,
  reference text,
  notes text,
  date timestamp with time zone not null default now(),
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

create table if not exists journal_entries (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  entry_number text not null,
  entry_date timestamp with time zone not null default now(),
  description text not null,
  type text not null,
  source_module text,
  source_reference text,
  status text not null default 'draft',
  total_debit numeric(14,2) not null default 0,
  total_credit numeric(14,2) not null default 0,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

do $$
begin
  if exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'journal_entries'
       and column_name = 'date'
  ) then
    begin
      alter table public.journal_entries rename column date to entry_date;
    exception when others then
      null;
    end;
  end if;
end $$;

create table if not exists journal_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  entry_id uuid not null references journal_entries(id) on delete cascade,
  account_id uuid not null,
  account_code text not null,
  account_name text not null,
  description text,
  debit_amount numeric(14,2) not null default 0,
  credit_amount numeric(14,2) not null default 0,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

-- ============================================================================
-- INVENTORY AND ACCOUNTING TRACE KERNEL (PHASE 1)
-- Connects source-document actions, stock movements, adjustments, and journals.
-- Historical rows remain nullable and are classified separately by audit tools.
-- ============================================================================

create table if not exists inventory_accounting_operations (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  operation_key text not null,
  source_channel text not null,
  action text not null,
  document_type text not null,
  document_id uuid not null,
  actor_id uuid references auth.users(id) on delete set null,
  executor text not null default 'database_trigger',
  old_status text,
  new_status text,
  before_snapshot jsonb,
  after_snapshot jsonb,
  context jsonb not null default '{}'::jsonb,
  outcome text not null default 'started'
    check (outcome in ('started', 'completed', 'failed', 'reversed', 'superseded')),
  error_code text,
  error_message text,
  started_at timestamp with time zone not null default clock_timestamp(),
  completed_at timestamp with time zone,
  created_at timestamp with time zone not null default clock_timestamp(),
  unique (tenant_id, id),
  unique (tenant_id, operation_key)
);

create table if not exists inventory_accounting_checkpoints (
  id bigint generated by default as identity primary key,
  tenant_id uuid references tenants(id) on delete cascade not null,
  operation_id uuid not null,
  phase text not null check (phase in (
    'accepted',
    'source_snapshotted',
    'inventory_planned',
    'inventory_applied',
    'movement_recorded',
    'accounting_planned',
    'journal_posted',
    'journal_reversed',
    'invariants_verified',
    'completed'
  )),
  outcome text not null default 'completed'
    check (outcome in ('started', 'completed', 'warning', 'failed')),
  entity_type text,
  entity_id uuid,
  payload jsonb not null default '{}'::jsonb,
  created_at timestamp with time zone not null default clock_timestamp(),
  foreign key (tenant_id, operation_id)
    references inventory_accounting_operations(tenant_id, id) on delete restrict
);

create index if not exists idx_inventory_operations_tenant_created
  on inventory_accounting_operations(tenant_id, created_at desc);
create index if not exists idx_inventory_operations_document
  on inventory_accounting_operations(tenant_id, document_type, document_id, created_at desc);
create index if not exists idx_inventory_operations_actor
  on inventory_accounting_operations(actor_id, created_at desc);
create index if not exists idx_inventory_checkpoints_operation
  on inventory_accounting_checkpoints(operation_id, id);

alter table inventory_accounting_operations enable row level security;
alter table inventory_accounting_checkpoints enable row level security;

drop policy if exists inventory_accounting_operations_select
  on inventory_accounting_operations;
create policy inventory_accounting_operations_select
  on inventory_accounting_operations
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

drop policy if exists inventory_accounting_checkpoints_select
  on inventory_accounting_checkpoints;
create policy inventory_accounting_checkpoints_select
  on inventory_accounting_checkpoints
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

revoke all on inventory_accounting_operations from anon, authenticated;
revoke all on inventory_accounting_checkpoints from anon, authenticated;
grant select on inventory_accounting_operations to authenticated;
grant select on inventory_accounting_checkpoints to authenticated;

create or replace function public.prevent_inventory_checkpoint_mutation()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_setting('app.allow_inventory_trace_mutation', true) <> 'true' then
    raise exception 'Inventory/accounting checkpoints are append-only'
      using errcode = 'check_violation';
  end if;
  return case when TG_OP = 'DELETE' then OLD else NEW end;
end;
$$;

drop trigger if exists trg_inventory_checkpoints_immutable
  on inventory_accounting_checkpoints;
create trigger trg_inventory_checkpoints_immutable
  before update or delete on inventory_accounting_checkpoints
  for each row execute function public.prevent_inventory_checkpoint_mutation();

create or replace function public.inventory_trace_document_snapshot(p_row jsonb)
returns jsonb
language sql
immutable
set search_path = public
as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', p_row->'id',
    'status', p_row->'status',
    'source', p_row->'source',
    'invoice_number', p_row->'invoice_number',
    'items', coalesce(p_row->'items', '[]'::jsonb),
    'subtotal', p_row->'subtotal',
    'net_amount', p_row->'net_amount',
    'tax', coalesce(p_row->'tax', p_row->'iva_amount'),
    'total', p_row->'total',
    'paid_amount', p_row->'paid_amount',
    'balance', p_row->'balance',
    'prepayment_model', p_row->'prepayment_model',
    'updated_at', p_row->'updated_at'
  ));
$$;

create or replace function public.append_inventory_accounting_checkpoint(
  p_operation_id uuid,
  p_phase text,
  p_outcome text default 'completed',
  p_entity_type text default null,
  p_entity_id uuid default null,
  p_payload jsonb default '{}'::jsonb
)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_checkpoint_id bigint;
begin
  insert into inventory_accounting_checkpoints (
    tenant_id,
    operation_id,
    phase,
    outcome,
    entity_type,
    entity_id,
    payload
  )
  select
    operation.tenant_id,
    operation.id,
    p_phase,
    coalesce(p_outcome, 'completed'),
    p_entity_type,
    p_entity_id,
    coalesce(p_payload, '{}'::jsonb)
  from inventory_accounting_operations operation
  where operation.id = p_operation_id
  returning id into v_checkpoint_id;

  if v_checkpoint_id is null then
    raise exception 'Inventory/accounting operation % does not exist', p_operation_id
      using errcode = 'foreign_key_violation';
  end if;

  return v_checkpoint_id;
end;
$$;

revoke all on function public.append_inventory_accounting_checkpoint(
  uuid, text, text, text, uuid, jsonb
) from public, anon, authenticated;

create or replace function public.complete_inventory_accounting_operation(
  p_operation_id uuid,
  p_tenant_id uuid,
  p_completion_payload jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_stock_column_drift integer := 0;
  v_movement_arithmetic_errors integer := 0;
  v_unbalanced_journals integer := 0;
begin
  if not exists (
    select 1
      from inventory_accounting_operations operation
     where operation.id = p_operation_id
       and operation.tenant_id = p_tenant_id
  ) then
    raise exception 'Inventory/accounting operation % does not belong to tenant %',
      p_operation_id, p_tenant_id
      using errcode = 'foreign_key_violation';
  end if;

  select count(*)::integer
    into v_stock_column_drift
    from products product
   where product.tenant_id = p_tenant_id
     and product.id in (
       select movement.product_id
         from stock_movements movement
        where movement.operation_id = p_operation_id
     )
     and coalesce(product.inventory_qty, 0)
         <> coalesce(product.stock_quantity, 0);

  select count(*)::integer
    into v_movement_arithmetic_errors
    from stock_movements movement
   where movement.operation_id = p_operation_id
     and (
       movement.stock_before is null
       or movement.stock_after is null
       or round(
         movement.stock_before + case
           when movement.type in ('OUT', 'TRANSFER_OUT') then -abs(movement.quantity)
           when movement.type in ('IN', 'TRANSFER_IN') then abs(movement.quantity)
           else movement.quantity
         end,
         2
       ) <> round(movement.stock_after, 2)
     );

  select count(*)::integer
    into v_unbalanced_journals
    from (
      select entry.id
        from journal_entries entry
        left join journal_lines line
          on line.entry_id = entry.id
         and line.tenant_id = entry.tenant_id
       where entry.operation_id = p_operation_id
       group by entry.id
      having round(coalesce(sum(line.debit_amount), 0), 2)
          <> round(coalesce(sum(line.credit_amount), 0), 2)
    ) broken;

  perform public.append_inventory_accounting_checkpoint(
    p_operation_id,
    'invariants_verified',
    case
      when v_stock_column_drift = 0
       and v_movement_arithmetic_errors = 0
       and v_unbalanced_journals = 0 then 'completed'
      else 'failed'
    end,
    null,
    null,
    jsonb_build_object(
      'stock_column_drift', v_stock_column_drift,
      'movement_arithmetic_errors', v_movement_arithmetic_errors,
      'unbalanced_journals', v_unbalanced_journals
    )
  );

  if v_stock_column_drift > 0
     or v_movement_arithmetic_errors > 0
     or v_unbalanced_journals > 0 then
    raise exception
      'Inventory/accounting invariants failed for operation % (stock drift %, movement errors %, unbalanced journals %)',
      p_operation_id,
      v_stock_column_drift,
      v_movement_arithmetic_errors,
      v_unbalanced_journals
      using errcode = 'check_violation';
  end if;

  update inventory_accounting_operations
     set outcome = 'completed',
         completed_at = clock_timestamp()
   where id = p_operation_id
     and tenant_id = p_tenant_id;

  perform public.append_inventory_accounting_checkpoint(
    p_operation_id,
    'completed',
    'completed',
    null,
    null,
    coalesce(p_completion_payload, '{}'::jsonb)
  );
end;
$$;

revoke all on function public.complete_inventory_accounting_operation(uuid, uuid, jsonb)
  from public, anon, authenticated;

create or replace function public.begin_invoice_inventory_accounting_trace()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old_row jsonb;
  v_new_row jsonb;
  v_effective_row jsonb;
  v_before_snapshot jsonb;
  v_after_snapshot jsonb;
  v_operation_id uuid;
  v_operation_key text;
  v_existing_operation text;
  v_tenant_id uuid;
  v_document_id uuid;
  v_document_type text;
  v_source_channel text;
begin
  v_existing_operation := nullif(
    current_setting('app.inventory_operation_id', true),
    ''
  );

  -- Nested invoice updates caused by payment recalculation or sync belong to
  -- the already-active operation and must not start a disconnected trace.
  if pg_trigger_depth() > 1 and v_existing_operation is not null then
    return case when TG_OP = 'DELETE' then OLD else NEW end;
  end if;

  if TG_OP = 'INSERT' then
    v_new_row := to_jsonb(NEW);
    v_effective_row := v_new_row;
  elsif TG_OP = 'UPDATE' then
    v_old_row := to_jsonb(OLD);
    v_new_row := to_jsonb(NEW);
    v_effective_row := v_new_row;
  else
    v_old_row := to_jsonb(OLD);
    v_effective_row := v_old_row;
  end if;

  v_tenant_id := nullif(v_effective_row->>'tenant_id', '')::uuid;
  v_document_id := nullif(v_effective_row->>'id', '')::uuid;

  if v_tenant_id is null or v_document_id is null then
    raise exception 'Inventory/accounting trace requires tenant_id and document id';
  end if;

  if TG_TABLE_NAME = 'sales_invoices' then
    v_document_type := 'sales_invoice';
    v_source_channel := coalesce(nullif(v_effective_row->>'source', ''), 'manual_sale');
  elsif TG_TABLE_NAME = 'purchase_invoices' then
    v_document_type := 'purchase_invoice';
    v_source_channel := 'purchase_invoice';
  else
    raise exception 'Unsupported trace source table: %', TG_TABLE_NAME;
  end if;

  v_before_snapshot := case
    when v_old_row is null then null
    else public.inventory_trace_document_snapshot(v_old_row)
  end;
  v_after_snapshot := case
    when v_new_row is null then null
    else public.inventory_trace_document_snapshot(v_new_row)
  end;

  v_operation_key := coalesce(
    nullif(current_setting('app.inventory_idempotency_key', true), ''),
    gen_random_uuid()::text
  );

  insert into inventory_accounting_operations (
    tenant_id,
    operation_key,
    source_channel,
    action,
    document_type,
    document_id,
    actor_id,
    executor,
    old_status,
    new_status,
    before_snapshot,
    after_snapshot,
    context
  ) values (
    v_tenant_id,
    format('%s:%s:%s:%s', v_document_type, v_document_id, lower(TG_OP), v_operation_key),
    v_source_channel,
    lower(TG_OP),
    v_document_type,
    v_document_id,
    auth.uid(),
    'database_trigger',
    v_old_row->>'status',
    v_new_row->>'status',
    v_before_snapshot,
    v_after_snapshot,
    jsonb_build_object(
      'table', TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
      'trigger_depth', pg_trigger_depth(),
      'transaction_id', txid_current()::text,
      'before_hash', case when v_before_snapshot is null then null else md5(v_before_snapshot::text) end,
      'after_hash', case when v_after_snapshot is null then null else md5(v_after_snapshot::text) end
    )
  )
  returning id into v_operation_id;

  perform set_config('app.inventory_operation_id', v_operation_id::text, true);
  perform set_config('app.inventory_source_document_type', v_document_type, true);
  perform set_config('app.inventory_source_document_id', v_document_id::text, true);
  perform set_config('app.inventory_source_channel', v_source_channel, true);

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'accepted',
    'started',
    v_document_type,
    v_document_id,
    jsonb_build_object(
      'action', lower(TG_OP),
      'old_status', v_old_row->>'status',
      'new_status', v_new_row->>'status'
    )
  );

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'source_snapshotted',
    'completed',
    v_document_type,
    v_document_id,
    jsonb_build_object(
      'before', v_before_snapshot,
      'after', v_after_snapshot
    )
  );

  return case when TG_OP = 'DELETE' then OLD else NEW end;
end;
$$;

alter table stock_movements
  add column if not exists operation_id uuid,
  add column if not exists source_document_type text,
  add column if not exists source_document_id uuid,
  add column if not exists created_by uuid references auth.users(id),
  add column if not exists stock_before numeric(12,2),
  add column if not exists stock_after numeric(12,2),
  add column if not exists reversal_of_id uuid references stock_movements(id);

alter table stock_adjustments
  add column if not exists operation_id uuid,
  add column if not exists source_document_type text,
  add column if not exists source_document_id uuid;

alter table journal_entries
  add column if not exists operation_id uuid,
  add column if not exists source_document_type text,
  add column if not exists source_document_id uuid,
  add column if not exists created_by uuid references auth.users(id),
  add column if not exists reversal_of_id uuid references journal_entries(id);

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'stock_movements_inventory_operation_fkey'
      and conrelid = 'public.stock_movements'::regclass
  ) then
    alter table stock_movements
      add constraint stock_movements_inventory_operation_fkey
      foreign key (tenant_id, operation_id)
      references inventory_accounting_operations(tenant_id, id) on delete restrict;
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'stock_adjustments_inventory_operation_fkey'
      and conrelid = 'public.stock_adjustments'::regclass
  ) then
    alter table stock_adjustments
      add constraint stock_adjustments_inventory_operation_fkey
      foreign key (tenant_id, operation_id)
      references inventory_accounting_operations(tenant_id, id) on delete restrict;
  end if;

  if not exists (
    select 1 from pg_constraint
    where conname = 'journal_entries_inventory_operation_fkey'
      and conrelid = 'public.journal_entries'::regclass
  ) then
    alter table journal_entries
      add constraint journal_entries_inventory_operation_fkey
      foreign key (tenant_id, operation_id)
      references inventory_accounting_operations(tenant_id, id) on delete restrict;
  end if;
end $$;

