create or replace function public.checkpoint_stock_movement_trace()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if NEW.operation_id is null then
    return NEW;
  end if;

  perform public.append_inventory_accounting_checkpoint(
    NEW.operation_id,
    'inventory_applied',
    'completed',
    'product',
    NEW.product_id,
    jsonb_build_object(
      'stock_before', NEW.stock_before,
      'stock_after', NEW.stock_after,
      'movement_type', NEW.movement_type
    )
  );

  perform public.append_inventory_accounting_checkpoint(
    NEW.operation_id,
    'movement_recorded',
    'completed',
    'stock_movement',
    NEW.id,
    jsonb_build_object(
      'product_id', NEW.product_id,
      'type', NEW.type,
      'quantity', NEW.quantity,
      'stock_before', NEW.stock_before,
      'stock_after', NEW.stock_after,
      'reference', NEW.reference,
      'reversal_of_id', NEW.reversal_of_id
    )
  );
  return NEW;
end;
$$;

