-- ============================================================================
-- STOCK MOVEMENTS LOGIC (View, Triggers)
-- Added to support unified stock history and purchase corrections.
-- ============================================================================

-- 1. Stock Movements View (Modern: Reads from table, not calculation)
drop view if exists stock_movements_view cascade;

-- Helper: safe lookup (avoids hard dependency when bootstrapping from scratch)
create or replace function public.get_mechanic_job_number(p_job_id uuid, p_tenant_id uuid)
returns text
language plpgsql
stable
set search_path = public
as $$
declare
  v_job_number text;
begin
  if p_job_id is null then
    return null;
  end if;

  if to_regclass('public.mechanic_jobs') is null then
    return null;
  end if;

  execute 'select job_number from public.mechanic_jobs where id = $1 and tenant_id = $2'
    into v_job_number
    using p_job_id, p_tenant_id;

  return v_job_number;
exception
  when others then
    return null;
end;
$$;

create view stock_movements_view as
with movement_documents as (
  select
    sm.id,
    sm.product_id,
    p.name as product_name,
    p.sku as product_sku,
    sm.date as transaction_date,
    sm.type,
    sm.movement_type as raw_movement_type,
    sm.reference,
    case
      when sm.type = 'OUT' then -abs(sm.quantity)
      when sm.type = 'IN' then abs(sm.quantity)
      else sm.quantity
    end as quantity,
    sm.notes,
    sm.created_by,
    sm.stock_before as persisted_stock_before,
    sm.stock_after as persisted_stock_after,
    sm.created_at,
    sm.tenant_id,
    case
      when sm.source_document_id is not null then sm.source_document_id
      when coalesce(sm.reference, '') ~ '^sales_invoice:[0-9a-fA-F-]{36}$'
        then split_part(sm.reference, ':', 2)::uuid
      when coalesce(sm.reference, '') ~ '^purchase_invoice:[0-9a-fA-F-]{36}$'
        then split_part(sm.reference, ':', 2)::uuid
      when coalesce(sm.reference, '') ~ '^mechanic_job:[0-9a-fA-F-]{36}$'
        then split_part(sm.reference, ':', 2)::uuid
      else null::uuid
    end as document_id,
    case
      when nullif(sm.source_document_type, '') is not null then sm.source_document_type
      when coalesce(sm.reference, '') like 'sales_invoice:%' then 'sales_invoice'
      when coalesce(sm.reference, '') like 'purchase_invoice:%' then 'purchase_invoice'
      when coalesce(sm.reference, '') like 'mechanic_job:%' then 'mechanic_job'
      else null::text
    end as document_type
  from stock_movements sm
  left join products p
    on nullif(sm.product_id::text, '')::uuid = p.id
   and sm.tenant_id = p.tenant_id
),
movements_with_resolution as (
  select
    md.id,
    md.product_id,
    md.product_name,
    md.product_sku,
    md.transaction_date,
    case
      when md.document_type = 'sales_invoice' then 'sale'
      when md.document_type = 'purchase_invoice' then 'purchase'
      when md.document_type = 'mechanic_job' then 'sale'
      when coalesce(md.raw_movement_type, '') in ('purchase', 'purchase_invoice', 'purchase_invoice_reversal', 'manual_purchase') then 'purchase'
      when coalesce(md.raw_movement_type, '') in ('sale', 'sales_invoice', 'sales_invoice_component', 'sales_invoice_reversal', 'manual_sale') then 'sale'
      when coalesce(md.raw_movement_type, '') in ('transfer', 'transfer_in', 'transfer_out') then 'transfer'
      when coalesce(md.raw_movement_type, '') in ('manual', 'correction', 'initial', 'damage', 'loss', 'found', 'import', 'adjustment', 'inventory_adjust', 'inventory_adjustment', 'count_gain', 'count_loss', 'theft', 'internal_use') then 'adjustment'
      else 'adjustment'
    end as movement_type,
    case
      when md.document_type = 'sales_invoice' and coalesce(md.raw_movement_type, '') = 'sales_invoice_reversal' then 'sales_invoice_reversal'
      when md.document_type = 'sales_invoice' then coalesce(si.source, 'sale')
      when md.document_type = 'purchase_invoice' and coalesce(md.raw_movement_type, '') = 'purchase_invoice_reversal' then 'purchase_invoice_reversal'
      when md.document_type = 'purchase_invoice' then 'purchase_invoice'
      when md.document_type = 'mechanic_job' then 'mechanic_job'
      when nullif(trim(coalesce(md.raw_movement_type, '')), '') is not null then md.raw_movement_type
      else 'manual'
    end as source,
    case
      when md.document_type in ('sales_invoice', 'purchase_invoice', 'mechanic_job') then md.document_id
      when sa.id is not null then sa.id
      else null::uuid
    end as reference_id,
    case
      when md.document_type = 'sales_invoice' then coalesce(nullif(si.invoice_number, ''), md.reference)
      when md.document_type = 'purchase_invoice' then coalesce(nullif(pi.invoice_number, ''), md.reference)
      when md.document_type = 'mechanic_job' then coalesce(
        nullif(public.get_mechanic_job_number(md.document_id, md.tenant_id), ''),
        md.reference
      )
      when sa.id is not null then coalesce(
        nullif(sa.reference, ''),
        nullif(trim(coalesce(md.reference, '')), ''),
        nullif(trim(coalesce(md.notes, '')), ''),
        null::text
      )
      when nullif(trim(coalesce(md.reference, '')), '') is not null then md.reference
      when nullif(trim(coalesce(md.notes, '')), '') is not null then md.notes
      else null::text
    end as reference_number,
    md.quantity,
    md.notes,
    md.persisted_stock_before,
    md.persisted_stock_after,
    sa.adjustment_origin,
    coalesce(md.created_by, sa.created_by) as created_by,
    md.created_at,
    md.tenant_id
  from movement_documents md
  left join sales_invoices si
    on md.document_type = 'sales_invoice'
   and md.document_id = si.id
   and md.tenant_id = si.tenant_id
  left join purchase_invoices pi
    on md.document_type = 'purchase_invoice'
   and md.document_id = pi.id
   and md.tenant_id = pi.tenant_id
  left join stock_adjustments sa
    on md.document_type is null
   and md.tenant_id = sa.tenant_id
   and md.product_id = sa.product_id
   and md.created_at = sa.created_at
   and md.quantity = sa.quantity
   and coalesce(md.raw_movement_type, '') = sa.adjustment_type
),
movements_with_running_stock as (
  select
    m.*,
    greatest(coalesce(p.stock_quantity, 0), coalesce(p.inventory_qty, 0)) as current_stock,
    greatest(coalesce(p.stock_quantity, 0), coalesce(p.inventory_qty, 0)) - coalesce(
      sum(m.quantity) over (
        partition by m.product_id, m.tenant_id
        order by m.transaction_date desc nulls last, m.created_at desc, m.id desc
        rows between unbounded preceding and 1 preceding
      ),
      0
    )::integer as calculated_stock_after
  from movements_with_resolution m
  left join products p
    on nullif(m.product_id::text, '')::uuid = p.id
   and m.tenant_id = p.tenant_id
)
select
  id,
  product_id,
  product_name,
  product_sku,
  transaction_date,
  movement_type,
  source,
  reference_id,
  reference_number,
  quantity,
  coalesce(persisted_stock_before, calculated_stock_after - quantity)::integer as stock_before,
  coalesce(persisted_stock_after, calculated_stock_after)::integer as stock_after,
  notes,
  adjustment_origin,
  created_by,
  created_at,
  tenant_id
from movements_with_running_stock;

alter view stock_movements_view set (security_invoker = on);

-- 2. Sync Stock Adjustments -> Stock Movements
create or replace function sync_stock_adjustment_to_movement()
returns trigger as $$
begin
  insert into stock_movements (
    tenant_id,
    product_id,
    date,
    type,
    movement_type,
    reference,
    quantity,
    notes,
    created_at
  ) values (
    NEW.tenant_id,
    NEW.product_id,
    coalesce(NEW.adjustment_date, NEW.created_at), -- transaction date
    case when NEW.quantity >= 0 then 'IN' else 'OUT' end,
    NEW.adjustment_type,
    NEW.reference,
    abs(NEW.quantity),
    NEW.reason,
    NEW.created_at
  );
  return NEW;
end;
$$ language plpgsql security definer;

drop trigger if exists trg_sync_adjustment_to_movement on stock_adjustments;
create trigger trg_sync_adjustment_to_movement
  after insert on stock_adjustments
  for each row
  execute function sync_stock_adjustment_to_movement();

drop function if exists public.apply_inventory_stock_adjustment(uuid, integer, text, text, text, timestamp with time zone);

create or replace function public.apply_inventory_stock_adjustment(
  p_product_id uuid,
  p_quantity integer,
  p_type text,
  p_reason_type text,
  p_note text default null,
  p_effective_at timestamp with time zone default now(),
  p_adjustment_origin text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_product public.products%rowtype;
  v_delta integer;
  v_stock_before integer;
  v_stock_after integer;
  v_reason_label text;
  v_reason text;
  v_adjustment_type text;
  v_reference text;
  v_adjustment_origin text;
  v_adjustment_origin_label text;
  v_adjustment_date timestamp with time zone := coalesce(p_effective_at, now());
  v_created_at timestamp with time zone := now();
  v_adjustment_id uuid;
  v_operation_id uuid;
  v_operation_key text;
  v_source_channel text;
  v_movement_id uuid;
  v_inventory_account_id uuid;
  v_counterpart_account_id uuid;
  v_counterpart_account_code text;
  v_counterpart_account_name text;
  v_inventory_value numeric(14,2) := 0;
  v_entry_id uuid;
  v_entry_number text;
  v_description text;
begin
  if p_type not in ('IN', 'OUT') then
    raise exception 'Invalid stock adjustment type: %', p_type
      using errcode = 'check_violation';
  end if;

  if p_quantity <= 0 then
    raise exception 'Stock adjustment quantity must be positive: %', p_quantity
      using errcode = 'check_violation';
  end if;

  if p_reason_type not in ('manual', 'count', 'loss', 'damage', 'theft', 'internal_use', 'found') then
    raise exception 'Invalid stock adjustment reason type: %', p_reason_type
      using errcode = 'check_violation';
  end if;

  if p_type = 'IN' and p_reason_type in ('loss', 'damage', 'theft', 'internal_use') then
    raise exception 'Reason % is only valid for stock decreases', p_reason_type
      using errcode = 'check_violation';
  end if;

  if p_type = 'OUT' and p_reason_type = 'found' then
    raise exception 'Reason % is only valid for stock increases', p_reason_type
      using errcode = 'check_violation';
  end if;

  v_adjustment_origin := nullif(trim(coalesce(p_adjustment_origin, '')), '');

  if v_adjustment_origin is not null
     and v_adjustment_origin not in ('product_form', 'mass_edit_panel', 'manual_service') then
    raise exception 'Invalid stock adjustment origin: %', v_adjustment_origin
      using errcode = 'check_violation';
  end if;

  select *
    into v_product
    from public.products
   where id = p_product_id
     and tenant_id = public.user_tenant_id()
   for update;

  if not found then
    raise exception 'Product % not found for current tenant', p_product_id
      using errcode = 'foreign_key_violation';
  end if;

  if coalesce(v_product.product_type, 'product') = 'service'
     or coalesce(v_product.track_stock, true) = false then
    raise exception 'Product % does not track stock', coalesce(v_product.name, p_product_id::text)
      using errcode = 'check_violation';
  end if;

  v_delta := case when p_type = 'IN' then p_quantity else -p_quantity end;
  v_stock_before := greatest(coalesce(v_product.inventory_qty, 0), coalesce(v_product.stock_quantity, 0));
  v_stock_after := v_stock_before + v_delta;

  if v_stock_after < 0 then
    raise exception 'Stock cannot go negative for product %', coalesce(v_product.name, p_product_id::text)
      using errcode = 'check_violation';
  end if;

  case p_reason_type
    when 'count' then
      v_adjustment_type := case when p_type = 'IN' then 'count_gain' else 'count_loss' end;
      v_reason_label := 'Regularización por conteo';
    when 'loss' then
      v_adjustment_type := 'loss';
      v_reason_label := 'Merma';
    when 'damage' then
      v_adjustment_type := 'damage';
      v_reason_label := 'Daño';
    when 'theft' then
      v_adjustment_type := 'theft';
      v_reason_label := 'Robo / extravío';
    when 'internal_use' then
      v_adjustment_type := 'internal_use';
      v_reason_label := 'Uso interno / taller';
    when 'found' then
      v_adjustment_type := 'found';
      v_reason_label := 'Hallazgo / recuperación';
    else
      v_adjustment_type := 'manual';
      v_reason_label := 'Ajuste Manual';
  end case;

  v_reason := case
    when nullif(trim(coalesce(p_note, '')), '') is null then v_reason_label
    else format('%s: %s', v_reason_label, trim(p_note))
  end;

  case v_adjustment_origin
    when 'product_form' then v_adjustment_origin_label := 'Formulario producto';
    when 'mass_edit_panel' then v_adjustment_origin_label := 'Edicion masiva';
    when 'manual_service' then v_adjustment_origin_label := 'Ajuste manual';
    else v_adjustment_origin_label := null;
  end case;

  v_reference := public.get_next_document_number(v_product.tenant_id, 'stock_adjustment');
  v_inventory_value := round(abs(v_delta) * greatest(coalesce(v_product.cost, 0), 0), 2);
  v_description := case
    when v_adjustment_origin_label is null then format('%s %s - %s', v_reason_label, v_reference, v_product.name)
    else format('%s [%s] %s - %s', v_reason_label, v_adjustment_origin_label, v_reference, v_product.name)
  end;

  v_adjustment_id := gen_random_uuid();
  v_source_channel := coalesce(v_adjustment_origin, 'manual_stock_adjustment');
  v_operation_key := format(
    'stock_adjustment:%s:adjust_stock:%s',
    v_adjustment_id,
    coalesce(
      nullif(current_setting('app.inventory_idempotency_key', true), ''),
      gen_random_uuid()::text
    )
  );

  insert into public.inventory_accounting_operations (
    tenant_id,
    operation_key,
    source_channel,
    action,
    document_type,
    document_id,
    actor_id,
    executor,
    before_snapshot,
    after_snapshot,
    context
  ) values (
    v_product.tenant_id,
    v_operation_key,
    v_source_channel,
    'adjust_stock',
    'stock_adjustment',
    v_adjustment_id,
    auth.uid(),
    'database_rpc',
    jsonb_build_object(
      'product_id', v_product.id,
      'stock', v_stock_before,
      'unit_cost', coalesce(v_product.cost, 0)
    ),
    jsonb_build_object(
      'product_id', v_product.id,
      'stock', v_stock_after,
      'unit_cost', coalesce(v_product.cost, 0)
    ),
    jsonb_build_object(
      'adjustment_type', v_adjustment_type,
      'adjustment_origin', v_adjustment_origin,
      'reason', v_reason,
      'effective_at', v_adjustment_date,
      'inventory_value', v_inventory_value,
      'transaction_id', txid_current()::text
    )
  )
  returning id into v_operation_id;

  perform set_config('app.inventory_operation_id', v_operation_id::text, true);
  perform set_config('app.inventory_source_document_type', 'stock_adjustment', true);
  perform set_config('app.inventory_source_document_id', v_adjustment_id::text, true);
  perform set_config('app.inventory_source_channel', v_source_channel, true);

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'accepted',
    'started',
    'stock_adjustment',
    v_adjustment_id,
    jsonb_build_object('action', 'adjust_stock', 'source_channel', v_source_channel)
  );

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'source_snapshotted',
    'completed',
    'stock_adjustment',
    v_adjustment_id,
    jsonb_build_object(
      'product_id', v_product.id,
      'stock_before', v_stock_before,
      'stock_after', v_stock_after,
      'reason', v_reason
    )
  );

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'inventory_planned',
    'completed',
    'product',
    v_product.id,
    jsonb_build_object(
      'signed_delta', v_delta,
      'stock_before', v_stock_before,
      'stock_after', v_stock_after
    )
  );

  perform public.append_inventory_accounting_checkpoint(
    v_operation_id,
    'accounting_planned',
    'completed',
    'stock_adjustment',
    v_adjustment_id,
    jsonb_build_object(
      'inventory_value', v_inventory_value,
      'journal_expected', v_inventory_value > 0
    )
  );

  perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

  update public.products
     set inventory_qty = v_stock_after,
         stock_quantity = v_stock_after,
         updated_at = v_created_at
   where id = v_product.id
     and tenant_id = v_product.tenant_id;

  insert into public.stock_adjustments (
    id,
    tenant_id,
    product_id,
    adjustment_type,
    quantity,
    stock_before,
    stock_after,
    reason,
    reference,
    adjustment_origin,
    adjustment_date,
    created_by,
    created_at
  ) values (
    v_adjustment_id,
    v_product.tenant_id,
    v_product.id,
    v_adjustment_type,
    v_delta,
    v_stock_before,
    v_stock_after,
    v_reason,
    v_reference,
    v_adjustment_origin,
    v_adjustment_date,
    auth.uid(),
    v_created_at
  )
  returning id into v_adjustment_id;

  if v_inventory_value > 0 then
    v_inventory_account_id := public.ensure_account(
      v_product.tenant_id,
      '1105',
      'Inventario de Productos',
      'asset',
      'currentAsset',
      'Valor de productos y repuestos en stock',
      null
    );

    if p_type = 'OUT' then
      case p_reason_type
        when 'internal_use' then
          v_counterpart_account_code := '5101';
          v_counterpart_account_name := 'Consumibles de Taller';
        when 'damage' then
          v_counterpart_account_code := '6196';
          v_counterpart_account_name := 'Pérdidas por Daño de Inventario';
        when 'theft' then
          v_counterpart_account_code := '6197';
          v_counterpart_account_name := 'Pérdidas por Robo de Inventario';
        when 'loss' then
          v_counterpart_account_code := '6195';
          v_counterpart_account_name := 'Mermas de Inventario';
        else
          v_counterpart_account_code := '6198';
          v_counterpart_account_name := 'Diferencias de Inventario';
      end case;

      v_counterpart_account_id := public.ensure_account(
        v_product.tenant_id,
        v_counterpart_account_code,
        v_counterpart_account_name,
        'expense',
        'operatingExpense',
        'Ajustes negativos de inventario registrados manualmente',
        null
      );
    else
      case p_reason_type
        when 'found' then
          v_counterpart_account_code := '4202';
          v_counterpart_account_name := 'Recuperaciones de Inventario';
        else
          v_counterpart_account_code := '4203';
          v_counterpart_account_name := 'Ajustes Positivos de Inventario';
      end case;

      v_counterpart_account_id := public.ensure_account(
        v_product.tenant_id,
        v_counterpart_account_code,
        v_counterpart_account_name,
        'income',
        'nonOperatingIncome',
        'Ingresos no operacionales derivados de ajustes positivos de inventario',
        null
      );
    end if;

    v_entry_id := gen_random_uuid();
    v_entry_number := public.get_next_document_number(v_product.tenant_id, 'journal_entry');

    insert into public.journal_entries (
      id,
      tenant_id,
      entry_number,
      entry_date,
      description,
      type,
      source_module,
      source_reference,
      status,
      total_debit,
      total_credit,
      created_at,
      updated_at
    ) values (
      v_entry_id,
      v_product.tenant_id,
      v_entry_number,
      v_adjustment_date,
      v_description,
      'adjustment',
      'stock_adjustment',
      v_adjustment_id::text,
      'posted',
      v_inventory_value,
      v_inventory_value,
      v_created_at,
      v_created_at
    );

    if p_type = 'OUT' then
      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_counterpart_account_id,
        v_product.tenant_id,
        v_counterpart_account_code,
        v_counterpart_account_name,
        v_description,
        v_inventory_value,
        0,
        v_created_at,
        v_created_at
      );

      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_inventory_account_id,
        v_product.tenant_id,
        '1105',
        'Inventario de Productos',
        v_description,
        0,
        v_inventory_value,
        v_created_at,
        v_created_at
      );
    else
      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_inventory_account_id,
        v_product.tenant_id,
        '1105',
        'Inventario de Productos',
        v_description,
        v_inventory_value,
        0,
        v_created_at,
        v_created_at
      );

      insert into public.journal_lines (
        id,
        entry_id,
        account_id,
        tenant_id,
        account_code,
        account_name,
        description,
        debit_amount,
        credit_amount,
        created_at,
        updated_at
      ) values (
        gen_random_uuid(),
        v_entry_id,
        v_counterpart_account_id,
        v_product.tenant_id,
        v_counterpart_account_code,
        v_counterpart_account_name,
        v_description,
        0,
        v_inventory_value,
        v_created_at,
        v_created_at
      );
    end if;
  end if;

  perform set_config('app.skip_stock_adjustment_trigger', '', true);

  select sm.id
    into v_movement_id
    from public.stock_movements sm
   where sm.tenant_id = v_product.tenant_id
     and sm.product_id = v_product.id
     and sm.created_at = v_created_at
     and sm.movement_type = v_adjustment_type
   order by sm.id desc
   limit 1;

  perform public.complete_inventory_accounting_operation(
    v_operation_id,
    v_product.tenant_id,
    jsonb_build_object(
      'adjustment_id', v_adjustment_id,
      'movement_id', v_movement_id,
      'journal_entry_id', v_entry_id
    )
  );

  perform set_config('app.inventory_operation_id', '', true);
  perform set_config('app.inventory_source_document_type', '', true);
  perform set_config('app.inventory_source_document_id', '', true);
  perform set_config('app.inventory_source_channel', '', true);

  return jsonb_build_object(
    'operation_id', v_operation_id,
    'adjustment_id', v_adjustment_id,
    'movement_id', v_movement_id,
    'reference_number', v_reference,
    'product_id', v_product.id,
    'product_name', v_product.name,
    'product_sku', v_product.sku,
    'type', p_type,
    'adjustment_type', v_adjustment_type,
    'quantity', v_delta,
    'stock_before', v_stock_before,
    'stock_after', v_stock_after,
    'reason', v_reason,
    'adjustment_origin', v_adjustment_origin,
    'adjustment_date', v_adjustment_date,
    'created_at', v_created_at,
    'journal_entry_id', v_entry_id,
    'journal_entry_number', v_entry_number,
    'inventory_value', v_inventory_value
  );
exception
  when others then
    perform set_config('app.skip_stock_adjustment_trigger', '', true);
    perform set_config('app.inventory_operation_id', '', true);
    perform set_config('app.inventory_source_document_type', '', true);
    perform set_config('app.inventory_source_document_id', '', true);
    perform set_config('app.inventory_source_channel', '', true);
    raise;
end;
$$;

grant execute on function public.apply_inventory_stock_adjustment(uuid, integer, text, text, text, timestamp with time zone, text) to authenticated;

drop function if exists public.apply_manual_stock_adjustment(uuid, integer, text, text);

create or replace function public.apply_manual_stock_adjustment(
  p_product_id uuid,
  p_quantity integer,
  p_type text,
  p_reason text default 'Ajuste Manual',
  p_adjustment_origin text default 'manual_service'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  return public.apply_inventory_stock_adjustment(
    p_product_id,
    p_quantity,
    p_type,
    'count',
    p_reason,
    now(),
    p_adjustment_origin
  );
end;
$$;

grant execute on function public.apply_manual_stock_adjustment(uuid, integer, text, text, text) to authenticated;

create or replace function public.get_stock_adjustment_details(
  p_adjustment_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_adjustment record;
  v_entry record;
  v_counterpart_account_code text;
  v_counterpart_account_name text;
  v_counterpart_debit numeric;
  v_counterpart_credit numeric;
begin
  select
    sa.id,
    sa.tenant_id,
    sa.product_id,
    sa.adjustment_type,
    sa.quantity,
    sa.stock_before,
    sa.stock_after,
    sa.reason,
    sa.reference,
    sa.adjustment_origin,
    sa.adjustment_date,
    sa.created_at,
    sa.created_by,
    p.name as product_name,
    p.sku as product_sku,
    p.cost as unit_cost,
    au.email as created_by_email,
    abs(sa.quantity) * greatest(coalesce(p.cost, 0), 0) as inventory_value
  into v_adjustment
  from public.stock_adjustments sa
  join public.products p
    on p.id = sa.product_id
   and p.tenant_id = sa.tenant_id
  left join auth.users au
    on au.id = sa.created_by
  where sa.id = p_adjustment_id
    and sa.tenant_id = public.user_tenant_id();

  if not found then
    raise exception 'Stock adjustment % not found for current tenant', p_adjustment_id
      using errcode = 'foreign_key_violation';
  end if;

  select
    je.id,
    je.entry_number,
    je.entry_date,
    je.description,
    je.total_debit,
    je.total_credit
  into v_entry
  from public.journal_entries je
  where je.tenant_id = v_adjustment.tenant_id
    and je.source_module = 'stock_adjustment'
    and je.source_reference = v_adjustment.id::text
  order by je.created_at desc
  limit 1;

  if v_entry.id is not null then
    select
      jl.account_code,
      jl.account_name,
      jl.debit_amount,
      jl.credit_amount
    into v_counterpart_account_code,
         v_counterpart_account_name,
         v_counterpart_debit,
         v_counterpart_credit
    from public.journal_lines jl
    where jl.entry_id = v_entry.id
      and jl.account_code <> '1105'
    order by greatest(jl.debit_amount, jl.credit_amount) desc, jl.created_at asc
    limit 1;
  end if;

  return jsonb_build_object(
    'id', v_adjustment.id,
    'product_id', v_adjustment.product_id,
    'product_name', v_adjustment.product_name,
    'product_sku', v_adjustment.product_sku,
    'adjustment_type', v_adjustment.adjustment_type,
    'reference_number', v_adjustment.reference,
    'quantity', v_adjustment.quantity,
    'stock_before', v_adjustment.stock_before,
    'stock_after', v_adjustment.stock_after,
    'reason', v_adjustment.reason,
    'adjustment_origin', v_adjustment.adjustment_origin,
    'adjustment_date', v_adjustment.adjustment_date,
    'created_at', v_adjustment.created_at,
    'created_by', v_adjustment.created_by,
    'created_by_email', v_adjustment.created_by_email,
    'unit_cost', v_adjustment.unit_cost,
    'inventory_value', v_adjustment.inventory_value,
    'journal_entry_id', v_entry.id,
    'journal_entry_number', v_entry.entry_number,
    'journal_entry_date', v_entry.entry_date,
    'journal_entry_description', v_entry.description,
    'counterpart_account_code', v_counterpart_account_code,
    'counterpart_account_name', v_counterpart_account_name,
    'counterpart_debit', v_counterpart_debit,
    'counterpart_credit', v_counterpart_credit
  );
end;
$$;

grant execute on function public.get_stock_adjustment_details(uuid) to authenticated;

-- 3. Handle Purchase Invoice Deletion (Stock Reversal)
create or replace function public.handle_purchase_invoice_deletion()
returns trigger
language plpgsql
security definer
as $$
declare
  v_item jsonb;
  v_product_id uuid;
  v_quantity numeric;
begin
  -- Only proceed if the invoice was effectively adding stock
  if OLD.status in ('received', 'paid') then

    -- Iterate over the deleted invoice items
    for v_item in select * from jsonb_array_elements(OLD.items)
    loop
      v_product_id := (v_item->>'product_id')::uuid;
      v_quantity := (v_item->>'quantity')::numeric;

      if v_product_id is not null and v_quantity > 0 then
        -- CRITICAL: Prevent the generic trigger from firing and creating a duplicate/mislabeled adjustment
        perform set_config('app.skip_stock_adjustment_trigger', 'true', true);

        -- Reverse the stock (Subtract the quantity that was added)
        update products
        set stock_quantity = stock_quantity - v_quantity,
            inventory_qty = inventory_qty - v_quantity
        where id = v_product_id;

        -- Manually log the reversal in stock_adjustments to keep history clean
        insert into stock_adjustments (
            tenant_id,
            product_id,
            adjustment_type,
            quantity,
            stock_before,
            stock_after,
            reason,
            reference,
            created_by
        )
        select
            OLD.tenant_id,
            v_product_id,
            'correction',           -- Type: Correction
            -v_quantity,            -- Quantity: Negative (removal)
            p.stock_quantity + v_quantity, -- Stock Before (re-calculated)
            p.stock_quantity,       -- Stock After (current)
            'Reversal: Purchase Invoice Deleted #' || coalesce(OLD.invoice_number, OLD.id::text),
            OLD.id::text,           -- Reference: Deleted Invoice ID
            auth.uid()
        from products p
        where p.id = v_product_id;

      end if;
    end loop;
  end if;

  return OLD;
end;
$$;

drop trigger if exists trg_handle_purchase_invoice_deletion on purchase_invoices;
create trigger trg_handle_purchase_invoice_deletion
  before delete on purchase_invoices
  for each row
  execute function handle_purchase_invoice_deletion();


do $$
declare
  v_account_id_is_uuid boolean;
begin
  select exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'journal_lines'
       and column_name = 'account_id'
       and data_type = 'uuid'
  ) into v_account_id_is_uuid;

  if not v_account_id_is_uuid then
    begin
      alter table public.journal_lines drop column account_id;
    exception when undefined_column then
      null;
    end;

    alter table public.journal_lines
      add column account_id uuid;
  end if;
end $$;

do $$
begin
  begin
    alter table public.journal_lines
      alter column account_id set not null;
  exception when others then
    null;
  end;
end $$;

do $$
declare
  v_has_old_entry_column boolean;
  v_has_new_entry_column boolean;
  rec record;
begin
  select exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'journal_lines'
       and column_name = 'journal_entry_id'
  ) into v_has_old_entry_column;

  select exists (
    select 1
      from information_schema.columns
     where table_schema = 'public'
       and table_name = 'journal_lines'
       and column_name = 'entry_id'
  ) into v_has_new_entry_column;

  if not v_has_old_entry_column then
    return;
  end if;

  if not v_has_new_entry_column then
    alter table public.journal_lines rename column journal_entry_id to entry_id;
    return;
  end if;

  execute 'update public.journal_lines set entry_id = journal_entry_id where entry_id is null';

  for rec in (
    select constraint_name
      from information_schema.constraint_column_usage
     where table_schema = 'public'
       and table_name = 'journal_lines'
       and column_name = 'journal_entry_id'
  ) loop
    execute format('alter table public.journal_lines drop constraint %I', rec.constraint_name);
  end loop;

  alter table public.journal_lines drop column journal_entry_id;

  begin
    alter table public.journal_lines
      alter column entry_id set not null;
  exception when others then
    null;
  end;
end $$;

alter table public.stock_movements
  add column if not exists date timestamp with time zone not null default now(),
  add column if not exists created_at timestamp with time zone not null default now(),
  add column if not exists updated_at timestamp with time zone not null default now(),
  add column if not exists type text,
  add column if not exists movement_type text,
  add column if not exists quantity numeric(12,2),
  add column if not exists reference text,
  add column if not exists notes text;

do $$
begin
  begin
    alter table public.stock_movements
      alter column warehouse_id drop not null;
  exception when others then
    null;
  end;

  begin
    alter table public.stock_movements
      alter column movement_type drop not null;
  exception when others then
    null;
  end;
end $$;

alter table public.journal_entries
  add column if not exists entry_number text,
  add column if not exists entry_date timestamp with time zone not null default now(),
  add column if not exists description text,
  add column if not exists type text,
  add column if not exists source_module text,
  add column if not exists source_reference text,
  add column if not exists status text not null default 'draft',
  add column if not exists total_debit numeric(14,2) not null default 0,
  add column if not exists total_credit numeric(14,2) not null default 0,
  add column if not exists created_at timestamp with time zone not null default now(),
  add column if not exists updated_at timestamp with time zone not null default now();

alter table public.journal_lines
  add column if not exists entry_id uuid,
  add column if not exists account_id uuid,
  add column if not exists account_code text,
  add column if not exists account_name text,
  add column if not exists description text,
  add column if not exists debit_amount numeric(14,2) not null default 0,
  add column if not exists credit_amount numeric(14,2) not null default 0,
  add column if not exists created_at timestamp with time zone not null default now(),
  add column if not exists updated_at timestamp with time zone not null default now();

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.journal_lines'::regclass
      and contype = 'f'
      and conname = 'journal_lines_entry_id_fkey'
  ) then
    alter table public.journal_lines
      add constraint journal_lines_entry_id_fkey
        foreign key (entry_id)
        references public.journal_entries(id)
        on delete cascade;
  end if;
end $$;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.journal_lines'::regclass
      and contype = 'f'
      and conname = 'journal_lines_account_id_fkey'
  ) then
    alter table public.journal_lines
      add constraint journal_lines_account_id_fkey
        foreign key (account_id)
        references public.accounts(id);
  end if;
end $$;

do $$
begin
  if not exists (
    select 1 from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'stock_movements'
      and t.tgname = 'trg_stock_movements_updated_at'
  ) then
    create trigger trg_stock_movements_updated_at
      before update on stock_movements
      for each row execute procedure public.set_updated_at();
  end if;
end $$;

do $$
begin
  if not exists (
    select 1 from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'journal_entries'
      and t.tgname = 'trg_journal_entries_updated_at'
  ) then
    create trigger trg_journal_entries_updated_at
      before update on journal_entries
      for each row execute procedure public.set_updated_at();
  end if;
end $$;

do $$
begin
