alter table bikes drop constraint if exists bikes_bike_type_check;
alter table bikes add constraint bikes_bike_type_check check (
  bike_type in ('road','mountain','mountain_hardtail','hybrid','electric','bmx','folding','cruiser','gravel','paseo','other')
);
grant execute on function public.seed_job_subjects_for_tenant(uuid) to authenticated;

-- seed existing tenants
do $$
declare v_tenant record;
begin
  for v_tenant in select id from tenants loop
    perform public.seed_job_subjects_for_tenant(v_tenant.id);
  end loop;
end $$;

-- ============================================================
-- ALTER mechanic_jobs: job_type, subject_id, warranty_outcome,
-- quotation_status, converted_from_id, converted_at
-- ============================================================
-- Make bike_id nullable so item/quotation jobs need no registered bike
do $$ begin
  if exists (
    select 1 from information_schema.columns
    where table_name = 'mechanic_jobs' and column_name = 'bike_id'
      and is_nullable = 'NO'
  ) then
    alter table mechanic_jobs alter column bike_id drop not null;
    raise notice '✅ mechanic_jobs.bike_id is now nullable';
  end if;
end $$;

alter table mechanic_jobs
  add column if not exists job_type text not null default 'service';
do $$ begin
  alter table mechanic_jobs
    add constraint mechanic_jobs_job_type_check
    check (job_type in ('service', 'warranty', 'quotation', 'item_service'));
exception when duplicate_object then null; end $$;

alter table mechanic_jobs
  add column if not exists subject_id uuid references job_subjects(id) on delete set null;
alter table mechanic_jobs
  add column if not exists subject_notes text;
alter table mechanic_jobs
  add column if not exists warranty_outcome text;
do $$ begin
  alter table mechanic_jobs
    add constraint mechanic_jobs_warranty_outcome_check
    check (warranty_outcome in ('pending', 'covered', 'not_covered'));
exception when duplicate_object then null; end $$;

alter table mechanic_jobs
  add column if not exists quotation_status text;
do $$ begin
  alter table mechanic_jobs
    add constraint mechanic_jobs_quotation_status_check
    check (quotation_status in ('pending', 'approved', 'rejected', 'expired'));
exception when duplicate_object then null; end $$;

alter table mechanic_jobs
  add column if not exists quotation_valid_until timestamp with time zone;
alter table mechanic_jobs
  add column if not exists converted_from_id uuid references mechanic_jobs(id) on delete set null;
alter table mechanic_jobs
  add column if not exists converted_at timestamp with time zone;

-- Migrate existing warranty jobs
update mechanic_jobs
   set job_type = 'warranty',
       warranty_outcome = case
         when status in ('FINALIZADO', 'ENTREGADO') then 'covered'
         else 'pending'
       end
 where is_warranty_job = true
   and job_type = 'service';

-- new indexes
create index if not exists idx_mechanic_jobs_job_type on mechanic_jobs(tenant_id, job_type);
create index if not exists idx_mechanic_jobs_subject on mechanic_jobs(subject_id) where subject_id is not null;
create index if not exists idx_mechanic_jobs_converted on mechanic_jobs(converted_from_id) where converted_from_id is not null;

-- ============================================================
-- TABLE: mechanic_job_bikes (MULTI-BIKE SUPPORT)
-- ============================================================
-- Links bikes to jobs with per-bike details
-- Each bike in a job has its own: diagnosis, items, notes, costs, STATUS
create table if not exists mechanic_job_bikes (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  job_id uuid not null references mechanic_jobs(id) on delete cascade,
  bike_id uuid not null references bikes(id) on delete cascade,
  order_index integer not null default 0,

  -- Per-bike status (each bike can have independent status)
  status_id uuid references job_statuses(id) on delete set null,

  -- Per-bike work details
  diagnosis text,
  work_requested text,        -- Solicitud del cliente (per bike)
  work_performed text,        -- Lo que se hizo
  technician_notes text,      -- Notas del técnico
  diagnosis_sheet_key text,
  diagnosis_sheet_data jsonb not null default '{}'::jsonb,
  diagnosis_sheet_updated_at timestamp with time zone,

  -- Per-bike cost tracking (calculated from items)
  parts_cost numeric(12,2) not null default 0,
  labor_cost numeric(12,2) not null default 0,
  subtotal numeric(12,2) not null default 0,

  -- Per-bike flags
  is_warranty_work boolean not null default false,
  requires_approval boolean not null default false,
  approved_by_customer boolean not null default false,
  approved_at timestamp with time zone,

  -- Images for this specific bike work
  image_urls text[] not null default array[]::text[],

  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now()
);

-- Add status_id column if not exists (for existing tables)
alter table mechanic_job_bikes add column if not exists status_id uuid references job_statuses(id) on delete set null;
alter table mechanic_job_bikes add column if not exists diagnosis_sheet_key text;
alter table mechanic_job_bikes add column if not exists diagnosis_sheet_data jsonb not null default '{}'::jsonb;
alter table mechanic_job_bikes add column if not exists diagnosis_sheet_updated_at timestamp with time zone;

-- Indexes for mechanic_job_bikes
create index if not exists idx_mechanic_job_bikes_tenant on mechanic_job_bikes(tenant_id);
create index if not exists idx_mechanic_job_bikes_job on mechanic_job_bikes(job_id);
create index if not exists idx_mechanic_job_bikes_bike on mechanic_job_bikes(bike_id);
create index if not exists idx_mechanic_job_bikes_status on mechanic_job_bikes(status_id);

-- Unique constraint: each bike can only appear once per job
do $$ begin
  alter table mechanic_job_bikes drop constraint if exists mechanic_job_bikes_job_bike_unique;
  alter table mechanic_job_bikes add constraint mechanic_job_bikes_job_bike_unique unique (job_id, bike_id);
exception when others then null;
end $$;

-- Enable RLS for mechanic_job_bikes
alter table mechanic_job_bikes enable row level security;

drop policy if exists "mechanic_job_bikes_select" on mechanic_job_bikes;
drop policy if exists "mechanic_job_bikes_insert" on mechanic_job_bikes;
drop policy if exists "mechanic_job_bikes_update" on mechanic_job_bikes;
drop policy if exists "mechanic_job_bikes_delete" on mechanic_job_bikes;

