  metric_date date not null,
  sent_count integer default 0,
  opened_count integer default 0,
  clicked_count integer default 0,
  converted_count integer default 0,
  revenue_generated numeric(12,2) default 0,
  created_at timestamp with time zone not null default now()
);

do $$ begin
  create index if not exists idx_campaign_metrics_tenant on campaign_metrics(tenant_id);
  create index if not exists idx_campaign_metrics_campaign on campaign_metrics(campaign_id);
exception
  when undefined_table then raise notice '⚠ Table campaign_metrics does not exist';
  when undefined_column then raise notice '⚠ Column tenant_id does not exist in campaign_metrics';
end $$;

-- Companies (multi-company support within tenant)
create table if not exists companies (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references tenants(id) on delete cascade not null,
  name text not null,
  legal_name text,
  fantasy_name text,
  tax_id text,
  rut text,
  business_activity text,
  address text,
  comuna text,
  city text,
  region text,
  postal_code text,
  country text default 'Chile',
  phone text,
  whatsapp_phone text,
  whatsapp_api_phone text,
  support_phone text,
  email text,
  billing_email text,
  public_email text,
  website_url text,
  is_default boolean default false,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamp with time zone not null default now(),
  updated_at timestamp with time zone not null default now(),
  unique(tenant_id, tax_id)
);

alter table companies
  add column if not exists legal_name text,
  add column if not exists fantasy_name text,
  add column if not exists tax_id text,
  add column if not exists rut text,
  add column if not exists business_activity text,
  add column if not exists address text,
  add column if not exists comuna text,
  add column if not exists city text,
  add column if not exists region text,
  add column if not exists postal_code text,
  add column if not exists country text default 'Chile',
  add column if not exists phone text,
  add column if not exists whatsapp_phone text,
  add column if not exists whatsapp_api_phone text,
  add column if not exists support_phone text,
  add column if not exists email text,
  add column if not exists billing_email text,
  add column if not exists public_email text,
  add column if not exists website_url text,
  add column if not exists is_default boolean default false,
  add column if not exists updated_at timestamp with time zone not null default now(),
  add column if not exists metadata jsonb not null default '{}'::jsonb;

do $$ begin
  create index if not exists idx_companies_tenant on companies(tenant_id);
  create index if not exists idx_companies_default on companies(tenant_id, is_default);
  create index if not exists idx_companies_identity_search on companies using gin (
    to_tsvector(
      'spanish',
      coalesce(name, '') || ' ' ||
      coalesce(legal_name, '') || ' ' ||
      coalesce(fantasy_name, '') || ' ' ||
