-- ============================================================
-- DATA MIGRATION: RECALCULATE EXISTING PEGA COSTS
-- Run this once to fix trabajos that already have items but show $0
-- ============================================================

do $$
declare
  v_job record;
  v_parts_cost numeric;
  v_labor_cost numeric;
  v_updated_count integer := 0;
begin
  raise notice 'Starting trabajo cost recalculation...';

  for v_job in select id, job_number from mechanic_jobs loop
    -- Calculate parts cost (products only)
    select coalesce(sum(total_price), 0)
    into v_parts_cost
    from mechanic_job_items
    where job_id = v_job.id
      and coalesce(item_type, 'product') not in ('service', 'adhoc');

    -- Calculate labor cost (services + ad-hoc tasks)
    select coalesce(sum(total_price), 0)
    into v_labor_cost
    from mechanic_job_items
    where job_id = v_job.id
      and coalesce(item_type, 'product') in ('service', 'adhoc');

    -- Update job if costs changed
    update mechanic_jobs
    set
      parts_cost = v_parts_cost,
      labor_cost = v_labor_cost,
      total_cost = v_parts_cost + v_labor_cost,
      updated_at = now()
    where id = v_job.id
      and (parts_cost != v_parts_cost or labor_cost != v_labor_cost or total_cost != (v_parts_cost + v_labor_cost));

    if found then
      v_updated_count := v_updated_count + 1;
      raise notice 'Updated trabajo %: parts=$%, labor=$%, total=$%',
        v_job.job_number, v_parts_cost, v_labor_cost, v_parts_cost + v_labor_cost;
    end if;
  end loop;

  raise notice 'Trabajo cost recalculation complete! Updated % trabajos.', v_updated_count;
end $$;



--------------------------------------------------------------------------------
-- MESSAGING SYSTEM
--------------------------------------------------------------------------------
-- Unified messaging for internal ERP chats and customer support
-- Supports: Employee-to-employee chats, customer support tickets
-- RLS: Employees see internal + support, Customers see only their own support
--------------------------------------------------------------------------------

-- Conversations table
create table if not exists conversations (
  id uuid default gen_random_uuid() primary key,
  tenant_id uuid references public.tenants(id) default user_tenant_id(),
  type text not null check (type in ('internal', 'support')),
  channel text not null default 'website_portal' check (channel in ('internal', 'website_portal', 'whatsapp', 'instagram', 'facebook_messenger')),
  title text, -- Optional title for group chats or ticket subjects
  context_type text, -- 'job', 'invoice', etc.
  context_id uuid, -- ID of the related entity
  status text default 'active' check (status in ('pending', 'active', 'resolved', 'rejected')),
  created_by uuid references auth.users(id) default auth.uid(),
  accepted_by uuid references auth.users(id),
  accepted_at timestamptz,
  reject_reason text,
  last_message_at timestamptz default now(),
  staff_last_read_at timestamptz,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Add columns if they don't exist (for existing tables)
alter table conversations add column if not exists status text default 'active';
alter table conversations add column if not exists created_by uuid references auth.users(id) default auth.uid();
alter table conversations add column if not exists accepted_by uuid references auth.users(id);
alter table conversations add column if not exists accepted_at timestamptz;
alter table conversations add column if not exists reject_reason text;
alter table conversations add column if not exists channel text;
alter table conversations add column if not exists staff_last_read_at timestamptz;

update public.conversations c
set channel = case
  when c.type = 'internal' then 'internal'
  when c.channel in ('whatsapp', 'instagram', 'facebook_messenger')
    then c.channel
  else 'website_portal'
end
where c.channel is null
   or c.channel not in (
     'internal',
     'website_portal',
     'whatsapp',
     'instagram',
     'facebook_messenger'
   )
   or (c.type = 'internal' and c.channel <> 'internal')
   or (c.type = 'support' and c.channel = 'internal');

alter table conversations alter column channel set default 'website_portal';
alter table conversations alter column channel set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'conversations_channel_check'
      and conrelid = 'public.conversations'::regclass
  ) then
    alter table public.conversations
      add constraint conversations_channel_check
      check (channel in (
        'internal',
        'website_portal',
        'whatsapp',
        'instagram',
        'facebook_messenger'
      ));
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'conversations_type_channel_check'
      and conrelid = 'public.conversations'::regclass
  ) then
    alter table public.conversations
      add constraint conversations_type_channel_check
      check (
        (type = 'internal' and channel = 'internal')
        or (
          type = 'support'
          and channel in (
            'website_portal',
            'whatsapp',
            'instagram',
            'facebook_messenger'
          )
        )
      );
  end if;
end $$;

create or replace function public.normalize_conversation_channel()
returns trigger
language plpgsql
as $$
begin
  if NEW.type = 'internal' then
    NEW.channel := 'internal';
  elsif NEW.channel is null or NEW.channel = 'internal' then
    NEW.channel := 'website_portal';
  end if;

  return NEW;
end;
$$;

drop trigger if exists trg_normalize_conversation_channel on public.conversations;
create trigger trg_normalize_conversation_channel
  before insert or update of type, channel on public.conversations
  for each row execute procedure public.normalize_conversation_channel();

-- Conversation participants table
create table if not exists conversation_participants (
  conversation_id uuid references public.conversations(id) on delete cascade,
  user_id uuid references auth.users(id) on delete cascade,
  tenant_id uuid references public.tenants(id) default user_tenant_id(),
  role text default 'member' check (role in ('admin', 'member')),
  last_read_at timestamptz default now(),
  created_at timestamptz default now(),
  primary key (conversation_id, user_id)
);

update public.conversations c
set staff_last_read_at = latest.last_read_at
from (
  select
    cp.conversation_id,
    max(cp.last_read_at) as last_read_at
  from public.conversation_participants cp
  join public.conversations c2 on c2.id = cp.conversation_id
  where c2.type = 'support'
    and exists (
      select 1
      from public.user_profiles up
      where up.user_id = cp.user_id
    )
  group by cp.conversation_id
) latest
where c.id = latest.conversation_id
  and c.type = 'support'
  and (
    c.staff_last_read_at is null
    or c.staff_last_read_at < latest.last_read_at
  );

-- Messages table
create table if not exists messages (
  id uuid default gen_random_uuid() primary key,
  conversation_id uuid references public.conversations(id) on delete cascade,
  sender_id uuid references auth.users(id) on delete set null,
  tenant_id uuid references public.tenants(id) default user_tenant_id(),
  content text,
  type text default 'text' check (type in ('text', 'image', 'file', 'system', 'action_request')),
  metadata jsonb default '{}'::jsonb,
  message_direction text,
  created_at timestamptz default now()
);

-- Conversation contexts table (multi-context support)
create table if not exists conversation_contexts (
  id uuid default gen_random_uuid() primary key,
  conversation_id uuid references public.conversations(id) on delete cascade,
  context_type text not null check (context_type in ('job', 'invoice', 'bike', 'product', 'order', 'customer', 'supplier', 'purchase_invoice')),
  context_id uuid not null,
  is_primary boolean default false,
  added_by uuid references auth.users(id),
  added_at timestamptz default now(),
  tenant_id uuid references public.tenants(id) default user_tenant_id(),
  unique(conversation_id, context_type, context_id)
);

-- Indexes for performance
create index if not exists idx_conversations_tenant on public.conversations(tenant_id);
create index if not exists idx_conversations_status on public.conversations(status);
create index if not exists idx_conversations_channel_status on public.conversations(channel, status);
create index if not exists idx_conversations_type_status on public.conversations(type, status);
create index if not exists idx_participants_user on public.conversation_participants(user_id);
create index if not exists idx_messages_conversation on public.messages(conversation_id);
create index if not exists idx_messages_created_at on public.messages(created_at);
create index if not exists idx_conv_contexts_lookup on public.conversation_contexts(context_type, context_id);
create index if not exists idx_conv_contexts_conversation on public.conversation_contexts(conversation_id);

-- Helper function to check if user is a conversation participant
drop function if exists is_conversation_participant(uuid);

create or replace function is_conversation_participant(conv_id uuid)
returns boolean as $$
begin
  return exists (
    select 1 from public.conversation_participants
    where conversation_id = conv_id and user_id = auth.uid()
  );
end;
$$ language plpgsql stable security definer;

-- Update last_message_at trigger
create or replace function update_conversation_timestamp()
returns trigger as $$
declare
  v_sender_is_staff boolean := false;
  v_message_direction text := to_jsonb(new)->>'message_direction';
begin
  if new.sender_id is not null then
    select exists (
      select 1
      from public.user_profiles up
      where up.user_id = new.sender_id
    ) into v_sender_is_staff;
  end if;

  update public.conversations
  set last_message_at = new.created_at,
      updated_at = new.created_at,
      staff_last_read_at = case
        when type = 'support'
          and v_sender_is_staff
          and coalesce(new.type, 'text') <> 'system'
          and coalesce(v_message_direction, 'outbound') <> 'inbound'
        then greatest(
          coalesce(staff_last_read_at, '1970-01-01'::timestamptz),
          new.created_at
        )
        else staff_last_read_at
      end
  where id = new.conversation_id;
  return new;
end;
$$ language plpgsql;

drop trigger if exists trg_update_conversation_timestamp on messages;
create trigger trg_update_conversation_timestamp
after insert on public.messages
for each row execute function update_conversation_timestamp();

update public.conversations c
set staff_last_read_at = greatest(
  coalesce(c.staff_last_read_at, '1970-01-01'::timestamptz),
  handled.handled_at
)
from (
  select
    m.conversation_id,
    max(m.created_at) as handled_at
  from public.messages m
  join public.conversations c2 on c2.id = m.conversation_id
  where c2.type = 'support'
    and m.sender_id is not null
    and coalesce(m.type, 'text') <> 'system'
    and coalesce(to_jsonb(m)->>'message_direction', 'outbound') <> 'inbound'
    and exists (
      select 1
      from public.user_profiles up
      where up.user_id = m.sender_id
    )
  group by m.conversation_id
) handled
where c.id = handled.conversation_id
  and c.type = 'support'
  and (
    c.staff_last_read_at is null
    or c.staff_last_read_at < handled.handled_at
  );

-- Enable RLS
alter table public.conversations enable row level security;
alter table public.conversation_participants enable row level security;
alter table public.messages enable row level security;
alter table public.conversation_contexts enable row level security;

-- Drop existing policies to recreate them (NON-RECURSIVE VERSIONS)
drop policy if exists "Users can view conversations they participate in" on public.conversations;
drop policy if exists "Users can create conversations" on public.conversations;
drop policy if exists "Users can update their conversations" on public.conversations;
drop policy if exists "Users can view participants of their conversations" on public.conversation_participants;
drop policy if exists "Users can join conversations" on public.conversation_participants;
drop policy if exists "Users can add themselves as participants" on public.conversation_participants;
drop policy if exists "Users can view messages in their conversations" on public.messages;
drop policy if exists "Users can insert messages in their conversations" on public.messages;
drop policy if exists "Users can send messages" on public.messages;
drop policy if exists "Users can view contexts of their conversations" on public.conversation_contexts;
drop policy if exists "Participants can add contexts" on public.conversation_contexts;

-- ============================================================================
-- NON-RECURSIVE RLS POLICIES (Fixed Dec 24, 2024)
-- These policies use direct subqueries instead of is_conversation_participant()
-- to avoid infinite recursion when conversation_participants policy triggers itself
-- ============================================================================

-- CONVERSATIONS POLICIES
-- INSERT: Any authenticated user can create support conversations
create policy "Users can create conversations"
  on public.conversations for insert
  to authenticated
  with check (TRUE);  -- Simple: any authenticated user can create

-- SELECT: Creator, participants, or employees for support
create policy "Users can view conversations they participate in"
  on public.conversations for select
  to authenticated
  using (
    created_by = auth.uid()
    OR id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
    OR (type = 'support' AND EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid()))
  );

-- UPDATE: Creator, participants, or employees
create policy "Users can update their conversations"
  on public.conversations for update
  to authenticated
  using (
    created_by = auth.uid()
    OR id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

-- PARTICIPANTS POLICIES (CRITICAL: must not reference itself!)
-- SELECT: Your own participations, conversations you created, or employees see all
create policy "Users can view participants of their conversations"
  on public.conversation_participants for select
  to authenticated
  using (
    user_id = auth.uid()
    OR conversation_id IN (SELECT id FROM public.conversations WHERE created_by = auth.uid())
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

-- INSERT: Can add yourself, or employees can add anyone
create policy "Users can add themselves as participants"
  on public.conversation_participants for insert
  to authenticated
  with check (
    user_id = auth.uid()
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

-- MESSAGES POLICIES
-- SELECT: Conversations you created, participate in, or employees for support
create policy "Users can view messages in their conversations"
  on public.messages for select
  to authenticated
  using (
    conversation_id IN (SELECT id FROM public.conversations WHERE created_by = auth.uid())
    OR conversation_id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

-- INSERT: Must be sender and (creator, participant, or employee)
create policy "Users can send messages"
  on public.messages for insert
  to authenticated
  with check (
    sender_id = auth.uid()
    AND (
      conversation_id IN (SELECT id FROM public.conversations WHERE created_by = auth.uid())
      OR conversation_id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
    )
  );

-- CONVERSATION CONTEXTS POLICIES
create policy "Users can view contexts of their conversations"
  on public.conversation_contexts for select
  to authenticated
  using (
    conversation_id IN (SELECT id FROM public.conversations WHERE created_by = auth.uid())
    OR conversation_id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

create policy "Participants can add contexts"
  on public.conversation_contexts for insert
  to authenticated
  with check (
    conversation_id IN (SELECT id FROM public.conversations WHERE created_by = auth.uid())
    OR conversation_id IN (SELECT conversation_id FROM public.conversation_participants WHERE user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
  );

-- Grant permissions
grant select, insert, update on public.conversations to authenticated;
grant select, insert, update on public.conversation_participants to authenticated;
grant select, insert on public.messages to authenticated;
grant select, insert on public.conversation_contexts to authenticated;

-- Unread counts per participant.
-- Internal chats remain per participant. Support/WhatsApp chats use a shared
-- staff read marker so one teammate reading a customer thread clears the team
-- inbox badge for other staff users too.
create or replace view public.conversation_unread_counts as
with participant_scope as (
  select
    cp.conversation_id,
    cp.user_id,
    cp.last_read_at,
    c.type as conversation_type,
    c.staff_last_read_at,
    exists (
      select 1
      from public.user_profiles up
      where up.user_id = cp.user_id
    ) as participant_is_staff
  from public.conversation_participants cp
  join public.conversations c on c.id = cp.conversation_id
)
select
  ps.conversation_id,
  ps.user_id,
  coalesce(count(m.id), 0)::integer as unread_count
from participant_scope ps
left join public.messages m
  on m.conversation_id = ps.conversation_id
  and m.created_at > case
    when ps.conversation_type = 'support' and ps.participant_is_staff then
      greatest(
        coalesce(ps.last_read_at, '1970-01-01'::timestamptz),
        coalesce(ps.staff_last_read_at, '1970-01-01'::timestamptz)
      )
    else coalesce(ps.last_read_at, '1970-01-01'::timestamptz)
  end
  and coalesce(m.type, 'text') <> 'system'
  and case
    when ps.conversation_type = 'support' and ps.participant_is_staff then
      m.message_direction = 'inbound'
      or (
        m.message_direction is null
        and (
          m.sender_id is null
          or not exists (
            select 1
            from public.user_profiles sender_profile
            where sender_profile.user_id = m.sender_id
          )
        )
      )
    else m.sender_id is distinct from ps.user_id
  end
group by ps.conversation_id, ps.user_id;

grant select on public.conversation_unread_counts to authenticated;

-- Mark a conversation as read for the current participant.
create or replace function public.mark_conversation_read(
  p_conversation_id uuid
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_now timestamptz := now();
  v_conversation record;
  v_is_staff boolean := false;
begin
  if v_user_id is null then
    return;
  end if;

  select id, type, tenant_id, created_by
  into v_conversation
  from public.conversations
  where id = p_conversation_id;

  if not found then
    return;
  end if;

  select exists (
    select 1
    from public.user_profiles up
    where up.user_id = v_user_id
  ) into v_is_staff;

  if not (
    v_conversation.created_by = v_user_id
    or exists (
      select 1
      from public.conversation_participants cp
      where cp.conversation_id = p_conversation_id
        and cp.user_id = v_user_id
    )
    or (
      v_conversation.type = 'support'
      and v_is_staff
      and v_conversation.tenant_id = public.user_tenant_id()
    )
  ) then
    raise exception 'Not allowed to mark this conversation as read'
      using errcode = '42501';
  end if;

  update public.conversation_participants
  set last_read_at = v_now
  where conversation_id = p_conversation_id
    and user_id = v_user_id;

  if v_conversation.type = 'support' and v_is_staff then
    update public.conversations
    set staff_last_read_at = v_now
    where id = p_conversation_id;
  end if;
end;
$$;

do $$
begin
  if exists (
    select 1
    from pg_publication
    where pubname = 'supabase_realtime'
  ) then
    if not exists (
      select 1
      from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = 'messages'
    ) then
      alter publication supabase_realtime add table public.messages;
    end if;

    if not exists (
      select 1
      from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = 'conversations'
    ) then
      alter publication supabase_realtime add table public.conversations;
    end if;

    if not exists (
      select 1
      from pg_publication_tables
      where pubname = 'supabase_realtime'
        and schemaname = 'public'
        and tablename = 'conversation_participants'
    ) then
      alter publication supabase_realtime add table public.conversation_participants;
    end if;
  end if;
end $$;

-- Delete conversation RPC
-- Updated 2025-12-24: Fix permissions for support chats
CREATE OR REPLACE FUNCTION delete_conversation(p_conversation_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_participant BOOLEAN;
    v_is_employee BOOLEAN;
    v_user_role TEXT;
    v_chat_type TEXT;
BEGIN
    -- Get conversation details
    SELECT type INTO v_chat_type
    FROM conversations
    WHERE id = p_conversation_id;

    IF v_chat_type IS NULL THEN
        RETURN; -- Conversation does not exist
    END IF;

    -- Check if user is a participant using a more direct query
    IF EXISTS (
        SELECT 1 FROM conversation_participants
        WHERE conversation_id = p_conversation_id
        AND user_id = v_user_id
    ) THEN
        v_is_participant := true;
    ELSE
        v_is_participant := false;
    END IF;

    -- Check if user is an employee
    IF EXISTS (SELECT 1 FROM employees WHERE user_id = v_user_id) THEN
        v_is_employee := true;
    ELSE
        v_is_employee := false;
    END IF;

    -- AUTH LOGIC:
    -- 1. Participant can delete (Standard)
    -- 2. Employee can delete 'support' chats (Shared Inbox)

    -- Get user role
    SELECT role INTO v_user_role FROM user_profiles WHERE user_id = v_user_id;

    -- AUTH LOGIC:
    -- 1. Participant can delete (Standard)
    -- 2. Employee can delete 'support' chats (Shared Inbox)
    -- 3. Admins/Managers can delete any chat

    IF v_is_participant
       OR (v_is_employee AND v_chat_type = 'support')
       OR (v_user_role IN ('admin', 'manager', 'owner')) THEN
        -- Allowed
        NULL;
    ELSE
        RAISE EXCEPTION 'User is not authorized to delete this conversation (Code: P0001)';
    END IF;

    -- DELETE OPERATIONS

    -- 1. Messages (Foreign Key)
    DELETE FROM messages WHERE conversation_id = p_conversation_id;

    -- 2. Participants
    DELETE FROM conversation_participants WHERE conversation_id = p_conversation_id;

    -- 3. Conversation
    DELETE FROM conversations WHERE id = p_conversation_id;

END;
$$;

-- RPC to allow customers (or employees) to confirm an invoice
CREATE OR REPLACE FUNCTION public.confirm_invoice_approval(p_invoice_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_customer_id uuid;
BEGIN
  -- Get invoice customer
  SELECT customer_id INTO v_customer_id
  FROM public.sales_invoices
  WHERE id = p_invoice_id;

  -- Check permissions (must be the customer or an admin/employee)
  -- Employees are checked via user_profiles usually, but here we focus on Customer approval
  IF v_customer_id != auth.uid() THEN
     -- Check if employee
     IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid()) THEN
        RAISE EXCEPTION 'Not authorized to approve this invoice';
     END IF;
  END IF;

  -- Update status
  UPDATE public.sales_invoices
  SET status = 'confirmed'
  WHERE id = p_invoice_id;
END;
$$;
-- Enable RLS on sales_invoices if not already enabled (it should be)
ALTER TABLE public.sales_invoices ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Customers can view their own invoices"
ON public.sales_invoices;
DROP POLICY IF EXISTS "Employees can view all invoices"
ON public.sales_invoices;

-- 1. Sales Invoices: Customers can view their own invoices
CREATE POLICY "Customers can view their own invoices"
ON public.sales_invoices
FOR SELECT
TO authenticated
USING (
  customer_id = auth.uid()
);

-- 2. Sales Invoices: Employees can view all (assuming user_profiles check)
CREATE POLICY "Employees can view all invoices"
ON public.sales_invoices
FOR SELECT
TO authenticated
USING (
  EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
);

-- 3. Optional Sales Invoice Items policies
DO $$
BEGIN
  IF to_regclass('public.sales_invoice_items') IS NOT NULL THEN
    ALTER TABLE public.sales_invoice_items ENABLE ROW LEVEL SECURITY;

    DROP POLICY IF EXISTS "Customers can view their own invoice items"
    ON public.sales_invoice_items;
    DROP POLICY IF EXISTS "Employees can view all invoice items"
    ON public.sales_invoice_items;

    CREATE POLICY "Customers can view their own invoice items"
    ON public.sales_invoice_items
    FOR SELECT
    TO authenticated
    USING (
      EXISTS (
        SELECT 1 FROM public.sales_invoices i
        WHERE i.id = sales_invoice_items.invoice_id
        AND i.customer_id = auth.uid()
      )
    );

    CREATE POLICY "Employees can view all invoice items"
    ON public.sales_invoice_items
    FOR SELECT
    TO authenticated
    USING (
      EXISTS (SELECT 1 FROM public.user_profiles WHERE user_id = auth.uid())
    );
  END IF;
END $$;
-- Secure RPC to handle action request responses (bypassing RLS for specific updates)
create or replace function public.respond_to_action_request(
  p_message_id uuid,
  p_action_type text,
  p_status text,
  p_metadata_updates jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer -- Runs with elevated privileges
as $$
declare
  v_message_exists boolean;
  v_current_metadata jsonb;
  v_new_metadata jsonb;
begin
  -- 1. Verify existence
  select exists(select 1 from public.messages where id = p_message_id)
  into v_message_exists;

  if not v_message_exists then
    raise exception 'StartChat: Message not found';
  end if;

  -- 2. Get current metadata
  select metadata into v_current_metadata
  from public.messages
  where id = p_message_id;

  -- 3. Merge updates
  -- We update status, responded_at, and any other fields provided
  v_new_metadata := v_current_metadata ||
                    jsonb_build_object(
                      'status', p_status,
                      'responded_at', now()
                    ) || p_metadata_updates;

  -- 4. Update the message
  update public.messages
  set metadata = v_new_metadata
  where id = p_message_id;

end;
$$;
-- RPC to get basic public user info (name, avatar, role) for chat participants
-- This bypasses strict RLS and table structure differences
-- IMPORTANT: Checks employees FIRST, then user_profiles+employees, then customers, then auth.users
create or replace function public.get_public_user_info(p_user_id uuid)
returns jsonb
language plpgsql
security definer -- Runs with elevated privileges
as $$
declare
  v_result jsonb;
begin
  -- 1. Try to find in employees table directly (via user_id)
  select jsonb_build_object(
    'id', user_id,
    'name', coalesce(nullif(trim(first_name || ' ' || last_name), ''), 'Soporte'),
    'avatar_url', photo_url,
    'role', 'employee'
  )
  into v_result
  from public.employees
  where user_id = p_user_id
  limit 1;

  if v_result is not null then
    return v_result;
  end if;

  -- 2. Try user_profiles joined with employees (for when employee_id is linked)
  select jsonb_build_object(
    'id', up.user_id,
    'name', coalesce(nullif(trim(e.first_name || ' ' || e.last_name), ''), 'Soporte'),
    'avatar_url', e.photo_url,
    'role', 'employee'
  )
  into v_result
  from public.user_profiles up
  inner join public.employees e on e.id = up.employee_id
  where up.user_id = p_user_id
  limit 1;

  if v_result is not null then
    return v_result;
  end if;

  -- 3. If not an employee, try customers
  select jsonb_build_object(
    'id', auth_user_id,
    'name', coalesce(name, 'Cliente'),
    'avatar_url', image_url,
    'role', 'customer'
  )
  into v_result
  from public.customers
  where auth_user_id = p_user_id
  limit 1;

  if v_result is not null then
    return v_result;
  end if;

  -- 4. Fallback: try auth.users metadata
  select jsonb_build_object(
    'id', id,
    'name', coalesce(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1)),
    'avatar_url', raw_user_meta_data->>'avatar_url',
    'role', 'unknown'
  )
  into v_result
  from auth.users
  where id = p_user_id;

  return coalesce(v_result, jsonb_build_object('id', p_user_id, 'name', 'Soporte', 'avatar_url', null, 'role', 'employee'));
end;
$$;

-- ============================================================================
-- WHATSAPP CLOUD API INTEGRATION
-- Added: 2026-03-29
-- Purpose: Receive Meta webhooks, persist inbound/outbound message traceability,
--          bind WhatsApp contacts to support conversations, and automate job
--          lifecycle updates without bypassing the existing messaging system.
-- ============================================================================

create table if not exists whatsapp_channels (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references public.tenants(id) on delete cascade not null,
  phone_number_id text not null,
  business_account_id text,
  display_name text,
  display_phone_number text,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(phone_number_id),
  unique(tenant_id, phone_number_id)
);

create index if not exists idx_whatsapp_channels_tenant
  on public.whatsapp_channels(tenant_id);
create index if not exists idx_whatsapp_channels_active
  on public.whatsapp_channels(tenant_id, is_active);

alter table public.whatsapp_channels enable row level security;

drop policy if exists "whatsapp_channels_select" on public.whatsapp_channels;
drop policy if exists "whatsapp_channels_insert" on public.whatsapp_channels;
drop policy if exists "whatsapp_channels_update" on public.whatsapp_channels;
drop policy if exists "whatsapp_channels_delete" on public.whatsapp_channels;

create policy "whatsapp_channels_select" on public.whatsapp_channels
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_channels_insert" on public.whatsapp_channels
  for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "whatsapp_channels_update" on public.whatsapp_channels
  for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_channels_delete" on public.whatsapp_channels
  for delete to authenticated
  using (tenant_id = public.user_tenant_id());

drop trigger if exists trg_whatsapp_channels_updated_at on public.whatsapp_channels;
create trigger trg_whatsapp_channels_updated_at
  before update on public.whatsapp_channels
  for each row execute procedure public.set_updated_at();

create table if not exists whatsapp_conversation_bindings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references public.tenants(id) on delete cascade not null,
  conversation_id uuid references public.conversations(id) on delete cascade not null,
  channel_id uuid references public.whatsapp_channels(id) on delete cascade not null,
  customer_id uuid references public.customers(id) on delete set null,
  external_wa_id text not null,
  external_phone_number text,
  contact_name text,
  last_inbound_at timestamptz,
  last_outbound_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(channel_id, external_wa_id),
  unique(conversation_id, channel_id)
);

create index if not exists idx_whatsapp_bindings_tenant
  on public.whatsapp_conversation_bindings(tenant_id);
create index if not exists idx_whatsapp_bindings_conversation
  on public.whatsapp_conversation_bindings(conversation_id);
create index if not exists idx_whatsapp_bindings_customer
  on public.whatsapp_conversation_bindings(customer_id) where customer_id is not null;

alter table public.whatsapp_conversation_bindings enable row level security;

drop policy if exists "whatsapp_bindings_select" on public.whatsapp_conversation_bindings;
drop policy if exists "whatsapp_bindings_insert" on public.whatsapp_conversation_bindings;
drop policy if exists "whatsapp_bindings_update" on public.whatsapp_conversation_bindings;
drop policy if exists "whatsapp_bindings_delete" on public.whatsapp_conversation_bindings;

create policy "whatsapp_bindings_select" on public.whatsapp_conversation_bindings
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_bindings_insert" on public.whatsapp_conversation_bindings
  for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "whatsapp_bindings_update" on public.whatsapp_conversation_bindings
  for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_bindings_delete" on public.whatsapp_conversation_bindings
  for delete to authenticated
  using (tenant_id = public.user_tenant_id());

drop trigger if exists trg_whatsapp_bindings_updated_at on public.whatsapp_conversation_bindings;
create trigger trg_whatsapp_bindings_updated_at
  before update on public.whatsapp_conversation_bindings
  for each row execute procedure public.set_updated_at();

update public.conversations c
set channel = 'whatsapp'
where c.type = 'support'
  and exists (
    select 1
    from public.whatsapp_conversation_bindings w
    where w.conversation_id = c.id
  )
  and c.channel <> 'whatsapp';

create table if not exists whatsapp_webhook_events (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid references public.tenants(id) on delete cascade not null,
  channel_id uuid references public.whatsapp_channels(id) on delete cascade not null,
  event_key text not null,
  event_type text not null check (event_type in ('message', 'status', 'unknown')),
  direction text not null default 'system' check (direction in ('inbound', 'outbound', 'system')),
  payload jsonb not null default '{}'::jsonb,
  processed_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  unique(channel_id, event_key)
);

create index if not exists idx_whatsapp_webhook_events_tenant
  on public.whatsapp_webhook_events(tenant_id);
create index if not exists idx_whatsapp_webhook_events_channel
  on public.whatsapp_webhook_events(channel_id, created_at desc);
create index if not exists idx_whatsapp_webhook_events_type
  on public.whatsapp_webhook_events(event_type, created_at desc);

alter table public.whatsapp_webhook_events enable row level security;

drop policy if exists "whatsapp_webhook_events_select" on public.whatsapp_webhook_events;
drop policy if exists "whatsapp_webhook_events_insert" on public.whatsapp_webhook_events;
drop policy if exists "whatsapp_webhook_events_update" on public.whatsapp_webhook_events;
drop policy if exists "whatsapp_webhook_events_delete" on public.whatsapp_webhook_events;

create policy "whatsapp_webhook_events_select" on public.whatsapp_webhook_events
  for select to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_webhook_events_insert" on public.whatsapp_webhook_events
  for insert to authenticated
  with check (tenant_id = public.user_tenant_id());

create policy "whatsapp_webhook_events_update" on public.whatsapp_webhook_events
  for update to authenticated
  using (tenant_id = public.user_tenant_id());

create policy "whatsapp_webhook_events_delete" on public.whatsapp_webhook_events
  for delete to authenticated
  using (tenant_id = public.user_tenant_id());

alter table public.messages add column if not exists external_provider text;
alter table public.messages add column if not exists external_message_id text;
alter table public.messages add column if not exists message_direction text;
alter table public.messages add column if not exists external_status text;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'messages_external_provider_check'
  ) then
    alter table public.messages
      add constraint messages_external_provider_check
      check (
        external_provider in (
          'whatsapp',
          'instagram',
          'facebook_messenger'
        )
        or external_provider is null
      );
  end if;
exception
  when duplicate_object then null;
end $$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'messages_message_direction_check'
  ) then
    alter table public.messages
      add constraint messages_message_direction_check
      check (message_direction in ('inbound', 'outbound') or message_direction is null);
  end if;
exception
  when duplicate_object then null;
end $$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'messages_external_status_check'
  ) then
    alter table public.messages
      add constraint messages_external_status_check
      check (external_status in ('accepted', 'sent', 'delivered', 'read', 'failed') or external_status is null);
  end if;
exception
  when duplicate_object then null;
end $$;

create index if not exists idx_messages_external_provider
  on public.messages(external_provider) where external_provider is not null;
create unique index if not exists idx_messages_external_message_id
  on public.messages(external_message_id) where external_message_id is not null;

create or replace function public.normalize_whatsapp_phone(p_phone text)
returns text
language plpgsql
immutable
as $$
declare
  v_digits text;
begin
  if p_phone is null then
    return null;
  end if;

  v_digits := regexp_replace(p_phone, '[^0-9]', '', 'g');

  if v_digits = '' then
    return null;
  end if;

  if v_digits like '56%' then
    return v_digits;
  end if;

  if length(v_digits) = 9 and left(v_digits, 1) = '9' then
    return '56' || v_digits;
  end if;

  if length(v_digits) = 8 then
    return '569' || v_digits;
  end if;

  return v_digits;
end;
$$;

create or replace function public.ensure_whatsapp_conversation_binding(
  p_tenant_id uuid,
  p_channel_id uuid,
  p_wa_id text,
  p_phone_number text default null,
  p_contact_name text default null,
  p_customer_id uuid default null,
  p_context_type text default null,
  p_context_id uuid default null,
  p_conversation_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_binding record;
  v_conversation_id uuid;
  v_binding_id uuid;
  v_customer_auth_user_id uuid;
  v_context_type text;
  v_context_id uuid;
  v_title text;
begin
  if p_tenant_id is null or p_channel_id is null or p_wa_id is null then
    raise exception 'tenant, channel and wa_id are required';
  end if;

  select * into v_binding
  from public.whatsapp_conversation_bindings
  where channel_id = p_channel_id
    and external_wa_id = p_wa_id
  limit 1;

  if found then
    v_conversation_id := v_binding.conversation_id;
    v_binding_id := v_binding.id;
  else
    if p_conversation_id is not null then
      select id into v_conversation_id
      from public.conversations
      where id = p_conversation_id
        and tenant_id = p_tenant_id
      limit 1;
    end if;

    if v_conversation_id is null then
      v_title := coalesce(nullif(trim(p_contact_name), ''), nullif(trim(p_phone_number), ''), 'WhatsApp');

      insert into public.conversations (
        tenant_id,
        type,
        channel,
        title,
        status,
        last_message_at,
        updated_at
      ) values (
        p_tenant_id,
        'support',
        'whatsapp',
        v_title,
        'pending',
        now(),
        now()
      ) returning id into v_conversation_id;
    end if;

    insert into public.whatsapp_conversation_bindings (
      tenant_id,
      conversation_id,
      channel_id,
      customer_id,
      external_wa_id,
      external_phone_number,
      contact_name
    ) values (
      p_tenant_id,
      v_conversation_id,
      p_channel_id,
      p_customer_id,
      p_wa_id,
      public.normalize_whatsapp_phone(p_phone_number),
      p_contact_name
    ) returning id into v_binding_id;
  end if;

  update public.whatsapp_conversation_bindings
  set customer_id = coalesce(p_customer_id, customer_id),
      external_phone_number = coalesce(public.normalize_whatsapp_phone(p_phone_number), external_phone_number),
      contact_name = coalesce(nullif(trim(p_contact_name), ''), contact_name),
      updated_at = now()
  where id = v_binding_id;

  if p_customer_id is not null then
    select auth_user_id into v_customer_auth_user_id
    from public.customers
    where id = p_customer_id
      and tenant_id = p_tenant_id
    limit 1;

    if v_customer_auth_user_id is not null then
      insert into public.conversation_participants (
        conversation_id,
        user_id,
        tenant_id,
        role
      ) values (
        v_conversation_id,
        v_customer_auth_user_id,
        p_tenant_id,
        'member'
      ) on conflict (conversation_id, user_id) do nothing;
    end if;
  end if;

  v_context_type := p_context_type;
  v_context_id := p_context_id;

  if v_context_type is null and p_customer_id is not null then
    v_context_type := 'customer';
    v_context_id := p_customer_id;
  end if;

  if v_context_type is not null and v_context_id is not null then
    update public.conversation_contexts
    set is_primary = false
    where conversation_id = v_conversation_id
      and tenant_id = p_tenant_id;

    insert into public.conversation_contexts (
      conversation_id,
      context_type,
      context_id,
      is_primary,
      tenant_id
    ) values (
      v_conversation_id,
      v_context_type,
      v_context_id,
      true,
      p_tenant_id
    ) on conflict (conversation_id, context_type, context_id) do update
      set is_primary = true;
  end if;

  update public.conversations
  set title = case
        when nullif(trim(p_contact_name), '') is not null
          and (
            title is null
            or trim(title) = ''
            or public.normalize_whatsapp_phone(title) = p_wa_id
            or public.normalize_whatsapp_phone(title) = public.normalize_whatsapp_phone(p_phone_number)
          )
          then trim(p_contact_name)
        else coalesce(title, nullif(trim(p_contact_name), ''), nullif(trim(p_phone_number), ''), title)
      end,
      channel = 'whatsapp',
      context_type = coalesce(v_context_type, context_type),
      context_id = coalesce(v_context_id, context_id),
      updated_at = now()
  where id = v_conversation_id;

  return jsonb_build_object(
    'binding_id', v_binding_id,
    'conversation_id', v_conversation_id,
    'customer_id', p_customer_id,
    'channel_id', p_channel_id
  );
end;
$$;

create or replace function public.mark_whatsapp_job_quote_sent(
  p_job_id uuid,
  p_external_message_id text default null,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job record;
  v_status_id uuid;
begin
  select * into v_job
  from public.mechanic_jobs
  where id = p_job_id;

  if not found then
    raise exception 'Job not found: %', p_job_id;
  end if;

  select id into v_status_id
  from public.job_statuses
  where tenant_id = v_job.tenant_id
    and code = 'ESPERANDO_APROBACION'
    and is_active = true
  order by sort_order
  limit 1;

  update public.mechanic_jobs
  set status = coalesce(
        case
          when v_status_id is not null then 'ESPERANDO_APROBACION'
          else status
        end,
        status
      ),
      status_id = coalesce(v_status_id, status_id),
      diagnostic_sent_at = coalesce(diagnostic_sent_at, now()),
      requires_approval = true,
      updated_at = now()
  where id = p_job_id;

  perform public.log_mechanic_job_timeline(
    p_job_id,
    'whatsapp_quote_sent',
    null,
    p_external_message_id,
    'Quote sent to customer via WhatsApp'
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'status_code', case when v_status_id is not null then 'ESPERANDO_APROBACION' else v_job.status end,
    'diagnostic_sent_at', now(),
    'external_message_id', p_external_message_id,
    'payload', p_payload
  );
end;
$$;

create or replace function public.apply_whatsapp_job_action(
  p_job_id uuid,
  p_action text,
  p_external_message_id text default null,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_job record;
  v_status_code text;
  v_status_id uuid;
  v_description text;
begin
  select * into v_job
  from public.mechanic_jobs
  where id = p_job_id;

  if not found then
    raise exception 'Job not found: %', p_job_id;
  end if;

  case lower(p_action)
    when 'approve_quote', 'approve_budget', 'approve_estimate' then
      v_status_code := 'EN_CURSO';
      v_description := 'Customer approved the work via WhatsApp';
    when 'reject_quote', 'reject_budget', 'reject_estimate' then
      v_status_code := 'CANCELADO';
      v_description := 'Customer rejected the work via WhatsApp';
    when 'confirm_delivery' then
      v_status_code := 'ENTREGADO';
      v_description := 'Customer confirmed delivery via WhatsApp';
    when 'cancel_delivery' then
      v_status_code := 'FINALIZADO';
      v_description := 'Customer asked to keep the job open for delivery follow-up';
    else
      raise exception 'Unsupported WhatsApp job action: %', p_action;
  end case;

  select id into v_status_id
  from public.job_statuses
  where tenant_id = v_job.tenant_id
    and code = v_status_code
    and is_active = true
  order by sort_order
  limit 1;

  if v_status_id is null then
    raise exception 'Status % not found for tenant %', v_status_code, v_job.tenant_id;
  end if;

  update public.mechanic_jobs
  set status = v_status_code,
      status_id = v_status_id,
      approved_by_customer = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then true
        else approved_by_customer
      end,
      approved_at = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then coalesce(approved_at, now())
        else approved_at
      end,
      requires_approval = case
        when lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate', 'reject_quote', 'reject_budget', 'reject_estimate') then false
        else requires_approval
      end,
      quotation_status = case
        when job_type = 'quotation' and lower(p_action) in ('approve_quote', 'approve_budget', 'approve_estimate') then 'approved'
        when job_type = 'quotation' and lower(p_action) in ('reject_quote', 'reject_budget', 'reject_estimate') then 'rejected'
        else quotation_status
      end,
      updated_at = now()
  where id = p_job_id;

  perform public.log_mechanic_job_timeline(
    p_job_id,
    'whatsapp_action',
    null,
    lower(p_action),
    v_description
  );

  return jsonb_build_object(
    'job_id', p_job_id,
    'action', lower(p_action),
    'status_code', v_status_code,
    'status_id', v_status_id,
    'external_message_id', p_external_message_id,
    'payload', p_payload
  );
end;
$$;

create or replace function public.ingest_whatsapp_inbound_message(
  p_phone_number_id text,
  p_external_message_id text,
  p_wa_id text,
  p_phone_number text,
  p_contact_name text,
  p_message_type text,
  p_message_body text,
  p_payload jsonb default '{}'::jsonb,
  p_context_type text default null,
  p_context_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_channel record;
  v_customer record;
  v_binding jsonb;
  v_conversation_id uuid;
  v_message_id uuid;
  v_event_key text;
  v_row_count integer;
  v_ui_message_type text;
begin
  select * into v_channel
  from public.whatsapp_channels
  where phone_number_id = p_phone_number_id
    and is_active = true
  limit 1;

  if not found then
    raise exception 'WhatsApp channel not found for phone_number_id %', p_phone_number_id;
  end if;

  select id, auth_user_id, tenant_id
    into v_customer
  from public.customers
  where tenant_id = v_channel.tenant_id
    and public.normalize_whatsapp_phone(phone) = public.normalize_whatsapp_phone(p_phone_number)
  order by updated_at desc nulls last, created_at desc
  limit 1;

  v_event_key := 'message:' || p_external_message_id;

  insert into public.whatsapp_webhook_events (
    tenant_id,
    channel_id,
    event_key,
    event_type,
    direction,
    payload
  ) values (
    v_channel.tenant_id,
    v_channel.id,
    v_event_key,
    'message',
    'inbound',
    p_payload
  ) on conflict (channel_id, event_key) do nothing;

  get diagnostics v_row_count = row_count;

  if v_row_count = 0 then
    return jsonb_build_object(
      'duplicate', true,
      'event_key', v_event_key,
      'external_message_id', p_external_message_id
    );
  end if;

  if lower(coalesce(p_message_type, '')) = 'unsupported' then
    return jsonb_build_object(
      'duplicate', false,
      'ignored', true,
      'ignored_reason', 'unsupported_whatsapp_message_type',
      'event_key', v_event_key,
      'external_message_id', p_external_message_id,
      'tenant_id', v_channel.tenant_id,
      'channel_id', v_channel.id
    );
  end if;

  v_binding := public.ensure_whatsapp_conversation_binding(
    v_channel.tenant_id,
    v_channel.id,
    p_wa_id,
    p_phone_number,
    p_contact_name,
    v_customer.id,
    p_context_type,
    p_context_id,
    null
  );

  v_conversation_id := (v_binding->>'conversation_id')::uuid;

  v_ui_message_type := case lower(coalesce(p_message_type, 'text'))
    when 'image' then 'image'
    when 'document' then 'file'
    when 'audio' then 'file'
    when 'video' then 'file'
    when 'sticker' then 'image'
    when 'interactive' then 'text'
    else 'text'
  end;

  insert into public.messages (
    conversation_id,
    sender_id,
    tenant_id,
    content,
    type,
    metadata,
    external_provider,
    external_message_id,
    message_direction,
    created_at
  ) values (
    v_conversation_id,
    null,
    v_channel.tenant_id,
    coalesce(p_message_body, ''),
    v_ui_message_type,
    jsonb_strip_nulls(jsonb_build_object(
      'provider', 'whatsapp',
      'wa_id', p_wa_id,
      'phone_number', public.normalize_whatsapp_phone(p_phone_number),
      'contact_name', p_contact_name,
      'message_type', p_message_type,
      'raw_payload', p_payload
    )),
    'whatsapp',
    p_external_message_id,
    'inbound',
    now()
  ) returning id into v_message_id;

  update public.whatsapp_conversation_bindings
  set last_inbound_at = now(),
      updated_at = now()
  where id = (v_binding->>'binding_id')::uuid;

  update public.conversations
  set last_message_at = now(),
      updated_at = now(),
      status = case when status = 'pending' then 'active' else status end
  where id = v_conversation_id;

  return jsonb_build_object(
    'duplicate', false,
    'message_id', v_message_id,
    'conversation_id', v_conversation_id,
    'binding_id', (v_binding->>'binding_id')::uuid,
    'customer_id', v_customer.id,
    'tenant_id', v_channel.tenant_id
  );
end;
$$;

create or replace function public.replay_whatsapp_message_status(
  p_external_message_id text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_event record;
  v_message record;
begin
  select
    lower(coalesce(payload->>'status', split_part(event_key, ':', 3))) as status,
    payload
  into v_event
  from public.whatsapp_webhook_events
  where event_type = 'status'
    and left(event_key, length('status:' || p_external_message_id || ':')) =
      'status:' || p_external_message_id || ':'
  order by
    case lower(coalesce(payload->>'status', split_part(event_key, ':', 3)))
      when 'failed' then 50
      when 'read' then 40
      when 'delivered' then 30
      when 'sent' then 20
      else 10
    end desc,
    coalesce(nullif(payload->>'timestamp', '')::bigint, extract(epoch from created_at)::bigint) desc,
    created_at desc
  limit 1;

  if not found or v_event.status is null or v_event.status = '' then
    return jsonb_build_object(
      'applied', false,
      'reason', 'no_status_event',
      'external_message_id', p_external_message_id
    );
  end if;

  update public.messages
  set external_status = v_event.status,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'whatsapp_status', v_event.status,
        'whatsapp_status_payload', v_event.payload,
        'whatsapp_status_updated_at', now()
      )
  where external_provider = 'whatsapp'
    and external_message_id = p_external_message_id
  returning id, conversation_id into v_message;

  if v_message.id is null then
    return jsonb_build_object(
      'applied', false,
      'reason', 'message_not_found',
      'external_message_id', p_external_message_id,
      'status', v_event.status
    );
  end if;

  return jsonb_build_object(
    'applied', true,
    'message_id', v_message.id,
    'conversation_id', v_message.conversation_id,
    'external_message_id', p_external_message_id,
    'status', v_event.status
  );
end;
$$;

create or replace function public.record_whatsapp_message_status(
  p_phone_number_id text,
  p_external_message_id text,
  p_status text,
  p_payload jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_channel record;
  v_event_key text;
  v_row_count integer;
  v_job_id uuid;
  v_replay_result jsonb;
  v_message_id uuid;
  v_conversation_id uuid;
begin
  select * into v_channel
  from public.whatsapp_channels
  where phone_number_id = p_phone_number_id
    and is_active = true
  limit 1;

  if not found then
    raise exception 'WhatsApp channel not found for phone_number_id %', p_phone_number_id;
  end if;

  v_event_key := 'status:' || p_external_message_id || ':' || lower(coalesce(p_status, 'unknown')) || ':' || coalesce(p_payload->>'timestamp', '');

  insert into public.whatsapp_webhook_events (
    tenant_id,
    channel_id,
    event_key,
    event_type,
    direction,
    payload
  ) values (
    v_channel.tenant_id,
    v_channel.id,
    v_event_key,
    'status',
    'system',
    p_payload
  ) on conflict (channel_id, event_key) do nothing;

  get diagnostics v_row_count = row_count;

  v_replay_result := public.replay_whatsapp_message_status(p_external_message_id);
  v_message_id := nullif(v_replay_result->>'message_id', '')::uuid;
  v_conversation_id := nullif(v_replay_result->>'conversation_id', '')::uuid;

  if v_conversation_id is not null and lower(p_status) = 'read' then
    select cc.context_id into v_job_id
    from public.conversation_contexts cc
    where cc.conversation_id = v_conversation_id
      and cc.context_type = 'job'
    order by cc.is_primary desc, cc.added_at asc
    limit 1;

    if v_job_id is not null then
      perform public.log_mechanic_job_timeline(
        v_job_id,
        'whatsapp_read',
        null,
        p_external_message_id,
        'Customer read a WhatsApp message linked to this job'
      );
    end if;
  end if;

  return jsonb_build_object(
    'duplicate', v_row_count = 0,
    'event_key', v_event_key,
    'message_id', v_message_id,
    'conversation_id', v_conversation_id,
    'status', v_replay_result->>'status',
    'status_applied', coalesce((v_replay_result->>'applied')::boolean, false),
    'external_message_id', p_external_message_id
  );
end;
$$;

grant execute on function public.ensure_whatsapp_conversation_binding(uuid, uuid, text, text, text, uuid, text, uuid, uuid) to authenticated;
grant execute on function public.mark_whatsapp_job_quote_sent(uuid, text, jsonb) to authenticated;
grant execute on function public.mark_whatsapp_job_quote_sent(uuid, text, jsonb) to service_role;
grant execute on function public.apply_whatsapp_job_action(uuid, text, text, jsonb) to authenticated;
grant execute on function public.apply_whatsapp_job_action(uuid, text, text, jsonb) to service_role;
grant execute on function public.ingest_whatsapp_inbound_message(text, text, text, text, text, text, text, jsonb, text, uuid) to service_role;
grant execute on function public.replay_whatsapp_message_status(text) to service_role;
grant execute on function public.record_whatsapp_message_status(text, text, text, jsonb) to service_role;

-- ============================================================================
-- SPEC ENGINE: Technical Templates + Service Profiles
-- Added: 2026-03-18
-- See: supabase/migrations/20260318_spec_engine.sql for full deployment SQL
-- ============================================================================

-- spec_definitions: reusable field definitions (tenant_id NULL = system)
create table if not exists spec_definitions (
  id                       uuid        primary key default gen_random_uuid(),
  tenant_id                uuid        references tenants(id) on delete cascade,
  key                      text        not null,
  label                    text        not null,
  description              text,
  data_type                text        not null default 'text'
                             check (data_type in ('text','number','boolean','single_select','multi_select','range','json')),
  unit                     text,
  allowed_values           jsonb       not null default '[]',
  validation_rules         jsonb       not null default '{}',
  is_filterable            boolean     not null default false,
  is_required_by_default   boolean     not null default false,
  is_compatibility_relevant boolean    not null default false,
  is_customer_visible      boolean     not null default true,
  is_mechanic_visible      boolean     not null default true,
  group_name               text,
  sort_order               integer     not null default 0,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);
create unique index if not exists idx_spec_definitions_system_key on spec_definitions (key) where tenant_id is null;
create unique index if not exists idx_spec_definitions_tenant_key on spec_definitions (tenant_id, key) where tenant_id is not null;
create index if not exists idx_spec_definitions_tenant on spec_definitions (tenant_id);
alter table spec_definitions enable row level security;
drop policy if exists "spec_definitions_select" on spec_definitions;
drop policy if exists "spec_definitions_insert" on spec_definitions;
drop policy if exists "spec_definitions_update" on spec_definitions;
drop policy if exists "spec_definitions_delete" on spec_definitions;
create policy "spec_definitions_select" on spec_definitions for select to authenticated using (tenant_id is null or tenant_id = public.user_tenant_id());
create policy "spec_definitions_insert" on spec_definitions for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "spec_definitions_update" on spec_definitions for update to authenticated using (tenant_id = public.user_tenant_id());
create policy "spec_definitions_delete" on spec_definitions for delete to authenticated using (tenant_id = public.user_tenant_id());

-- spec_templates: ficha técnica schemas (tenant_id NULL = system)
create table if not exists spec_templates (
  id               uuid        primary key default gen_random_uuid(),
  tenant_id        uuid        references tenants(id) on delete cascade,
  key              text        not null,
  name             text        not null,
  technical_family text        not null,
  description      text,
  default_tags     jsonb       not null default '[]',
  is_active        boolean     not null default true,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create unique index if not exists idx_spec_templates_system_key on spec_templates (key) where tenant_id is null;
create unique index if not exists idx_spec_templates_tenant_key on spec_templates (tenant_id, key) where tenant_id is not null;
create index if not exists idx_spec_templates_tenant on spec_templates (tenant_id);
create index if not exists idx_spec_templates_family on spec_templates (technical_family) where tenant_id is null;
alter table spec_templates enable row level security;
drop policy if exists "spec_templates_select" on spec_templates;
drop policy if exists "spec_templates_insert" on spec_templates;
drop policy if exists "spec_templates_update" on spec_templates;
drop policy if exists "spec_templates_delete" on spec_templates;
create policy "spec_templates_select" on spec_templates for select to authenticated using (tenant_id is null or tenant_id = public.user_tenant_id());
create policy "spec_templates_insert" on spec_templates for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "spec_templates_update" on spec_templates for update to authenticated using (tenant_id = public.user_tenant_id());
create policy "spec_templates_delete" on spec_templates for delete to authenticated using (tenant_id = public.user_tenant_id());

-- spec_template_fields: links definitions to templates with ordering and visibility rules
create table if not exists spec_template_fields (
  id                  uuid        primary key default gen_random_uuid(),
  tenant_id           uuid        references tenants(id) on delete cascade,
  template_id         uuid        not null references spec_templates(id) on delete cascade,
  spec_definition_id  uuid        not null references spec_definitions(id) on delete cascade,
  is_required         boolean     not null default false,
  section_key         text        not null default 'general',
  sort_order          integer     not null default 0,
  default_value_json  jsonb,
  visibility_rules    jsonb       not null default '[]',
  helper_text         text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (template_id, spec_definition_id)
);
create index if not exists idx_spec_template_fields_template on spec_template_fields (template_id);
create index if not exists idx_spec_template_fields_definition on spec_template_fields (spec_definition_id);
alter table spec_template_fields enable row level security;
drop policy if exists "spec_template_fields_select" on spec_template_fields;
drop policy if exists "spec_template_fields_insert" on spec_template_fields;
drop policy if exists "spec_template_fields_update" on spec_template_fields;
drop policy if exists "spec_template_fields_delete" on spec_template_fields;
create policy "spec_template_fields_select" on spec_template_fields for select to authenticated using (tenant_id is null or tenant_id = public.user_tenant_id());
create policy "spec_template_fields_insert" on spec_template_fields for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "spec_template_fields_update" on spec_template_fields for update to authenticated using (tenant_id = public.user_tenant_id());
create policy "spec_template_fields_delete" on spec_template_fields for delete to authenticated using (tenant_id = public.user_tenant_id());

-- category_tech_mappings: maps business categories to technical families + templates
create table if not exists category_tech_mappings (
  id               uuid        primary key default gen_random_uuid(),
  tenant_id        uuid        not null references tenants(id) on delete cascade,
  category_id      uuid        not null references product_categories(id) on delete cascade,
  technical_family text        not null,
  template_id      uuid        references spec_templates(id) on delete set null,
  default_tags     jsonb       not null default '[]',
  status           text        not null default 'active' check (status in ('active','pending')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (tenant_id, category_id)
);
create index if not exists idx_category_tech_mappings_tenant on category_tech_mappings (tenant_id);
create index if not exists idx_category_tech_mappings_category on category_tech_mappings (category_id);
create index if not exists idx_category_tech_mappings_template on category_tech_mappings (template_id);
alter table category_tech_mappings enable row level security;
drop policy if exists "category_tech_mappings_select" on category_tech_mappings;
drop policy if exists "category_tech_mappings_insert" on category_tech_mappings;
drop policy if exists "category_tech_mappings_update" on category_tech_mappings;
drop policy if exists "category_tech_mappings_delete" on category_tech_mappings;
create policy "category_tech_mappings_select" on category_tech_mappings for select to authenticated using (tenant_id = public.user_tenant_id());
create policy "category_tech_mappings_insert" on category_tech_mappings for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "category_tech_mappings_update" on category_tech_mappings for update to authenticated using (tenant_id = public.user_tenant_id());
create policy "category_tech_mappings_delete" on category_tech_mappings for delete to authenticated using (tenant_id = public.user_tenant_id());

-- product_spec_values: actual technical values per product
create table if not exists product_spec_values (
  id                  uuid        primary key default gen_random_uuid(),
  tenant_id           uuid        not null references tenants(id) on delete cascade,
  product_id          uuid        not null references products(id) on delete cascade,
  spec_definition_id  uuid        not null references spec_definitions(id) on delete cascade,
  value_text          text,
  value_number        numeric,
  value_boolean       boolean,
  value_option        text,
  value_json          jsonb,
  display_value       text,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  unique (tenant_id, product_id, spec_definition_id)
);
create index if not exists idx_product_spec_values_tenant on product_spec_values (tenant_id);
create index if not exists idx_product_spec_values_product on product_spec_values (product_id);
create index if not exists idx_product_spec_values_product_def on product_spec_values (product_id, spec_definition_id);
create index if not exists idx_product_spec_values_filterable on product_spec_values (spec_definition_id, value_option) where value_option is not null;
alter table product_spec_values enable row level security;
drop policy if exists "product_spec_values_select" on product_spec_values;
