create or replace function public.get_public_product_technical_specs(
  p_tenant_id uuid,
  p_product_id uuid
)
returns table (
  section_key text,
  section_sort_order integer,
  field_sort_order integer,
  spec_key text,
  spec_label text,
  display_value text,
  unit text,
  data_type text
)
language sql
stable
security definer
set search_path = public
as $$
  with visible_product as (
    select p.id, p.category_id
    from public.products p
    where p.tenant_id = p_tenant_id
      and p.id = p_product_id
      and coalesce(p.is_active, true) = true
      and coalesce(p.is_published, false) = true
      and coalesce(p.show_on_website, false) = true
    limit 1
  ),
  template_match as (
    select ctm.template_id
    from visible_product p
    join public.category_tech_mappings ctm
      on ctm.category_id = p.category_id
     and ctm.tenant_id = p_tenant_id
    where ctm.template_id is not null
    order by ctm.created_at desc
    limit 1
  ),
  raw_field_values as (
    select
      stf.section_key,
      min(stf.sort_order) over (partition by stf.section_key)::integer as section_min_sort_order,
      stf.sort_order::integer as field_sort_order,
      sd.key as spec_key,
      sd.label as spec_label,
      sd.unit,
      sd.data_type,
      psv.display_value,
      psv.value_text,
      psv.value_number,
      psv.value_boolean,
      psv.value_option,
      psv.value_json
    from visible_product p
    join template_match tm on true
    join public.spec_template_fields stf
      on stf.template_id = tm.template_id
     and (stf.tenant_id is null or stf.tenant_id = p_tenant_id)
    join public.spec_definitions sd
      on sd.id = stf.spec_definition_id
     and (sd.tenant_id is null or sd.tenant_id = p_tenant_id)
    join public.product_spec_values psv
      on psv.product_id = p.id
     and psv.tenant_id = p_tenant_id
     and psv.spec_definition_id = sd.id
  ),
  field_values as (
    select
      r.*,
      dense_rank() over (order by r.section_min_sort_order, r.section_key)::integer as section_sort_order
    from raw_field_values r
  )
  select
    fv.section_key,
    fv.section_sort_order,
    fv.field_sort_order,
    fv.spec_key,
    fv.spec_label,
    nullif(
      coalesce(
        nullif(btrim(fv.display_value), ''),
        case
          when fv.data_type = 'boolean' then case when fv.value_boolean then 'Sí' else 'No' end
          when fv.data_type = 'number' then fv.value_number::text
          when fv.data_type = 'single_select' then fv.value_option
          when fv.data_type = 'multi_select' and jsonb_typeof(fv.value_json) = 'array' then (
            select string_agg(value, ', ' order by ordinality)
            from jsonb_array_elements_text(fv.value_json) with ordinality as option_value(value, ordinality)
          )
          when fv.value_json is not null then fv.value_json::text
          else fv.value_text
        end
      ),
      ''
    ) as display_value,
    fv.unit,
    fv.data_type
  from field_values fv
  where nullif(
    coalesce(
      nullif(btrim(fv.display_value), ''),
      fv.value_text,
      fv.value_option,
      fv.value_number::text,
      fv.value_boolean::text,
      fv.value_json::text
    ),
    ''
  ) is not null
  order by fv.section_sort_order, fv.field_sort_order, fv.spec_label;
$$;

grant execute on function public.get_public_product_technical_specs(uuid, uuid) to anon, authenticated;

create or replace function public.is_broad_drivetrain_ecosystem_claim(
  p_value text
)
returns boolean
language plpgsql
immutable
as $$
declare
  v_normalized text;
  v_has_brand_family boolean;
  v_has_exact_semantics boolean;
begin
  if p_value is null or btrim(p_value) = '' then
    return false;
  end if;

  v_normalized := lower(btrim(p_value));
  v_normalized := replace(v_normalized, 'á', 'a');
  v_normalized := replace(v_normalized, 'é', 'e');
  v_normalized := replace(v_normalized, 'í', 'i');
  v_normalized := replace(v_normalized, 'ó', 'o');
  v_normalized := replace(v_normalized, 'ú', 'u');
  v_normalized := regexp_replace(v_normalized, '[^a-z0-9]+', '', 'g');

  if v_normalized like '%ecosistema%' then
    return true;
  end if;

  if v_normalized like '%compatible%'
     and v_normalized not like '%genericocompatible%' then
    return true;
  end if;

  v_has_brand_family := v_normalized like '%shimano%'
    or v_normalized like '%sram%'
    or v_normalized like '%campagnolo%'
    or v_normalized like '%microshift%';

  if not v_has_brand_family then
    return false;
  end if;

  v_has_exact_semantics := v_normalized like '%hg%'
    or v_normalized like '%sis%'
    or v_normalized like '%dynasys%'
    or v_normalized like '%linkglide%'
    or v_normalized like '%cues%'
    or v_normalized like '%exactactuation%'
    or v_normalized like '%xactuation%'
    or v_normalized like '%eagle%'
    or v_normalized like '%axs%'
    or v_normalized like '%flattop%'
    or v_normalized like '%ttype%'
    or v_normalized like '%transmission%'
    or v_normalized like '%advent%'
    or v_normalized like '%acolyte%'
    or v_normalized like '%friccion%'
    or v_normalized like '%universal%'
    or v_normalized like '%single%'
    or v_normalized like '%bmx%'
    or v_normalized like '%ruta%';

  return not v_has_exact_semantics;
end;
$$;

create or replace function public.validate_product_spec_value_exact_drivetrain_fields()
returns trigger
language plpgsql
as $$
declare
  v_spec_key text;
  v_raw_value text;
begin
  select sd.key
    into v_spec_key
    from public.spec_definitions sd
   where sd.id = new.spec_definition_id;

  if v_spec_key not in ('drivetrain_platform', 'shift_actuation_family') then
    return new;
  end if;

  v_raw_value := btrim(coalesce(
    new.value_option,
    new.value_text,
    case
      when new.value_json is not null and jsonb_typeof(new.value_json) = 'string'
        then new.value_json #>> '{}'
      else null
    end,
    new.display_value,
    ''
  ));

  if v_raw_value = '' then
    return new;
  end if;

  if v_spec_key = 'drivetrain_platform' then
    if not (v_raw_value = any (array[
      'Shimano HG / SIS',
      'Shimano Hyperglide+',
      'Shimano Linkglide / CUES',
      'SRAM Eagle',
      'SRAM FlatTop / AXS road',
      'SRAM T-Type Transmission',
      'Campagnolo',
      'Microshift Advent / Acolyte',
      'Friccion / universal',
      'Single speed / BMX',
      'Generico compatible',
      'Desconocido / sin confirmar'
    ]))
       and public.is_broad_drivetrain_ecosystem_claim(v_raw_value) then
      raise exception
        'drivetrain_platform must store an exact platform label, not a broad ecosystem claim (%).',
        v_raw_value
        using errcode = '23514';
    end if;
  end if;

  if v_spec_key = 'shift_actuation_family' then
    if not (v_raw_value = any (array[
      'Shimano SIS 6-9v',
      'Shimano Dynasys 10v',
      'Shimano Dynasys 11/12v',
      'Shimano CUES / Linkglide',
      'Shimano ruta',
      'SRAM Exact Actuation',
      'SRAM X-Actuation / Eagle',
      'SRAM AXS road / FlatTop',
      'SRAM T-Type Transmission',
      'Campagnolo',
      'Microshift Advent / Acolyte',
      'Friccion / universal',
      'Otro',
      'Desconocido / sin confirmar'
    ]))
       and public.is_broad_drivetrain_ecosystem_claim(v_raw_value) then
      raise exception
        'shift_actuation_family must store an exact actuation/indexing label, not a broad ecosystem claim (%).',
        v_raw_value
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;

drop trigger if exists trg_validate_product_spec_value_exact_drivetrain_fields on public.product_spec_values;
create trigger trg_validate_product_spec_value_exact_drivetrain_fields
  before insert or update of spec_definition_id, value_text, value_option, value_json, display_value
  on public.product_spec_values
  for each row
  execute function public.validate_product_spec_value_exact_drivetrain_fields();

-- service_profiles: operational behavior for a billable service product
create table if not exists service_profiles (
  id                        uuid        primary key default gen_random_uuid(),
  tenant_id                 uuid        references tenants(id) on delete cascade,
  key                       text        not null,
  name                      text        not null,
  service_family            text        not null,
  description               text,
  customer_summary_template text,
  mechanic_summary_template text,
  is_active                 boolean     not null default true,
  created_at                timestamptz not null default now(),
  updated_at                timestamptz not null default now()
);
create unique index if not exists idx_service_profiles_system_key on service_profiles (key) where tenant_id is null;
create unique index if not exists idx_service_profiles_tenant_key on service_profiles (tenant_id, key) where tenant_id is not null;
create index if not exists idx_service_profiles_tenant on service_profiles (tenant_id);
create index if not exists idx_service_profiles_family on service_profiles (service_family) where tenant_id is null;
alter table service_profiles enable row level security;
drop policy if exists "service_profiles_select" on service_profiles;
drop policy if exists "service_profiles_insert" on service_profiles;
drop policy if exists "service_profiles_update" on service_profiles;
drop policy if exists "service_profiles_delete" on service_profiles;
create policy "service_profiles_select" on service_profiles for select to authenticated using (tenant_id is null or tenant_id = public.user_tenant_id());
create policy "service_profiles_insert" on service_profiles for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "service_profiles_update" on service_profiles for update to authenticated using (tenant_id = public.user_tenant_id());
create policy "service_profiles_delete" on service_profiles for delete to authenticated using (tenant_id = public.user_tenant_id());

-- service_product_profile_mappings: links service products to their profiles
create table if not exists service_product_profile_mappings (
  id                 uuid        primary key default gen_random_uuid(),
  tenant_id          uuid        not null references tenants(id) on delete cascade,
  product_id         uuid        not null references products(id) on delete cascade,
  service_profile_id uuid        not null references service_profiles(id) on delete cascade,
  status             text        not null default 'active' check (status in ('active','pending')),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  unique (tenant_id, product_id)
);
create index if not exists idx_svc_product_map_tenant on service_product_profile_mappings (tenant_id);
create index if not exists idx_svc_product_map_product on service_product_profile_mappings (product_id);
create index if not exists idx_svc_product_map_profile on service_product_profile_mappings (service_profile_id);
alter table service_product_profile_mappings enable row level security;
drop policy if exists "svc_product_map_select" on service_product_profile_mappings;
drop policy if exists "svc_product_map_insert" on service_product_profile_mappings;
drop policy if exists "svc_product_map_update" on service_product_profile_mappings;
drop policy if exists "svc_product_map_delete" on service_product_profile_mappings;
create policy "svc_product_map_select" on service_product_profile_mappings for select to authenticated using (tenant_id = public.user_tenant_id());
create policy "svc_product_map_insert" on service_product_profile_mappings for insert to authenticated with check (tenant_id = public.user_tenant_id());
create policy "svc_product_map_update" on service_product_profile_mappings for update to authenticated using (tenant_id = public.user_tenant_id());
