create or replace function public.validate_shift_planning_tenant_consistency()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if TG_TABLE_NAME = 'employee_default_shift_blocks' then
    if NEW.planning_role_id is not null and not exists (
      select 1 from public.planning_roles pr
      where pr.id = NEW.planning_role_id
        and pr.tenant_id = NEW.tenant_id
    ) then
      raise exception 'Planning role does not belong to this tenant';
    end if;
  elsif TG_TABLE_NAME = 'planned_shifts' then
    if NEW.employee_id is not null and not exists (
      select 1 from public.employees e
      where e.id = NEW.employee_id
        and e.tenant_id = NEW.tenant_id
    ) then
      raise exception 'Worker does not belong to this tenant';
    end if;

    if NEW.planning_role_id is not null and not exists (
      select 1 from public.planning_roles pr
      where pr.id = NEW.planning_role_id
        and pr.tenant_id = NEW.tenant_id
    ) then
      raise exception 'Planning role does not belong to this tenant';
    end if;
  elsif TG_TABLE_NAME = 'shift_change_requests' then
    if NEW.requested_role_id is not null and not exists (
      select 1 from public.planning_roles pr
      where pr.id = NEW.requested_role_id
        and pr.tenant_id = NEW.tenant_id
    ) then
      raise exception 'Requested planning role does not belong to this tenant';
    end if;

    if NEW.planned_shift_id is not null and not exists (
      select 1 from public.planned_shifts ps
      where ps.id = NEW.planned_shift_id
        and ps.tenant_id = NEW.tenant_id
    ) then
      raise exception 'Planned shift does not belong to this tenant';
    end if;
  end if;

  return NEW;
end;
$$;

drop trigger if exists trg_employee_default_shift_blocks_tenant_consistency
  on public.employee_default_shift_blocks cascade;
create trigger trg_employee_default_shift_blocks_tenant_consistency
  before insert or update on public.employee_default_shift_blocks
  for each row execute procedure public.validate_shift_planning_tenant_consistency();

drop trigger if exists trg_planned_shifts_tenant_consistency on public.planned_shifts cascade;
create trigger trg_planned_shifts_tenant_consistency
  before insert or update on public.planned_shifts
  for each row execute procedure public.validate_shift_planning_tenant_consistency();

drop trigger if exists trg_shift_change_requests_tenant_consistency
  on public.shift_change_requests cascade;
create trigger trg_shift_change_requests_tenant_consistency
  before insert or update on public.shift_change_requests
  for each row execute procedure public.validate_shift_planning_tenant_consistency();

create or replace view public.shift_attendance_variances
with (security_invoker = true)
as
select
  ps.id as planned_shift_id,
  ps.tenant_id,
  ps.employee_id,
  ps.planning_role_id,
  ps.start_at,
  ps.end_at,
  ps.status as shift_status,
  round(extract(epoch from (ps.end_at - ps.start_at)) / 60.0, 2) as planned_minutes,
  att.first_check_in,
  att.last_check_out,
  att.actual_minutes,
  case
    when att.first_check_in is null then null
    else round(extract(epoch from (att.first_check_in - ps.start_at)) / 60.0, 2)
  end as start_delta_minutes,
  case
    when att.last_check_out is null then null
    else round(extract(epoch from (att.last_check_out - ps.end_at)) / 60.0, 2)
  end as end_delta_minutes,
  case
    when att.actual_minutes is null then null
    else round(att.actual_minutes - (extract(epoch from (ps.end_at - ps.start_at)) / 60.0), 2)
  end as variance_minutes
from public.planned_shifts ps
left join lateral (
  select
    min(a.check_in) as first_check_in,
    max(a.check_out) as last_check_out,
    round(sum(extract(epoch from (coalesce(a.check_out, now()) - a.check_in)) / 60.0), 2) as actual_minutes
  from public.attendances a
  where a.tenant_id = ps.tenant_id
    and a.employee_id = ps.employee_id
    and a.check_in >= ps.start_at - interval '12 hours'
    and a.check_in <= ps.end_at + interval '12 hours'
    and a.status in ('ongoing', 'completed', 'approved')
) att on true;

create or replace function public.resolve_worker_login(
  p_tenant text,
  p_username text
)
returns table (login_email text)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_tenant_key text := lower(trim(coalesce(p_tenant, '')));
  v_username text := public.normalize_worker_username(p_username);
  v_tenant_uuid uuid;
begin
  begin
    v_tenant_uuid := v_tenant_key::uuid;
  exception
    when invalid_text_representation then
      v_tenant_uuid := null;
  end;

  return query
  select epa.login_email
  from public.employee_portal_accounts epa
  join public.tenants t on t.id = epa.tenant_id
  join public.employees e on e.id = epa.employee_id
  where epa.username = v_username
    and epa.is_active = true
    and e.status = 'active'
    and t.is_active = true
    and (
      t.id = v_tenant_uuid
      or lower(coalesce(t.subdomain, '')) = v_tenant_key
      or lower(coalesce(t.custom_domain, '')) = v_tenant_key
      or lower(replace(coalesce(t.shop_name, ''), ' ', '')) = replace(v_tenant_key, ' ', '')
    )
  limit 1;
end;
$$;

grant execute on function public.resolve_worker_login(text, text) to anon, authenticated;

create or replace function public.get_my_worker_portal_context()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_context jsonb;
begin
  select jsonb_build_object(
    'account', jsonb_build_object(
      'id', epa.id,
      'username', epa.username,
      'mustResetPassword', epa.must_reset_password,
      'isActive', epa.is_active,
      'createdAt', epa.created_at,
      'lastLoginAt', epa.last_login_at
    ),
    'tenant', jsonb_build_object(
      'id', t.id,
      'shopName', t.shop_name,
      'subdomain', t.subdomain,
      'timezone', t.timezone
    ),
    'storeSchedule', (
      select jsonb_build_object(
        'source', coalesce(max(ws.value) filter (where ws.key = 'business_hours_source'), 'erp_settings'),
        'businessHoursJson', coalesce(max(ws.value) filter (where ws.key = 'business_hours_json'), ''),
        'googleBusinessHoursJson', coalesce(max(ws.value) filter (where ws.key = 'google_business_regular_hours'), ''),
        'updatedAt', max(ws.value) filter (where ws.key = 'business_hours_updated_at')
      )
      from public.website_settings ws
      where ws.tenant_id = epa.tenant_id
        and ws.key in (
          'business_hours_source',
          'business_hours_json',
          'google_business_regular_hours',
          'business_hours_updated_at'
        )
    ),
    'employee', jsonb_build_object(
      'id', e.id,
      'employeeNumber', e.employee_number,
      'firstName', e.first_name,
      'lastName', e.last_name,
      'fullName', trim(e.first_name || ' ' || e.last_name),
      'jobTitle', e.job_title,
      'departmentName', d.name,
      'employmentType', e.employment_type,
      'systemRole', e.system_role,
      'photoUrl', e.photo_url,
      'email', e.email,
      'phone', e.phone,
      'rut', e.rut,
      'birthDate', e.birth_date,
      'hireDate', e.hire_date,
      'address', e.address,
      'city', e.city,
      'emergencyContactName', e.emergency_contact_name,
      'emergencyContactPhone', e.emergency_contact_phone,
      'status', e.status
    ),
    'payroll', jsonb_build_object(
      'hourlyRate', coalesce(e.hourly_rate, 0),
      'preferredPaymentMethod', e.preferred_payment_method,
      'preferredPaymentMethodId', e.preferred_payment_method_id,
      'preferredPaymentMethodName', pm.name
    ),
    'planningRoles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pr.id,
        'code', pr.code,
        'name', pr.name,
        'color', pr.color,
        'isDefault', epr.is_default
      ) order by epr.is_default desc, pr.sort_order, pr.name)
      from public.employee_planning_roles epr
      join public.planning_roles pr on pr.id = epr.planning_role_id
      where epr.tenant_id = epa.tenant_id
        and epr.employee_id = epa.employee_id
        and pr.is_active = true
    ), '[]'::jsonb),
    'defaultShiftBlocks', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', dsb.id,
        'dayOfWeek', dsb.day_of_week,
        'startTime', dsb.start_time,
        'endTime', dsb.end_time,
        'timezone', dsb.timezone,
        'planningRoleId', dsb.planning_role_id,
        'planningRoleName', pr.name,
        'planningRoleColor', pr.color,
        'source', dsb.source,
        'storeHoursValidated', dsb.store_hours_validated,
        'outsideStoreHoursReason', dsb.outside_store_hours_reason
      ) order by dsb.day_of_week, dsb.start_time)
      from public.employee_default_shift_blocks dsb
      left join public.planning_roles pr on pr.id = dsb.planning_role_id
      where dsb.tenant_id = epa.tenant_id
        and dsb.employee_id = epa.employee_id
        and dsb.is_active = true
    ), '[]'::jsonb)
  )
  into v_context
  from public.employee_portal_accounts epa
  join public.employees e on e.id = epa.employee_id
  join public.tenants t on t.id = epa.tenant_id
  left join public.departments d on d.id = e.department_id
  left join public.payment_methods pm
    on pm.id = e.preferred_payment_method_id
   and pm.tenant_id = e.tenant_id
  where epa.auth_user_id = auth.uid()
    and epa.is_active = true
    and e.status = 'active'
    and t.is_active = true
  limit 1;

  return v_context;
end;
$$;

grant execute on function public.get_my_worker_portal_context() to authenticated;

create or replace function public.get_my_worker_shifts(
  p_start_at timestamp with time zone,
  p_end_at timestamp with time zone
)
returns table (
  id uuid,
  title text,
  start_at timestamp with time zone,
  end_at timestamp with time zone,
  timezone text,
  status text,
  source text,
  planning_role_id uuid,
  planning_role_name text,
  store_hours_validated boolean,
  outside_store_hours_reason text,
  first_check_in timestamp with time zone,
  last_check_out timestamp with time zone,
  planned_minutes numeric,
  actual_minutes numeric,
  variance_minutes numeric
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  return query
  select
    ps.id,
    ps.title,
    ps.start_at,
    ps.end_at,
    ps.timezone,
    ps.status,
    ps.source,
    ps.planning_role_id,
    pr.name as planning_role_name,
    ps.store_hours_validated,
    ps.outside_store_hours_reason,
    sav.first_check_in,
    sav.last_check_out,
    sav.planned_minutes,
    sav.actual_minutes,
    sav.variance_minutes
  from public.planned_shifts ps
  left join public.planning_roles pr on pr.id = ps.planning_role_id
  left join public.shift_attendance_variances sav on sav.planned_shift_id = ps.id
  where ps.tenant_id = v_tenant_id
    and ps.employee_id = v_employee_id
    and ps.status in ('draft', 'published', 'completed')
    and ps.start_at < p_end_at
    and ps.end_at > p_start_at
  order by ps.start_at;
end;
$$;

grant execute on function public.get_my_worker_shifts(timestamp with time zone, timestamp with time zone)
  to authenticated;

create or replace function public.get_worker_portal_planning_calendar(
  p_start_at timestamp with time zone,
  p_end_at timestamp with time zone
)
returns table (
  id uuid,
  employee_id uuid,
  employee_full_name text,
  employee_job_title text,
  employee_photo_url text,
  title text,
  start_at timestamp with time zone,
  end_at timestamp with time zone,
  timezone text,
  status text,
  source text,
  planning_role_id uuid,
  planning_role_name text,
  planning_role_color text,
  store_hours_validated boolean,
  outside_store_hours_reason text,
  is_my_shift boolean
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  return query
  select
    ps.id,
    ps.employee_id,
    trim(concat_ws(' ', e.first_name, e.last_name)) as employee_full_name,
    e.job_title as employee_job_title,
    e.photo_url as employee_photo_url,
    ps.title,
    ps.start_at,
    ps.end_at,
    ps.timezone,
    ps.status,
    ps.source,
    ps.planning_role_id,
    pr.name as planning_role_name,
    pr.color as planning_role_color,
    ps.store_hours_validated,
    ps.outside_store_hours_reason,
    ps.employee_id = v_employee_id as is_my_shift
  from public.planned_shifts ps
  left join public.employees e on e.id = ps.employee_id
  left join public.planning_roles pr on pr.id = ps.planning_role_id
  where ps.tenant_id = v_tenant_id
    and ps.status <> 'cancelled'
    and ps.start_at < p_end_at
    and ps.end_at > p_start_at
    and (
      ps.employee_id = v_employee_id
      or ps.status in ('published', 'completed')
    )
  order by ps.start_at, trim(concat_ws(' ', e.first_name, e.last_name));
end;
$$;

grant execute on function public.get_worker_portal_planning_calendar(
  timestamp with time zone,
  timestamp with time zone
) to authenticated;

create or replace function public.update_my_worker_shift(
  p_shift_id uuid,
  p_start_at timestamp with time zone,
  p_end_at timestamp with time zone
)
returns uuid
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
  v_shift_id uuid;
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  if p_end_at <= p_start_at then
    raise exception 'Shift end must be after start';
  end if;

  update public.planned_shifts ps
     set start_at = p_start_at,
         end_at = p_end_at,
         timezone = coalesce(nullif(ps.timezone, ''), 'America/Santiago'),
         updated_by = auth.uid(),
         store_hours_validated = true,
         outside_store_hours_reason = null,
         updated_at = now()
   where ps.id = p_shift_id
     and ps.tenant_id = v_tenant_id
     and ps.employee_id = v_employee_id
     and ps.status in ('draft', 'published')
   returning ps.id into v_shift_id;

  if v_shift_id is null then
    raise exception 'Shift not found or not editable';
  end if;

  return v_shift_id;
end;
$$;

grant execute on function public.update_my_worker_shift(
  uuid,
  timestamp with time zone,
  timestamp with time zone
) to authenticated;


create or replace function public.get_my_worker_attendances(
  p_start_at timestamp with time zone,
  p_end_at timestamp with time zone
)
returns table (
  id uuid,
  employee_id uuid,
  check_in timestamp with time zone,
  check_out timestamp with time zone,
  worked_hours numeric,
  overtime_hours numeric,
  break_minutes integer,
  status text,
  notes text
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  if p_start_at is null or p_end_at is null or p_start_at >= p_end_at then
    raise exception 'Invalid attendance period';
  end if;

  return query
  select
    a.id,
    a.employee_id,
    a.check_in,
    a.check_out,
    a.worked_hours,
    a.overtime_hours,
    a.break_minutes,
    a.status::text,
    a.notes
  from public.attendances a
  where a.tenant_id = v_tenant_id
    and a.employee_id = v_employee_id
    and a.check_in < p_end_at
    and coalesce(a.check_out, now()) >= p_start_at
  order by a.check_in;
end;
$$;

grant execute on function public.get_my_worker_attendances(
  timestamp with time zone,
  timestamp with time zone
) to authenticated;

create or replace function public.get_my_worker_payroll_for_period(
  p_start_date date,
  p_end_date date
)
returns table (
  voucher_id uuid,
  voucher_number text,
  period_start date,
  period_end date,
  period_label text,
  status text,
  paid_at timestamp with time zone,
  line_id uuid,
  worked_hours numeric,
  overtime_hours numeric,
  hourly_rate numeric,
  overtime_rate numeric,
  regular_amount numeric,
  overtime_amount numeric,
  total_amount numeric,
  payment_method text,
  payment_method_name text
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  if p_start_date is null or p_end_date is null or p_start_date > p_end_date then
    raise exception 'Invalid payroll period';
  end if;

  return query
  select
    pv.id as voucher_id,
    pv.voucher_number,
    pv.period_start,
    pv.period_end,
    pv.period_label,
    pv.status::text,
    pv.paid_at,
    pvl.id as line_id,
    pvl.worked_hours,
    pvl.overtime_hours,
    pvl.hourly_rate,
    pvl.overtime_rate,
    pvl.regular_amount,
    pvl.overtime_amount,
    pvl.total_amount,
    pvl.payment_method,
    pm.name as payment_method_name
  from public.payroll_voucher_lines pvl
  join public.payroll_vouchers pv
    on pv.id = pvl.voucher_id
   and pv.tenant_id = pvl.tenant_id
  left join public.payment_methods pm
    on pm.id = pvl.payment_method_id
   and pm.tenant_id = pvl.tenant_id
  where pvl.tenant_id = v_tenant_id
    and pvl.employee_id = v_employee_id
    and pvl.is_included = true
    and pv.period_start <= p_end_date
    and pv.period_end >= p_start_date
    and pv.status <> 'voided'
  order by pv.period_end desc, pv.created_at desc;
end;
$$;

grant execute on function public.get_my_worker_payroll_for_period(date, date)
  to authenticated;

create or replace function public.request_my_shift_change(
  p_request_type text,
  p_planned_shift_id uuid default null,
  p_requested_start_at timestamp with time zone default null,
  p_requested_end_at timestamp with time zone default null,
  p_requested_role_id uuid default null,
  p_worker_note text default null,
  p_request_payload jsonb default '{}'::jsonb
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
  v_request_id uuid;
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  if p_request_type not in ('create', 'update', 'delete', 'availability') then
    raise exception 'Unsupported shift request type: %', p_request_type;
  end if;

  if p_requested_start_at is not null
     and p_requested_end_at is not null
     and p_requested_start_at >= p_requested_end_at then
    raise exception 'Requested shift start must be before end';
  end if;

  if p_planned_shift_id is not null and not exists (
    select 1
    from public.planned_shifts ps
    where ps.id = p_planned_shift_id
      and ps.tenant_id = v_tenant_id
      and ps.employee_id = v_employee_id
  ) then
    raise exception 'Shift not found for current worker';
  end if;

  if p_requested_role_id is not null and not exists (
    select 1
    from public.planning_roles pr
    where pr.id = p_requested_role_id
      and pr.tenant_id = v_tenant_id
      and pr.is_active = true
  ) then
    raise exception 'Planning role not found';
  end if;

  insert into public.shift_change_requests (
    tenant_id,
    employee_id,
    planned_shift_id,
    request_type,
    requested_start_at,
    requested_end_at,
    requested_role_id,
    worker_note,
    request_payload
  )
  values (
    v_tenant_id,
    v_employee_id,
    p_planned_shift_id,
    p_request_type,
    p_requested_start_at,
    p_requested_end_at,
    p_requested_role_id,
    p_worker_note,
    coalesce(p_request_payload, '{}'::jsonb)
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;

grant execute on function public.request_my_shift_change(
  text,
  uuid,
  timestamp with time zone,
  timestamp with time zone,
  uuid,
  text,
  jsonb
) to authenticated;

create or replace function public.set_my_default_shift_blocks(
  p_blocks jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_employee_id uuid := public.worker_portal_employee_id();
  v_tenant_id uuid := public.worker_portal_tenant_id();
  v_count integer := 0;
begin
  if v_employee_id is null or v_tenant_id is null then
    raise exception 'Worker portal account not found';
  end if;

  if p_blocks is null then
    p_blocks := '[]'::jsonb;
  end if;

  if jsonb_typeof(p_blocks) <> 'array' then
    raise exception 'Default shift blocks must be a JSON array';
  end if;

  if jsonb_array_length(p_blocks) > 21 then
    raise exception 'Default shift blocks limit exceeded';
  end if;

  create temporary table if not exists worker_shift_blocks_input (
    idx integer,
    day_of_week integer,
    start_time time without time zone,
    end_time time without time zone,
    timezone text,
    planning_role_id uuid
  ) on commit drop;

  truncate table worker_shift_blocks_input;

  insert into worker_shift_blocks_input (
    idx,
    day_of_week,
    start_time,
    end_time,
    timezone,
    planning_role_id
  )
  select
    row_number() over (),
    (item->>'dayOfWeek')::integer,
    (item->>'startTime')::time,
    (item->>'endTime')::time,
    coalesce(nullif(item->>'timezone', ''), 'America/Santiago'),
    nullif(item->>'planningRoleId', '')::uuid
  from jsonb_array_elements(p_blocks) as item;

  select count(*) into v_count from worker_shift_blocks_input;

  if exists (
    select 1
    from worker_shift_blocks_input
    where day_of_week not between 1 and 7
       or start_time >= end_time
  ) then
    raise exception 'Default shift block contains invalid day or time';
  end if;

  if exists (
    select 1
    from worker_shift_blocks_input input
    where input.planning_role_id is not null
      and not exists (
        select 1
        from public.employee_planning_roles epr
        join public.planning_roles pr on pr.id = epr.planning_role_id
        where epr.tenant_id = v_tenant_id
          and epr.employee_id = v_employee_id
          and epr.planning_role_id = input.planning_role_id
          and pr.is_active = true
      )
  ) then
    raise exception 'Planning role is not assigned to current worker';
  end if;

  if exists (
    select 1
    from worker_shift_blocks_input a
    join worker_shift_blocks_input b
      on a.day_of_week = b.day_of_week
     and a.idx < b.idx
     and a.start_time < b.end_time
     and a.end_time > b.start_time
  ) then
    raise exception 'Default shift blocks cannot overlap';
  end if;

  update public.employee_default_shift_blocks
  set is_active = false,
      updated_by = auth.uid()
  where tenant_id = v_tenant_id
    and employee_id = v_employee_id
    and is_active = true;

  insert into public.employee_default_shift_blocks (
    tenant_id,
    employee_id,
    planning_role_id,
    day_of_week,
    start_time,
    end_time,
    timezone,
    source,
    is_active,
    store_hours_validated,
    outside_store_hours_reason,
    created_by,
    updated_by
  )
  select
    v_tenant_id,
    v_employee_id,
    planning_role_id,
    day_of_week,
    start_time,
    end_time,
    timezone,
    'worker',
    true,
    true,
    null,
    auth.uid(),
    auth.uid()
  from worker_shift_blocks_input;

  return jsonb_build_object('saved', v_count);
end;
$$;

grant execute on function public.set_my_default_shift_blocks(jsonb) to authenticated;

